"""计划量采纳和四账户一组素材分配。"""

from __future__ import annotations

import hashlib
import random
from typing import Any

from models import RunnerInput, period_dict

TARGET_CLASSES = {"付费优秀素材补产-P0", "付费优秀素材补产-P1"}


def _seed(parts: list[str]) -> int:
    return int(hashlib.sha256("|".join(parts).encode()).hexdigest()[:16], 16)


def _chunks(items: list[str], count: int) -> list[list[str]]:
    if count == 0:
        return []
    quotient, remainder = divmod(len(items), count)
    output, offset = [], 0
    for index in range(count):
        size = quotient + (1 if index < remainder else 0)
        output.append(items[offset : offset + size])
        offset += size
    return output


def allocate(
    scope: RunnerInput,
    accounts: list[dict[str, Any]],
    directions: list[dict[str, Any]],
    candidates: dict[tuple[str, str], list[str]],
) -> dict[str, Any]:
    account_ids = sorted(
        {
            str(row["advertiser_id"])
            for row in accounts
            if row.get("账户分类") in {"建议补量", "建议继续放量"}
        }
    )
    chosen: list[str] = []
    shortages: list[dict[str, Any]] = []
    for direction in directions:
        if direction.get("素材方向分类") not in TARGET_CLASSES:
            continue
        key = (str(direction["am_content_id"]), str(direction["material_pattern_name"]))
        quota = max(int(direction.get("采用的计划产量") or 0), 0)
        available = list(dict.fromkeys(candidates.get(key, [])))
        random.Random(_seed([*key, scope.period_current.end_date.isoformat()])).shuffle(
            available
        )
        selected = available[:quota]
        chosen.extend(selected)
        if len(selected) < quota:
            shortages.append(
                {
                    "am_content_id": key[0],
                    "material_pattern_name": key[1],
                    "planned": quota,
                    "available": len(selected),
                    "shortage": quota - len(selected),
                }
            )
    chosen = list(dict.fromkeys(chosen))
    groups = [account_ids[index : index + 4] for index in range(0, len(account_ids), 4)]
    random.Random(
        _seed([scope.product, scope.channel, scope.period_current.end_date.isoformat()])
    ).shuffle(chosen)
    buckets = _chunks(chosen, len(groups))
    return {
        "period_current": period_dict(scope.period_current),
        "period_previous": period_dict(scope.period_previous),
        "details": [
            {"accountId": account_id, "materialId": list(buckets[index])}
            for index, group in enumerate(groups)
            for account_id in group
        ],
        "group_size": 4,
        "selected_material_count": len(chosen),
        "shortages": shortages,
    }

