"""将 ReportView 的各个模型渲染为 HTML 片段。"""

from __future__ import annotations

import html
import json
from typing import Any

from .schema import (
    ArtifactView,
    LimitationView,
    ReportMetadata,
    ReportSection,
    SourceView,
    SummaryCard,
    TableBlock,
)


def escape(value: Any) -> str:
    """统一 HTML 转义，避免组件调用方遗漏。"""

    return html.escape(str(value if value is not None else ""), quote=True)


def _missing_reason(value: Any, column_key: str, column_type: str) -> str:
    if column_key.endswith("__change_rate"):
        return "缺失对比周期，无法计算环比"
    if column_type in {"number", "integer", "percent"}:
        reasons = {
            "cac": "缺少有效获客设备数分母",
            "roi": "缺少现金消耗分母",
            "consume_rate": "缺少参与用户数分母",
            "arppu": "缺少打赏次数分母",
            "retention_rate": "缺少次日留存分母",
            "pull_rate": "缺少有效设备数分母",
        }
        metric = column_key.split("__", 1)[0]
        return reasons.get(metric, "缺少计算所需的分母")
    if column_key in {"url", "material_url"}:
        return "原始结果未提供素材链接"
    return "暂无数据"


def _display(value: Any, column_key: str, column_type: str) -> str:
    if value is None or value == "":
        if column_key.endswith("__change_rate"):
            return "无可比数据"
        if column_type in {"number", "integer", "percent"}:
            return "无法计算"
        if column_key in {"url", "material_url"}:
            return "暂无素材预览信息"
        return "暂无数据"
    if column_type == "percent":
        return f"{float(value) * 100:,.2f}%"
    if column_type == "integer":
        return f"{float(value):,.0f}"
    if column_type == "number":
        return f"{float(value):,.2f}"
    return str(value)


def render_header(metadata: ReportMetadata) -> str:
    tags = "".join(
        f'<span class="gap-scope-tag">{escape(tag)}</span>' for tag in metadata.scope_tags
    )
    generated = (
        f'<p class="gap-eyebrow">Generated {escape(metadata.generated_at)}</p>'
        if metadata.generated_at
        else '<p class="gap-eyebrow">Account &amp; Material Gap Analysis</p>'
    )
    subtitle = f'<p class="gap-subtitle">{escape(metadata.subtitle)}</p>' if metadata.subtitle else ""
    return (
        '<header class="gap-header">'
        f'{generated}<h1 class="gap-title">{escape(metadata.title)}</h1>{subtitle}'
        f'<div class="gap-scope">{tags}</div></header>'
    )


def render_summary_cards(cards: list[SummaryCard]) -> str:
    if not cards:
        return ""
    items = "".join(
        f'<article class="gap-summary-card">'
        f'<p class="gap-card-label">{escape(card.label)}</p>'
        f'<div class="gap-card-value gap-tone-{escape(card.tone)}">{escape(card.value)}</div>'
        f'<p class="gap-card-description">{escape(card.description)}</p>'
        "</article>"
        for card in cards
    )
    return f'<section class="gap-summary" aria-label="核心指标">{items}</section>'


def _ordered_block_columns(columns: list[TableColumn]) -> list[TableColumn]:
    """旧视图可能把环比追加在末尾；渲染前强制同一指标三期物理相邻。"""

    fixed = [column for column in columns if "__" not in column.key]
    metric_names = list(
        dict.fromkeys(
            column.key.split("__", 1)[0]
            for column in columns
            if "__" in column.key
        )
    )
    by_key = {column.key: column for column in columns}
    metric_columns = [
        by_key[f"{metric}__{suffix}"]
        for metric in metric_names
        for suffix in ("previous", "current", "change_rate")
        if f"{metric}__{suffix}" in by_key
    ]
    return [*fixed, *metric_columns]


def render_toc(sections: list[ReportSection]) -> str:
    links = "".join(
        f'<li><a class="gap-toc-link" href="#{escape(section.id)}">{escape(section.title)}</a></li>'
        for section in sections
    )
    return (
        '<aside class="gap-toc" aria-label="报告目录">'
        '<h2 class="gap-toc-title">报告目录</h2>'
        f'<ol class="gap-toc-list">{links}</ol></aside>'
    )


def _table_cell(block: TableBlock, row: dict[str, Any], column_key: str, column_type: str) -> str:
    raw_value = row.get(column_key)
    is_list = isinstance(raw_value, list)
    if is_list:
        # 保留“一行账户对应一个完整数组”的业务结构，由 CSS 负责完整换行展示。
        display = json.dumps(raw_value, ensure_ascii=False, separators=(", ", ": "))
    else:
        display = _display(raw_value, column_key, column_type)
    tone_class = ""
    try:
        tone_number = float(raw_value)
    except (TypeError, ValueError):
        tone_number = None
    tone = block.tone_columns.get(column_key)
    if tone and tone_number is not None and tone_number != 0:
        increased = tone_number > 0
        increase_is_red = tone == "increase-red"
        should_be_red = increased if increase_is_red else not increased
        tone_class = "gap-cell-red" if should_be_red else "gap-cell-green"
    missing_reason = (
        _missing_reason(raw_value, column_key, column_type)
        if not is_list and raw_value in (None, "")
        else ""
    )
    title_attribute = f' title="{escape(missing_reason)}"' if missing_reason else ""
    sort_value = "" if raw_value is None else str(raw_value)
    if column_type == "url" and raw_value:
        content = f'<a href="{escape(raw_value)}" target="_blank" rel="noopener">素材链接</a>'
    else:
        content = escape(display)
    class_values = [tone_class.strip(), "gap-cell-list" if is_list else ""]
    class_value = " ".join(value for value in class_values if value)
    class_attribute = f' class="{escape(class_value)}"' if class_value else ""
    list_attribute = ' data-list="true"' if is_list else ""
    return (
        f'<td data-col="{escape(column_key)}" data-value="{escape(sort_value)}"'
        f'{list_attribute}{title_attribute}'
        f'{class_attribute}>{content}</td>'
    )


def render_table(block: TableBlock) -> str:
    shown_rows = block.rows[: block.preview_limit] if block.preview_limit else block.rows
    ordered_columns = _ordered_block_columns(block.columns)
    columns_json = html.escape(
        json.dumps(
            [
                {
                    "key": column.key,
                    "label": column.label,
                    "type": column.type,
                    "default": column.default,
                }
                for column in ordered_columns
            ],
            ensure_ascii=False,
            separators=(",", ":"),
        ),
        quote=True,
    )
    fixed_columns = [column for column in ordered_columns if "__" not in column.key]
    metric_names = list(dict.fromkeys(
        column.key.split("__", 1)[0]
        for column in ordered_columns
        if "__" in column.key
    ))
    group_headers = "".join(
        f'<th scope="colgroup" rowspan="2" draggable="true" data-col="{escape(column.key)}">'
        f"{escape(column.label)}</th>"
        for column in fixed_columns
    )
    for metric in metric_names:
        metric_columns = [
            column
            for column in ordered_columns
            if column.key.startswith(f"{metric}__")
        ]
        metric_label = metric_columns[0].label.split(" · ", 1)[0]
        current_key = next(
            (column.key for column in metric_columns if column.key.endswith("__current")),
            metric_columns[-1].key,
        )
        group_headers += (
            f'<th scope="colgroup" colspan="{len(metric_columns)}" '
            f'data-group-key="{escape(metric)}" data-sort-key="{escape(current_key)}" '
            f'title="点击按 {escape(metric_label)} 本期列排序">{escape(metric_label)}</th>'
        )
    sub_headers = "".join(
        f'<th scope="col" draggable="true" data-col="{escape(column.key)}">'
        f"{escape(column.label.split(' · ', 1)[-1])}</th>"
        for column in ordered_columns
        if "__" in column.key
    )
    rows = "".join(
        "<tr>"
        + "".join(
            _table_cell(block, row, column.key, column.type)
            for column in ordered_columns
        )
        + "</tr>"
        for row in shown_rows
    )
    preview_note = ""
    if block.preview_limit and block.row_count > block.preview_limit:
        preview_note = (
            f'<p class="gap-table-note">HTML 仅展示前 {block.preview_limit} 行；'
            f"完整 {block.row_count} 行请下载 CSV。</p>"
        )
    if not shown_rows:
        rows = f'<tr><td class="gap-empty" colspan="{len(block.columns)}">暂无数据</td></tr>'
    toolbar = (
        '<div class="gap-toolbar" role="group" '
        f'data-toolbar-for="{escape(block.id)}">'
        '<input class="gap-search" type="search" placeholder="搜索表格内容..." '
        'aria-label="搜索表格内容">'
        '<button type="button" class="gap-button" data-column-set="default">默认列</button>'
        '<button type="button" class="gap-button" data-column-set="all">全量字段</button>'
        '<label class="gap-table-control">显示列数'
        '<select data-column-count>'
        '<option value="5">5 列</option>'
        '<option value="10">10 列</option>'
        '<option value="20">20 列</option>'
        '<option value="50">50 列</option>'
        '<option value="all" selected>全部</option>'
        "</select></label>"
        '<label class="gap-table-control">冻结列'
        f'<input type="number" data-freeze-count value="2" min="0" max="{len(block.columns)}">'
        "</label></div>"
    )
    return (
        f'<article class="gap-block"><h3 class="gap-block-title">{escape(block.title)}</h3>'
        f"{f'<p class=\"gap-block-description\">{escape(block.description)}</p>' if block.description else ''}"
        f"{preview_note}{toolbar}"
        f'<div class="gap-table-shell"><table class="gap-table" data-table-id="{escape(block.id)}" '
        f'data-columns="{columns_json}"><thead><tr class="gap-header-group">{group_headers}</tr>'
        + (f'<tr class="gap-header-sub">{sub_headers}</tr>' if sub_headers else "")
        + "</thead>"
        f"<tbody>{rows}</tbody></table></div></article>"
    )


def render_section(section: ReportSection) -> str:
    blocks = "".join(
        render_table(block.table)
        if block.table
        else f'<p class="gap-note">{escape(block.note)}</p>'
        for block in section.blocks
    )
    description = (
        f'<p class="gap-section-description">{escape(section.description)}</p>'
        if section.description
        else ""
    )
    return (
        f'<section id="{escape(section.id)}" class="gap-section">'
        f'<h2 class="gap-section-title">{escape(section.title)}</h2>{description}{blocks}</section>'
    )


def _artifact_card(artifact: ArtifactView) -> str:
    meta = (
        f'<span class="gap-artifact-meta">{escape(artifact.media_type)} · '
        f"{artifact.row_count} 行</span>"
    )
    if artifact.download_url:
        return (
            f'<a class="gap-artifact" href="{escape(artifact.download_url)}" download>'
            f'<span class="gap-artifact-name">{escape(artifact.title)}</span>{meta}</a>'
        )
    return (
        '<div class="gap-artifact gap-artifact-disabled">'
        f'<span class="gap-artifact-name">{escape(artifact.title)}</span>{meta}'
        '<span class="gap-artifact-meta">下载链接生成失败</span></div>'
    )


def render_artifacts(artifacts: list[ArtifactView]) -> str:
    cards = "".join(_artifact_card(artifact) for artifact in artifacts)
    return f'<div class="gap-artifact-grid">{cards}</div>'


def render_sources(sources: list[SourceView]) -> str:
    cards = ""
    for source in sources:
        artifact_link = (
            f'<a href="#artifact-{escape(source.artifact_id)}">查看结果文件</a>'
            if source.artifact_id
            else "无结果文件"
        )
        query = (
            html.escape(
                json.dumps(source.query_summary, ensure_ascii=False, indent=2),
            )
            if source.query_summary
            else "未记录查询参数"
        )
        cards += (
            f'<details class="gap-source"><summary class="gap-source-summary">'
            f'<span class="gap-source-name">{escape(source.title)}</span>'
            f'<span class="gap-source-meta">{escape(source.tool_name or "本地结果")} · '
            f"{source.row_count} 行</span><span>{artifact_link}</span></summary>"
            f'<div class="gap-source-body"><pre>{query}</pre></div></details>'
        )
    return cards


def render_limitations(limitations: list[LimitationView]) -> str:
    items = "".join(
        f'<p class="gap-limitation">{escape(limitation.text)}</p>'
        for limitation in limitations
    )
    return items or '<p class="gap-limitation">无</p>'

