"""缺口分析报告的独立浏览器交互。"""


REPORT_JS = r"""
(function () {
  'use strict';

  function parseNumber(text) {
    if (text === null || text === undefined || text === '') return null;
    const value = Number(String(text).replace(/[,%\s]/g, ''));
    return Number.isFinite(value) ? value : null;
  }

  function sortIndicator(direction) {
    return direction === 'asc' ? ' ↑' : direction === 'desc' ? ' ↓' : '';
  }

  function headerByKey(table, key) {
    return table.querySelector(`th[data-col="${CSS.escape(key)}"]`);
  }

  function columnIndexByKey(table, key) {
    // 子表头行含有 rowspan/colspan，th.cellIndex 不是数据行物理列号；
    // 必须用同列 td 的 cellIndex，否则两行表头会排到错误列。
    const sampleCell = table.querySelector(`td${cellSelector(key)}`);
    return sampleCell ? sampleCell.cellIndex : -1;
  }

  function applySortIndicators(table) {
    table.querySelectorAll('th[data-col]').forEach((header) => {
      const sort = table._gapState.sorts.find((item) => item.key === header.dataset.col);
      header.classList.toggle('sorted', Boolean(sort));
      header.textContent = (header.dataset.label || '') + sortIndicator(sort?.direction);
    });
  }

  function restoreDefaultOrder(table) {
    if (!table._gapOriginalRows?.length) return;
    const tbody = table.tBodies[0];
    table._gapOriginalRows.forEach((row) => tbody.appendChild(row));
  }

  function sortTable(table, clicked, event) {
    const state = table._gapState;

    if (event.shiftKey) {
      const otherSorts = state.sorts.filter((item) => item.key !== clicked.dataset.col);
      const existing = state.sorts.find((item) => item.key === clicked.dataset.col);
      if (!existing) {
        state.sorts = otherSorts.concat([{ key: clicked.dataset.col, direction: 'asc' }]);
      } else if (existing.direction === 'asc') {
        state.sorts = otherSorts.concat([{ key: clicked.dataset.col, direction: 'desc' }]);
      } else {
        state.sorts = otherSorts;
      }
    } else {
      const existing = state.sorts.find((item) => item.key === clicked.dataset.col);
      if (!existing) {
        state.sorts = [{ key: clicked.dataset.col, direction: 'asc' }];
      } else if (existing.direction === 'asc') {
        state.sorts = [{ key: clicked.dataset.col, direction: 'desc' }];
      } else {
        state.sorts = [];
      }
    }

    applySortIndicators(table);
    if (!state.sorts.length) {
      restoreDefaultOrder(table);
      return;
    }

    const tbody = table.tBodies[0];
    const rows = Array.from(tbody.rows).filter((row) => !row.querySelector('.gap-empty'));
    rows.sort((left, right) => {
      for (const item of state.sorts) {
        const index = columnIndexByKey(table, item.key);
        if (index < 0) continue;
        const leftCell = left.cells[index];
        const rightCell = right.cells[index];
        const leftNumber = parseNumber(leftCell?.dataset.value);
        const rightNumber = parseNumber(rightCell?.dataset.value);
        let result;
        if (leftNumber === null && rightNumber === null) {
          result = 0;
        } else if (leftNumber === null) {
          result = 1;
        } else if (rightNumber === null) {
          result = -1;
        } else {
          result = leftNumber - rightNumber;
        }
        if (result === 0) {
          result = (leftCell?.textContent || '').localeCompare(
            rightCell?.textContent || '', 'zh-CN', { numeric: true }
          );
        }
        if (result !== 0) return result * (item.direction === 'asc' ? 1 : -1);
      }
      return 0;
    });
    rows.forEach((row) => tbody.appendChild(row));
  }

  function columnsJsonValue(table) {
    const raw = table.dataset.columns || '[]';
    try {
      return JSON.parse(raw);
    } catch (error) {
      console.warn('报告列元数据解析失败', error);
      return [];
    }
  }

  function cellSelector(key) {
    return `[data-col="${CSS.escape(key)}"]`;
  }

  function updateGroupHeaders(table, visibleKeys) {
    const visible = new Set(visibleKeys);
    table.querySelectorAll('th[data-group-key]').forEach((header) => {
      const count = (header._gapSegmentKeys || []).filter((key) => visible.has(key)).length;
      header.style.display = count ? '' : 'none';
      if (count) header.colSpan = count;
    });
  }

  function setupHeader(table, header) {
    header.dataset.label = header.textContent;
    header.draggable = true;
    header.title = '点击三态排序；Shift 点击叠加排序；拖拽移动列；右键冻结或隐藏';
    header.addEventListener('click', (event) => sortTable(table, header, event));
    header.addEventListener('dragstart', (event) => {
      window._gapColumnDrag = { table, key: header.dataset.col };
      header.classList.add('dragging');
      event.dataTransfer.effectAllowed = 'move';
      event.dataTransfer.setData('text/plain', header.dataset.col);
    });
    header.addEventListener('dragend', () => {
      window._gapColumnDrag = null;
      table.querySelectorAll('.gap-table th').forEach((item) => {
        item.classList.remove('dragging', 'drop-left', 'drop-right');
      });
    });
    header.addEventListener('dragover', (event) => {
      const drag = window._gapColumnDrag;
      if (!drag || drag.table !== table || drag.key === header.dataset.col) return;
      event.preventDefault();
      event.dataTransfer.dropEffect = 'move';
      table.querySelectorAll('th.drop-left, th.drop-right').forEach((item) => {
        item.classList.remove('drop-left', 'drop-right');
      });
      const rect = header.getBoundingClientRect();
      header.classList.add(event.clientX < rect.left + rect.width / 2 ? 'drop-left' : 'drop-right');
    });
    header.addEventListener('dragleave', () => header.classList.remove('drop-left', 'drop-right'));
    header.addEventListener('drop', (event) => {
      const drag = window._gapColumnDrag;
      if (!drag || drag.table !== table || drag.key === header.dataset.col) return;
      event.preventDefault();
      const rect = header.getBoundingClientRect();
      moveColumn(table, drag.key, header.dataset.col, event.clientX < rect.left + rect.width / 2);
    });
  }

  function setupGroupHeader(table, header) {
    const sortKey = header.dataset.sortKey;
    if (!sortKey) return;
    header.title = '点击按本期列排序；Shift 点击叠加排序';
    header.addEventListener('click', (event) => {
      const target = headerByKey(table, sortKey);
      if (target) sortTable(table, target, event);
    });
  }

  function rebuildHeader(table) {
    const thead = table.tHead;
    const columns = table._gapColumns;
    const groupRow = document.createElement('tr');
    const subRow = document.createElement('tr');
    groupRow.className = 'gap-header-group';
    subRow.className = 'gap-header-sub';
    let segmentBase = null;
    let segmentKeys = [];

    columns.forEach((column) => {
      if (!column.key.includes('__')) {
        segmentBase = null;
        segmentKeys = [];
        const header = document.createElement('th');
        header.rowSpan = 2;
        header.dataset.col = column.key;
        header.scope = 'col';
        header.textContent = column.label;
        setupHeader(table, header);
        groupRow.appendChild(header);
        return;
      }

      const base = column.key.split('__', 1)[0];
      if (base !== segmentBase) {
        segmentBase = base;
        segmentKeys = [];
        const header = document.createElement('th');
        header.dataset.groupKey = base;
            header.scope = 'colgroup';
            header.textContent = column.label.split(' · ', 1)[0];
            header._gapSegmentKeys = segmentKeys;
            setupGroupHeader(table, header);
            groupRow.appendChild(header);
      }
      const header = document.createElement('th');
      header.dataset.col = column.key;
      header.scope = 'col';
      header.textContent = column.label.split(' · ').slice(1).join(' · ') || column.label;
      segmentKeys.push(column.key);
      setupHeader(table, header);
      subRow.appendChild(header);
    });

    thead.replaceChildren(groupRow);
    if (subRow.children.length) thead.appendChild(subRow);
    applySortIndicators(table);
  }

  function moveColumn(table, sourceKey, targetKey, placeBefore) {
    const columns = table._gapColumns.map((column) => column);
    const keys = columns.map((column) => column.key);
    const sourceIndex = keys.indexOf(sourceKey);
    const targetIndex = keys.indexOf(targetKey);
    if (sourceIndex < 0 || targetIndex < 0) return;
    keys.splice(sourceIndex, 1);
    const insertIndex = Math.max(0, keys.indexOf(targetKey) + (placeBefore ? 0 : 1));
    keys.splice(insertIndex, 0, sourceKey);

    const byKey = new Map(columns.map((column) => [column.key, column]));
    table._gapColumns = keys.map((key) => byKey.get(key));
    table._gapState.sorts = table._gapState.sorts.filter((item) => keys.includes(item.key));
    if (table._gapState.mode === 'custom') table._gapState.customKeys = keys.slice();

    rebuildHeader(table);
    Array.from(table.tBodies[0].rows).forEach((row) => {
      keys.forEach((key) => {
        const cell = row.querySelector(cellSelector(key));
        if (cell) row.appendChild(cell);
      });
    });
    applyView(table);
  }

  function updateFreezeColumns(table) {
    const state = table._gapState;
    const visibleColumns = table._gapColumns.filter((column) => {
      const cell = table.querySelector(`td${cellSelector(column.key)}`);
      return cell && cell.style.display !== 'none';
    });
    const frozenCount = Math.max(0, Math.min(state.frozenCount, visibleColumns.length));
    const frozenKeys = new Set(visibleColumns.slice(0, frozenCount).map((column) => column.key));
    let left = 0;

    table._gapColumns.forEach((column) => {
      const cells = Array.from(table.querySelectorAll(cellSelector(column.key)));
      if (!frozenKeys.has(column.key)) {
        cells.forEach((cell) => {
          cell.style.left = '';
          delete cell.dataset.frozen;
        });
        return;
      }
      const sample = table.querySelector(`td${cellSelector(column.key)}`);
      const width = sample ? sample.getBoundingClientRect().width : 0;
      cells.forEach((cell) => {
        cell.style.left = `${left}px`;
        cell.dataset.frozen = '';
      });
      left += width;
    });
    table.classList.toggle('gap-freeze-active', frozenCount > 0);
  }

  function activeKeys(table) {
    const state = table._gapState;
    const columns = table._gapColumns;
    let keys;
    if (state.mode === 'custom') {
      keys = state.customKeys;
    } else if (state.mode === 'all') {
      keys = columns.map((column) => column.key);
    } else {
      keys = columns.filter((column) => column.default).map((column) => column.key);
      if (!keys.length) keys = columns.slice(0, 2).map((column) => column.key);
    }
    return state.limit ? keys.slice(0, state.limit) : keys.slice();
  }

  function applyView(table) {
    const state = table._gapState;
    const visibleKeys = new Set(activeKeys(table));
    table._gapColumns.forEach((column) => {
      const visible = visibleKeys.has(column.key);
      table.querySelectorAll(cellSelector(column.key)).forEach((cell) => {
        cell.style.display = visible ? '' : 'none';
      });
    });
    updateGroupHeaders(table, visibleKeys);
    table.querySelectorAll('[data-column-set]').forEach((button) => {
      button.classList.toggle('active', button.dataset.columnSet === state.mode);
    });
    const freezeInput = table._gapToolbar?.querySelector('[data-freeze-count]');
    if (freezeInput) freezeInput.max = String(table._gapColumns.length);
    updateFreezeColumns(table);
  }

  function initializeTableControls(table) {
    const toolbar = document.querySelector(`[data-toolbar-for="${table.dataset.tableId}"]`);
    table._gapToolbar = toolbar;
    if (!toolbar) return;

    toolbar.querySelectorAll('[data-column-set]').forEach((button) => {
      button.addEventListener('click', () => {
        table._gapState.mode = button.dataset.columnSet;
        table._gapState.customKeys = [];
        applyView(table);
      });
    });

    toolbar.querySelector('[data-column-count]')?.addEventListener('change', (event) => {
      const value = event.target.value;
      table._gapState.limit = value === 'all' ? null : Number(value);
      applyView(table);
    });

    toolbar.querySelector('[data-freeze-count]')?.addEventListener('input', (event) => {
      table._gapState.frozenCount = Math.max(0, Number(event.target.value || 0));
      updateFreezeColumns(table);
    });

    toolbar.querySelector('.gap-search')?.addEventListener('input', (event) => {
      const query = event.target.value.trim().toLowerCase();
      Array.from(table.tBodies[0].rows).forEach((row) => {
        const match = Array.from(row.cells)
          .filter((cell) => cell.style.display !== 'none')
          .some((cell) => cell.textContent.toLowerCase().includes(query));
        row.style.display = match ? '' : 'none';
      });
    });
  }

  function initializeContextMenu(table) {
    table.addEventListener('contextmenu', (event) => {
      const header = event.target.closest('th[data-col]');
      if (!header || !table.contains(header)) return;
      event.preventDefault();
      window._gapContextMenu.targetKey = header.dataset.col;
      window._gapContextMenu.table = table;
      const menu = document.getElementById('gap-context-menu');
      menu.style.left = `${Math.min(event.clientX, window.innerWidth - 155)}px`;
      menu.style.top = `${Math.min(event.clientY, window.innerHeight - 155)}px`;
      menu.classList.add('open');
    });
  }

  function initializeContextMenuActions() {
    const menu = document.getElementById('gap-context-menu');
    if (!menu) return;
    window._gapContextMenu = { table: null, targetKey: null };

    function closeMenu() {
      menu.classList.remove('open');
    }

    menu.addEventListener('click', (event) => {
      const action = event.target.closest('button')?.dataset.action;
      const table = window._gapContextMenu.table;
      const key = window._gapContextMenu.targetKey;
      if (!action || !table || !key) {
        closeMenu();
        return;
      }
      const state = table._gapState;
      if (action === 'hide') {
        state.customKeys = activeKeys(table).filter((item) => item !== key);
        state.mode = 'custom';
        applyView(table);
      } else if (action === 'freeze') {
        state.frozenCount = activeKeys(table).indexOf(key) + 1;
        const input = table._gapToolbar?.querySelector('[data-freeze-count]');
        if (input) input.value = String(state.frozenCount);
        updateFreezeColumns(table);
      } else if (action === 'unfreeze') {
        state.frozenCount = 0;
        const input = table._gapToolbar?.querySelector('[data-freeze-count]');
        if (input) input.value = '0';
        updateFreezeColumns(table);
      } else if (action === 'show') {
        state.mode = 'all';
        state.customKeys = [];
        applyView(table);
      }
      closeMenu();
    });

    document.addEventListener('click', (event) => {
      if (!menu.contains(event.target)) closeMenu();
    });
    document.addEventListener('scroll', closeMenu, true);
  }

  function initializeTable(table) {
    table._gapColumns = columnsJsonValue(table);
    table._gapState = {
      mode: table._gapColumns.some((column) => column.default) ? 'default' : 'all',
      limit: null,
      customKeys: [],
      frozenCount: 2,
      sorts: [],
    };
    table._gapOriginalRows = Array.from(table.tBodies[0].rows);
    rebuildHeader(table);
    initializeTableControls(table);
    initializeContextMenu(table);
    applyView(table);
    window.addEventListener('resize', () => updateFreezeColumns(table), { passive: true });
    if (document.fonts?.ready) document.fonts.ready.then(() => updateFreezeColumns(table));
  }

  function initializeNavigation() {
    const links = Array.from(document.querySelectorAll('.gap-toc-link'));
    const sections = links.map((link) => document.querySelector(link.hash)).filter(Boolean);
    if (!sections.length || !('IntersectionObserver' in window)) return;
    const observer = new IntersectionObserver((entries) => {
      const visible = entries.filter((entry) => entry.isIntersecting)
        .sort((left, right) => left.boundingClientRect.top - right.boundingClientRect.top)[0];
      if (!visible) return;
      links.forEach((link) => link.classList.toggle('active', link.hash === `#${visible.target.id}`));
    }, { rootMargin: '-18% 0px -68% 0px', threshold: 0 });
    sections.forEach((section) => observer.observe(section));
  }

  function initializeBackTop() {
    const button = document.querySelector('.gap-back-top');
    if (!button) return;
    button.addEventListener('click', () => window.scrollTo({ top: 0, behavior: 'smooth' }));
    window.addEventListener('scroll', () => {
      button.classList.toggle('visible', window.scrollY > 500);
    }, { passive: true });
  }

  document.addEventListener('DOMContentLoaded', () => {
    document.querySelectorAll('.gap-table').forEach(initializeTable);
    initializeContextMenuActions();
    initializeNavigation();
    initializeBackTop();
  });
})();
