"""缺口分析报告视图的独立数据契约。"""

from __future__ import annotations

from pathlib import Path
from typing import Any, Literal

from pydantic import BaseModel, ConfigDict, Field, field_validator, model_validator


REPORT_VIEW_SCHEMA_VERSION = "account-asset-gap-report-view/v1"
ColumnTone = Literal["increase-red", "decrease-red"]


class ContractModel(BaseModel):
    """禁止额外字段，避免视图契约被调用方悄悄扩展。"""

    model_config = ConfigDict(extra="forbid")


class ReportMetadata(ContractModel):
    title: str = Field(min_length=1)
    subtitle: str = ""
    generated_at: str | None = None
    scope_tags: list[str] = Field(default_factory=list)


class SummaryCard(ContractModel):
    id: str = Field(min_length=1)
    label: str = Field(min_length=1)
    value: str
    description: str = ""
    tone: Literal["neutral", "positive", "negative"] = "neutral"


class TableColumn(ContractModel):
    key: str = Field(min_length=1)
    label: str = Field(min_length=1)
    type: Literal["text", "number", "integer", "percent", "date", "url"] = "text"
    sticky: bool = False
    default: bool = False


class TableColumnGroup(ContractModel):
    id: str = Field(min_length=1)
    label: str = Field(min_length=1)
    keys: list[str] = Field(min_length=1)


class TableBlock(ContractModel):
    type: Literal["table"] = "table"
    id: str = Field(min_length=1)
    title: str = Field(min_length=1)
    description: str = ""
    row_count: int = Field(ge=0)
    preview_limit: int | None = Field(default=None, ge=1)
    columns: list[TableColumn] = Field(min_length=1)
    column_groups: list[TableColumnGroup] = Field(default_factory=list)
    rows: list[dict[str, Any]] = Field(default_factory=list)
    tone_columns: dict[str, ColumnTone] = Field(default_factory=dict)

    @model_validator(mode="after")
    def validate_columns(self) -> "TableBlock":
        keys = [column.key for column in self.columns]
        duplicate_keys = {key for key in keys if keys.count(key) > 1}
        if duplicate_keys:
            raise ValueError(f"表格 {self.id} 存在重复列：{sorted(duplicate_keys)}")

        known_keys = set(keys)
        shown_rows = self.rows[: self.preview_limit] if self.preview_limit else self.rows
        required_keys = {
            key for row in shown_rows for key in row if row.get(key) not in (None, "")
        }
        missing = required_keys - known_keys
        if missing:
            raise ValueError(f"表格 {self.id} 缺少列定义：{sorted(missing)}")

        group_ids = [group.id for group in self.column_groups]
        if len(group_ids) != len(set(group_ids)):
            raise ValueError(f"表格 {self.id} 存在重复列组")
        for group in self.column_groups:
            unknown = set(group.keys) - known_keys
            if unknown:
                raise ValueError(f"列组 {group.id} 引用了未知列：{sorted(unknown)}")

        unknown_tones = set(self.tone_columns) - known_keys
        if unknown_tones:
            raise ValueError(f"表格 {self.id} 的样式列不存在：{sorted(unknown_tones)}")
        return self

class ReportBlock(ContractModel):
    table: TableBlock | None = None
    note: str | None = None

    @model_validator(mode="after")
    def validate_single_kind(self) -> "ReportBlock":
        if (self.table is None) == (self.note is None):
            raise ValueError("报告块必须且只能包含 table 或 note")
        return self


class ReportSection(ContractModel):
    id: str = Field(min_length=1)
    title: str = Field(min_length=1)
    description: str = ""
    blocks: list[ReportBlock] = Field(default_factory=list)


class ArtifactView(ContractModel):
    id: str = Field(min_length=1)
    title: str = Field(min_length=1)
    dataset_id: str = Field(min_length=1)
    media_type: Literal["text/csv", "application/json"] = "text/csv"
    path: str
    download_url: str | None = None
    row_count: int = Field(ge=0)

    @field_validator("path")
    @classmethod
    def validate_relative_path(cls, value: str) -> str:
        path = Path(value)
        if path.is_absolute() or ".." in path.parts:
            raise ValueError("Artifact 路径必须是报告目录内的相对路径")
        return value

    @field_validator("download_url")
    @classmethod
    def validate_download_url(cls, value: str | None) -> str | None:
        if value is not None and not value.startswith(("http://", "https://")):
            raise ValueError("Artifact 下载地址必须是 HTTP(S) URL")
        return value


class SourceView(ContractModel):
    id: str = Field(min_length=1)
    title: str = Field(min_length=1)
    dataset_id: str = Field(min_length=1)
    tool_name: str = ""
    row_count: int = Field(ge=0)
    artifact_id: str | None = None
    query_summary: dict[str, Any] = Field(default_factory=dict)


class LimitationView(ContractModel):
    id: str = Field(min_length=1)
    text: str = Field(min_length=1)


class ReportView(ContractModel):
    schema_version: Literal["account-asset-gap-report-view/v1"] = (
        REPORT_VIEW_SCHEMA_VERSION
    )
    metadata: ReportMetadata
    summary_cards: list[SummaryCard] = Field(default_factory=list)
    sections: list[ReportSection] = Field(default_factory=list)
    artifacts: list[ArtifactView] = Field(default_factory=list)
    sources: list[SourceView] = Field(default_factory=list)
    limitations: list[LimitationView] = Field(default_factory=list)

    @model_validator(mode="after")
    def validate_contract(self) -> "ReportView":
        section_ids = [section.id for section in self.sections]
        duplicate_sections = {item for item in section_ids if section_ids.count(item) > 1}
        if duplicate_sections:
            raise ValueError(f"报告章节重复：{sorted(duplicate_sections)}")

        table_ids: list[str] = []
        for section in self.sections:
            table_ids.extend(block.table.id for block in section.blocks if block.table)
        duplicate_tables = {item for item in table_ids if table_ids.count(item) > 1}
        if duplicate_tables:
            raise ValueError(f"报告表格重复：{sorted(duplicate_tables)}")

        artifact_ids = [artifact.id for artifact in self.artifacts]
        if len(artifact_ids) != len(set(artifact_ids)):
            raise ValueError("报告 Artifact ID 重复")
        artifact_id_set = set(artifact_ids)
        for source in self.sources:
            if source.artifact_id and source.artifact_id not in artifact_id_set:
                raise ValueError(f"来源 {source.id} 引用了未知 Artifact")

        summary_ids = [card.id for card in self.summary_cards]
        if len(summary_ids) != len(set(summary_ids)):
            raise ValueError("汇总卡片 ID 重复")
        return self

