"""按关键词检索素材标签和内容映射，并生成素材库筛选参数。"""
from __future__ import annotations

import json
import sys
from pathlib import Path
from typing import Any

ROOT = Path(__file__).resolve().parents[1]
APP_IDS = {"TT语音": 1, "欢游": 2, "麦可": 9}


def load_mapping(path: Path) -> list[dict[str, Any]]:
    data = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(data, list) or not all(isinstance(row, dict) for row in data):
        raise ValueError(f"映射文件必须是对象数组：{path}")
    required = {"asset-tags.json": {"name", "id", "layer", "parent_id"}, "asset-contents.json": {"name", "id", "app_id"}}[path.name]
    for row in data:
        if not required <= row.keys():
            raise ValueError(f"映射记录字段不完整：{path}")
    return data


def clean_keywords(value: Any) -> list[str]:
    if value is None:
        return []
    if not isinstance(value, list) or any(not isinstance(item, str) for item in value):
        raise ValueError("关键词必须是字符串数组")
    result: list[str] = []
    for item in value:
        item = item.strip()
        if item and item not in result:
            result.append(item)
    return result


def matches(rows: list[dict[str, str]], keywords: list[str], app_id: int | None = None) -> dict[str, list[dict[str, str]]]:
    result: dict[str, list[dict[str, str]]] = {}
    for keyword in keywords:
        result[keyword] = [
            row for row in rows
            if keyword.casefold() == row["name"].strip().casefold()
            and (app_id is None or row.get("app_id") == app_id)
        ]
    return result


def main(payload: dict[str, Any]) -> dict[str, Any]:
    if not isinstance(payload, dict):
        raise ValueError("输入参数必须是 JSON 对象")
    tag_keywords = clean_keywords(payload.get("tag_keywords"))
    content_keywords = clean_keywords(payload.get("content_keywords"))
    if not tag_keywords and not content_keywords:
        raise ValueError("至少提供一个标签或素材内容关键词")
    app_name = payload.get("app_name")
    if content_keywords and app_name not in APP_IDS:
        raise ValueError("content_keywords 必须提供有效的 app_name：TT语音、欢游或麦可")
    tag_and = payload.get("tag_and", False)
    if not isinstance(tag_and, bool):
        raise ValueError("tag_and 必须是布尔值")

    tag_rows = load_mapping(ROOT / "references/asset-tags.json")
    content_rows = load_mapping(ROOT / "references/asset-contents.json")
    tag_candidates = matches(tag_rows, tag_keywords)
    content_candidates = matches(content_rows, content_keywords, APP_IDS.get(app_name))

    tag_ids: list[str] = []
    for rows in tag_candidates.values():
        for row in rows:
            tag_id = str(row["id"])
            if tag_id not in tag_ids:
                tag_ids.append(tag_id)
    content_ids: list[str] = []
    for rows in content_candidates.values():
        for row in rows:
            content_id = str(row["id"])
            if content_id not in content_ids:
                content_ids.append(content_id)

    filters: dict[str, Any] = {}
    if tag_keywords:
        filters["tag"] = {"tagIds": tag_ids, "andTagId": tag_and}
    if content_keywords:
        filters["contentIds"] = content_ids
    return {
        "filters": filters,
        "candidates": {"tags": tag_candidates, "contents": content_candidates},
    }


if __name__ == "__main__":
    try:
        if len(sys.argv) != 2:
            raise ValueError("用法：search_asset_mappings.py '<JSON>'")
        print(json.dumps(main(json.loads(sys.argv[1])), ensure_ascii=False))
    except (ValueError, json.JSONDecodeError) as exc:
        print(f"错误：{exc}", file=sys.stderr)
        raise SystemExit(2)

