"""
validate_and_build_params.py
────────────────────────────
阶段一：素材筛选前的参数校验与组装

职责：
  1. 按发布模式（COPY_CAMPAIGN / APPEND_AD）校验必填字段、过滤禁止字段
  2. 校验顶层 adAttrStrategy（预算/出价/深度出价/年龄）
  3. 检查所有账户的 appId / adPlatformId 是否一致
  4. 检查共享字段（模板信息等）跨账户是否一致
  5. APPEND_AD 模式下要求 runner 水合 templateAdvertiserId / templateAdvertiserName，
     模板账户可以与目标账户不同
  6. 【平台限制】校验 adPlatformName（目标账户平台）和 tempAdPlatformName（模板账户平台）
     必须均为"广点通"，否则返回 ok=false（runner 校验后的兜底校验）
  7. 将结果写入 <output_dir>/batch_publish_state_1_{timestamp}_{uuid后四位}.json

用法：
  python validate_and_build_params.py '<json_string>' <output_dir>

参数说明：
  json_string  直接传入 JSON 字符串，结构如下：
  {
    "mode": "COPY_CAMPAIGN" | "APPEND_AD",
    "adAttrStrategy": {                      // 可选，顶层统一模板调整
      "budget": {"type": "FIXED_AMOUNT", "value": 500},
      "bid": {"type": "INCREASE_PERCENT", "value": 10},
      "deepBid": {"type": "DECREASE_PERCENT", "value": 10},
      "age": [{"min": 14, "max": 18}]
    },
    "accounts": [
      {
        "advertiserId": "5001",
        "advertiserName": "广点通60账户",
        "appId": 1,
        "adPlatformId": 3,
        "adPlatformName": "广点通",          // 可选，目标账户所属媒体平台名称，传入时校验必须为"广点通"
        // COPY_CAMPAIGN 专用（所有账户一致）：
        "templateAdvertiserId": "48809760",
        "templateAdvertiserName": "广点通60账户",
        "tempAdPlatformName": "广点通",      // 可选，模板账户所属媒体平台名称，传入时校验必须为"广点通"
        "templateCampaignId": 83245111666,
        "templateCampaignName": "53账号深度出价用户增长广告1",
        "templateAdId": 666,
        // APPEND_AD 专用（每个账户可不同）：
        "targetCampaignId": 10001,
        "targetCampaignName": "目标广告组A",
        // APPEND_AD 同样使用 runner 水合的模板账户和 templateAdId
      },
      ...
    ]
  }

  output_dir  必填，指定输出目录，由调用方传入 DATA_DIR/tasks_run

平台限制说明：
  当前版本仅支持广点通平台。
  - adPlatformName：目标账户的媒体平台名称，传入时必须为"广点通"
  - tempAdPlatformName：模板账户的媒体平台名称，传入时必须为"广点通"
  这两个字段为可选，不传时跳过平台校验（主要拦截逻辑在 runner）。
  传入时作为兜底校验，任一账户不符合则返回 ok=false。

输出文件命名：
  batch_publish_state_1_{timestamp}_{uuid后四位}.json
  （index 固定为 1，代表阶段一）

输出（stdout + 写文件）：
{
  "step": 1,
  "ok": true | false,
  "errors": ["错误描述", ...],
  "publishStrategies": [...],   // ok=true 时有值
  "advertiserList": [...],       // ok=true 时有值，供 render_talent_material_filter 使用
  "output_file": "/path/to/batch_publish_state_1_20260521135600_ab12.json"
}
"""

import json
import os
import sys
import uuid
from datetime import datetime
from typing import Any

# ── 平台限制 ────────────────────────────────────────────────────────────────────
SUPPORTED_PLATFORM = "广点通"

# ── 模板属性调整 ────────────────────────────────────────────────────────────────
ADJUSTMENT_TYPES = {"FIXED_AMOUNT", "INCREASE_PERCENT", "DECREASE_PERCENT"}
SUPPORTED_AD_ATTR_KEYS = {"budget", "bid", "deepBid", "age", "deliveryTime", "budgetMode"}

# ── 各模式必填字段 ──────────────────────────────────────────────────────────────
REQUIRED_COPY = [
    "advertiserId", "advertiserName", "appId", "adPlatformId",
    "templateAdvertiserId", "templateAdvertiserName",
    "templateCampaignId", "templateCampaignName",
    "templateAdId",
]
REQUIRED_APPEND = [
    "advertiserId", "advertiserName", "appId", "adPlatformId",
    "targetCampaignId", "targetCampaignName",
    "templateAdvertiserId", "templateAdvertiserName",
    "templateAdId",
]

# ── 各模式禁止字段 ──────────────────────────────────────────────────────────────
FORBIDDEN_COPY   = {"targetCampaignId", "targetCampaignName"}
FORBIDDEN_APPEND = {"templateCampaignId", "templateCampaignName"}

# ── COPY_CAMPAIGN 中应在所有账户间保持一致的字段 ────────────────────────────────
SHARED_COPY_FIELDS = [
    "templateAdvertiserId", "templateAdvertiserName",
    "templateCampaignId", "templateCampaignName",
    "templateAdId",
]
# ── APPEND_AD 中应在所有账户间保持一致的字段 ────────────────────────────────────
SHARED_APPEND_FIELDS = ["templateAdvertiserId", "templateAdvertiserName", "templateAdId"]


def _is_missing(value: Any) -> bool:
    return value is None or (isinstance(value, str) and not value.strip())


def _positive_int(value: Any, field_name: str, errors: list[str]) -> int | None:
    try:
        number = int(value)
    except (TypeError, ValueError):
        errors.append(f"{field_name} 必须是正整数，当前值：{value}")
        return None
    if number <= 0:
        errors.append(f"{field_name} 必须是正整数，当前值：{number}")
        return None
    return number


def _normalize_number(value: Any) -> int | float | None:
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return int(value) if isinstance(value, float) and value.is_integer() else value
    if isinstance(value, str):
        text = value.strip()
        if not text:
            return None
        try:
            number = float(text)
        except ValueError:
            return None
        return int(number) if number.is_integer() else number
    return None


def _validate_adjustment_block(
    block_name: str,
    raw_block: Any,
    errors: list[str],
) -> dict[str, Any] | None:
    if raw_block is None:
        return None
    if not isinstance(raw_block, dict):
        errors.append(f"adAttrStrategy.{block_name} 必须是对象")
        return None
    adj_type = raw_block.get("type")
    if adj_type not in ADJUSTMENT_TYPES:
        errors.append(
            f"adAttrStrategy.{block_name}.type 非法：{adj_type}，可选值为 {sorted(ADJUSTMENT_TYPES)}"
        )
        return None
    value = _normalize_number(raw_block.get("value"))
    if value is None:
        errors.append(f"adAttrStrategy.{block_name}.value 必须是数值")
        return None
    if value <= 0:
        errors.append(f"adAttrStrategy.{block_name}.value 必须大于 0，当前值：{value}")
        return None
    return {"type": adj_type, "value": value}


def _validate_age_ranges(raw_ranges: Any, errors: list[str]) -> list[dict[str, int]] | None:
    if raw_ranges is None:
        return None
    if not isinstance(raw_ranges, list) or not raw_ranges:
        errors.append("adAttrStrategy.age 至少需要 1 个年龄区间")
        return None
    if len(raw_ranges) > 5:
        errors.append("adAttrStrategy.age 最多支持 5 个年龄区间")
        return None

    normalized: list[dict[str, int]] = []
    for index, item in enumerate(raw_ranges):
        label = f"adAttrStrategy.age[{index}]"
        if not isinstance(item, dict):
            errors.append(f"{label} 必须是对象")
            continue
        if item.get("unlimited") is True or str(item.get("label") or "").strip() == "不限":
            errors.append("年龄“不限”与其它年龄区间不能同时选择，需要重新修改")
            continue
        min_age = _positive_int(item.get("min"), f"{label}.min", errors)
        max_age = _positive_int(item.get("max"), f"{label}.max", errors)
        if min_age is None or max_age is None:
            continue
        if min_age < 14:
            errors.append(f"{label}.min 不能小于 14")
        if max_age > 66:
            errors.append(f"{label}.max 不能大于 66")
        if max_age - min_age < 4:
            errors.append(f"{label} 年龄区间至少需要覆盖 5 岁，当前为 {min_age}~{max_age}")
        normalized.append({"min": min_age, "max": max_age})

    sorted_ranges = sorted(normalized, key=lambda item: (item["min"], item["max"]))
    for prev, current in zip(sorted_ranges, sorted_ranges[1:]):
        if current["min"] <= prev["max"]:
            errors.append("修改多个年龄范围时不支持重叠区间，请重新修改年龄范围")
            break
    return sorted_ranges


def _validate_ad_attr_strategy(raw_strategy: Any, errors: list[str]) -> dict[str, Any] | None:
    if raw_strategy is None:
        return None
    if not isinstance(raw_strategy, dict):
        errors.append("adAttrStrategy 必须是对象")
        return None

    for key in raw_strategy:
        if key not in SUPPORTED_AD_ATTR_KEYS:
            errors.append(
                f"adAttrStrategy.{key} 不支持，达人批量发布当前仅支持 budget、bid、deepBid 和 age"
            )

    if not _is_missing(raw_strategy.get("deliveryTime")):
        errors.append("不支持修改投放时间")
    budget_mode = str(raw_strategy.get("budgetMode") or "").strip().upper()
    if budget_mode in {"UNLIMITED", "NO_LIMIT"} or str(raw_strategy.get("budgetMode") or "").strip() == "不限":
        errors.append("预算金额不支持设置为不限")

    normalized: dict[str, Any] = {}
    for key in ("budget", "bid", "deepBid"):
        block = _validate_adjustment_block(key, raw_strategy.get(key), errors)
        if block is not None:
            normalized[key] = block

    age_ranges = _validate_age_ranges(raw_strategy.get("age"), errors)
    if age_ranges is not None:
        normalized["age"] = age_ranges

    return normalized or None


def validate(data: dict) -> dict:
    errors = []
    mode = data.get("mode", "").upper()
    accounts = data.get("accounts", [])
    ad_attr_strategy = _validate_ad_attr_strategy(data.get("adAttrStrategy"), errors)

    # ── 基础检查 ────────────────────────────────────────────────────────────────
    if mode not in ("COPY_CAMPAIGN", "APPEND_AD"):
        errors.append(f"mode 字段无效：'{mode}'，必须是 COPY_CAMPAIGN 或 APPEND_AD")
        return {"step": 1, "ok": False, "errors": errors, "publishStrategies": [], "advertiserList": []}

    if not accounts:
        errors.append("accounts 列表为空，至少需要一个目标账户")
        return {"step": 1, "ok": False, "errors": errors, "publishStrategies": [], "advertiserList": []}

    if mode == "APPEND_AD" and len(accounts) > 1:
        errors.append(f"APPEND_AD 模式仅支持单个目标账户，当前传入了 {len(accounts)} 个账户。")

    required = REQUIRED_COPY if mode == "COPY_CAMPAIGN" else REQUIRED_APPEND
    forbidden = FORBIDDEN_COPY if mode == "COPY_CAMPAIGN" else FORBIDDEN_APPEND
    shared_fields = SHARED_COPY_FIELDS if mode == "COPY_CAMPAIGN" else SHARED_APPEND_FIELDS

    # ── 逐账户校验 ──────────────────────────────────────────────────────────────
    for i, acc in enumerate(accounts):
        label = f"账户[{i}]({acc.get('advertiserId', '?')})"

        # 必填字段检查
        for f in required:
            if not acc.get(f) and acc.get(f) != 0:
                errors.append(f"{label} 缺少必填字段：{f}")

        # 禁止字段检查
        for f in forbidden:
            if f in acc:
                errors.append(f"{label} 包含禁止字段（{mode} 模式不允许）：{f}")

        if "adAttrStrategy" in acc:
            errors.append(f"{label} adAttrStrategy 仅支持顶层统一传入，不支持账户级配置")

        # 平台限制：目标账户 adPlatformName 校验（兜底）
        ad_platform_name = acc.get("adPlatformName")
        if ad_platform_name is not None and ad_platform_name != SUPPORTED_PLATFORM:
            errors.append(
                f"{label} 目标账户所属平台为「{ad_platform_name}」，"
                f"当前批量发布功能仅支持{SUPPORTED_PLATFORM}平台，暂不支持其他媒体平台"
            )

        # 平台限制：模板账户 tempAdPlatformName 校验（兜底）
        temp_platform_name = acc.get("tempAdPlatformName")
        if temp_platform_name is not None and temp_platform_name != SUPPORTED_PLATFORM:
            errors.append(
                f"{label} 模板账户所属平台为「{temp_platform_name}」，"
                f"当前批量发布功能仅支持{SUPPORTED_PLATFORM}平台，暂不支持其他媒体平台"
            )

    # ── appId / adPlatformId 跨账户一致性 ──────────────────────────────────────
    app_ids = {acc.get("appId") for acc in accounts if acc.get("appId") is not None}
    platform_ids = {acc.get("adPlatformId") for acc in accounts if acc.get("adPlatformId") is not None}

    if len(app_ids) > 1:
        errors.append(f"所有账户的 appId 必须一致，当前存在多个值：{app_ids}")
    if len(platform_ids) > 1:
        errors.append(f"所有账户的 adPlatformId 必须一致，当前存在多个值：{platform_ids}")

    # ── 共享字段跨账户一致性 ────────────────────────────────────────────────────
    for f in shared_fields:
        vals = {acc.get(f) for acc in accounts if f in acc}
        if len(vals) > 1:
            errors.append(f"字段 {f} 在所有账户中应保持一致，当前存在多个值：{vals}")

    if errors:
        return {"step": 1, "ok": False, "errors": errors, "publishStrategies": [], "advertiserList": []}

    # ── 组装 publishStrategies ──────────────────────────────────────────────────
    # 注意：所有 ID 类字段统一转为字符串，避免下游工具因类型不匹配报错
    publish_strategies = []
    for acc in accounts:
        entry = {
            "type": mode,
            "appId": acc["appId"],
            "adPlatformId": acc["adPlatformId"],
            "advertiserId": str(acc["advertiserId"]),
            "advertiserName": acc["advertiserName"],
        }
        if mode == "COPY_CAMPAIGN":
            entry["templateAdvertiserId"]   = str(acc["templateAdvertiserId"])
            entry["templateAdvertiserName"] = acc["templateAdvertiserName"]
            entry["templateCampaignId"]     = str(acc["templateCampaignId"])
            entry["templateCampaignName"]   = acc["templateCampaignName"]
            entry["templateAdId"]           = str(acc["templateAdId"])
        else:  # APPEND_AD
            entry["targetCampaignId"]       = str(acc["targetCampaignId"])
            entry["targetCampaignName"]     = acc["targetCampaignName"]
            entry["templateAdId"]           = str(acc["templateAdId"])
            entry["templateAdvertiserId"]   = str(acc["templateAdvertiserId"])
            entry["templateAdvertiserName"] = acc["templateAdvertiserName"]

        template_ad_name = acc.get("templateAdName")
        if template_ad_name is not None and str(template_ad_name).strip():
            entry["templateAdName"] = str(template_ad_name).strip()

        if ad_attr_strategy:
            entry["adAttrStrategy"] = ad_attr_strategy

        publish_strategies.append(entry)

    # ── 组装 advertiserList（供 render_talent_material_filter）──────────────────
    advertiser_list = [
        {
            "appId":          acc["appId"],
            "adPlatformId":   acc["adPlatformId"],
            "advertiserId":   int(acc["advertiserId"]),   # 组件要求 integer
            "advertiserName": acc["advertiserName"],
        }
        for acc in accounts
    ]

    return {
        "step": 1,
        "ok": True,
        "errors": [],
        "publishStrategies": publish_strategies,
        "advertiserList": advertiser_list,
    }


def write_output(result: dict, output_dir: str) -> str:
    """将结果写入文件，返回文件路径。"""
    os.makedirs(output_dir, exist_ok=True)
    timestamp = datetime.now().strftime("%Y%m%d%H%M%S")
    uid_suffix = uuid.uuid4().hex[-4:]
    filename = f"batch_publish_state_1_{timestamp}_{uid_suffix}.json"
    filepath = os.path.join(output_dir, filename)
    with open(filepath, "w", encoding="utf-8") as f:
        json.dump(result, f, ensure_ascii=False, indent=2)
    return filepath


def main():
    if len(sys.argv) < 3:
        print(json.dumps({
            "step": 1,
            "ok": False,
            "errors": ["用法：python validate_and_build_params.py '<json_string>' <output_dir>"],
            "publishStrategies": [], "advertiserList": []
        }, ensure_ascii=False))
        sys.exit(1)

    raw = sys.argv[1]
    output_dir = sys.argv[2]

    try:
        data = json.loads(raw)
    except json.JSONDecodeError as e:
        result = {
            "step": 1,
            "ok": False,
            "errors": [f"JSON 解析失败：{e}"],
            "publishStrategies": [], "advertiserList": []
        }
        print(json.dumps(result, ensure_ascii=False, indent=2))
        sys.exit(1)

    result = validate(data)

    filepath = write_output(result, output_dir)
    result["output_file"] = filepath

    print(json.dumps(result, ensure_ascii=False, indent=2))
    sys.exit(0 if result["ok"] else 1)


if __name__ == "__main__":
    main()

