#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""
CB Strategy Troubleshooting - SQL Generator & Query Executor
用于生成动态 SQL 查询回传策略数据

支持两种参数传递方式：
1. JSON 字符串：python query_builder.py '{"start_date": "2026-04-10", "end_date": "2026-04-16", "advertiser_id": "32448992"}'
2. 命令行参数：python query_builder.py --start-date 2026-04-10 --end-date 2026-04-16 --advertiser-id 32448992
"""

import json
import sys
import argparse
from typing import Dict, List, Any, Optional
from datetime import datetime


class CBStrategyQueryBuilder:
    """回传策略查询构建器"""

    def __init__(self):
        self.base_table = "ods_wefly_cb_strategy_process_data_di"
        self.conditions = []
        self.filters_applied = {}

    def add_date_range_condition(self, start_date: str, end_date: str) -> None:
        """添加日期范围条件"""
        if not start_date or not end_date:
            raise ValueError("start_date 和 end_date 参数不能为空")

        # 验证日期格式
        try:
            start_dt = datetime.strptime(start_date, "%Y-%m-%d")
            end_dt = datetime.strptime(end_date, "%Y-%m-%d")
        except ValueError:
            raise ValueError(f"日期格式错误，应为 YYYY-MM-DD。得到: start_date={start_date}, end_date={end_date}")

        # 验证日期逻辑
        if start_dt > end_dt:
            raise ValueError(f"start_date ({start_date}) 不能晚于 end_date ({end_date})")

        self.conditions.append(f"sum_date >= '{start_date}' AND sum_date <= '{end_date}'")
        self.filters_applied["start_date"] = start_date
        self.filters_applied["end_date"] = end_date

    def add_advertiser_id_condition(self, advertiser_id: str) -> None:
        """添加广告账户ID条件"""
        if not advertiser_id:
            return

        self.conditions.append(f"advertiser_id = '{advertiser_id}'")
        self.filters_applied["advertiser_id"] = advertiser_id

    def add_cp_id_condition(self, cp_id: str) -> None:
        """添加 CP ID 条件，支持模糊匹配"""
        if not cp_id:
            return

        if "%" in cp_id:
            # 模糊匹配
            self.conditions.append(f"cp_id LIKE '{cp_id}'")
            self.filters_applied["cp_id"] = f"{cp_id} (LIKE)"
        else:
            # 精确匹配
            self.conditions.append(f"cp_id = '{cp_id}'")
            self.filters_applied["cp_id"] = cp_id

    def add_source_event_condition(self, source_events: str) -> None:
        """添加源事件条件，支持多个事件"""
        if not source_events:
            return

        events = [e.strip() for e in source_events.split(",")]
        if len(events) == 1:
            self.conditions.append(f"source_event = '{events[0]}'")
        else:
            event_list = "', '".join(events)
            self.conditions.append(f"source_event IN ('{event_list}')")

        self.filters_applied["source_event"] = events

    def add_target_event_condition(self, target_events: str) -> None:
        """添加目标事件条件，支持多个事件"""
        if not target_events:
            return

        events = [e.strip() for e in target_events.split(",")]
        if len(events) == 1:
            self.conditions.append(f"target_event = '{events[0]}'")
        else:
            event_list = "', '".join(events)
            self.conditions.append(f"target_event IN ('{event_list}')")

        self.filters_applied["target_event"] = events

    def add_strategy_id_condition(self, cb_strategy_id: str) -> None:
        """添加策略 ID 条件"""
        if not cb_strategy_id:
            return

        self.conditions.append(f"cb_strategy_id = '{cb_strategy_id}'")
        self.filters_applied["cb_strategy_id"] = cb_strategy_id

    def add_result_ratio_range(self, min_val: Optional[float], max_val: Optional[float]) -> None:
        """添加实际转化率范围条件"""
        if min_val is not None:
            if not (0 <= min_val <= 1):
                raise ValueError(f"result_ratio_min 应在 [0, 1] 范围内，得到: {min_val}")
            self.conditions.append(f"result_ratio >= {min_val}")
            self.filters_applied["result_ratio_min"] = min_val

        if max_val is not None:
            if not (0 <= max_val <= 1):
                raise ValueError(f"result_ratio_max 应在 [0, 1] 范围内，得到: {max_val}")
            self.conditions.append(f"result_ratio <= {max_val}")
            self.filters_applied["result_ratio_max"] = max_val

    def add_setting_ratio_range(self, min_val: Optional[float], max_val: Optional[float]) -> None:
        """添加目标转化率范围条件"""
        if min_val is not None:
            if not (0 <= min_val <= 100):
                raise ValueError(f"setting_ratio_min 应在 [0, 100] 范围内，得到: {min_val}")
            self.conditions.append(f"setting_ratio >= {min_val}")
            self.filters_applied["setting_ratio_min"] = min_val

        if max_val is not None:
            if not (0 <= max_val <= 100):
                raise ValueError(f"setting_ratio_max 应在 [0, 100] 范围内，得到: {max_val}")
            self.conditions.append(f"setting_ratio <= {max_val}")
            self.filters_applied["setting_ratio_max"] = max_val

    def add_total_count_range(self, min_val: Optional[int], max_val: Optional[int]) -> None:
        """添加总尝试数范围条件"""
        if min_val is not None:
            if min_val < 0:
                raise ValueError(f"total_count_min 不能为负数，得到: {min_val}")
            self.conditions.append(f"total_count >= {min_val}")
            self.filters_applied["total_count_min"] = min_val

        if max_val is not None:
            if max_val < 0:
                raise ValueError(f"total_count_max 不能为负数，得到: {max_val}")
            self.conditions.append(f"total_count <= {max_val}")
            self.filters_applied["total_count_max"] = max_val

    def build_sql(self) -> str:
        """构建完整的 SQL 查询语句"""
        if not self.conditions:
            raise ValueError("至少需要一个查询条件")

        where_clause = " AND ".join(self.conditions)
        sql = f"SELECT * FROM {self.base_table} WHERE {where_clause}"

        return sql

    def get_filters(self) -> Dict[str, Any]:
        """获取已应用的筛选条件"""
        return self.filters_applied


def parse_input_from_dict(input_data: Dict[str, Any]) -> CBStrategyQueryBuilder:
    """从字典解析用户输入并构建查询"""

    builder = CBStrategyQueryBuilder()

    # 必填参数 - 日期范围
    start_date = input_data.get("start_date")
    end_date = input_data.get("end_date")
    if not start_date or not end_date:
        raise ValueError("缺少必填参数: start_date 和 end_date")

    builder.add_date_range_condition(start_date, end_date)

    # 可选参数 - 基础筛选
    if "advertiser_id" in input_data:
        builder.add_advertiser_id_condition(input_data["advertiser_id"])

    if "cp_id" in input_data:
        builder.add_cp_id_condition(input_data["cp_id"])

    if "source_event" in input_data:
        builder.add_source_event_condition(input_data["source_event"])

    if "target_event" in input_data:
        builder.add_target_event_condition(input_data["target_event"])

    if "cb_strategy_id" in input_data:
        builder.add_strategy_id_condition(input_data["cb_strategy_id"])

    # 可选参数 - 数值范围筛选
    result_ratio_min = input_data.get("result_ratio_min")
    result_ratio_max = input_data.get("result_ratio_max")
    if result_ratio_min is not None or result_ratio_max is not None:
        builder.add_result_ratio_range(result_ratio_min, result_ratio_max)

    setting_ratio_min = input_data.get("setting_ratio_min")
    setting_ratio_max = input_data.get("setting_ratio_max")
    if setting_ratio_min is not None or setting_ratio_max is not None:
        builder.add_setting_ratio_range(setting_ratio_min, setting_ratio_max)

    total_count_min = input_data.get("total_count_min")
    total_count_max = input_data.get("total_count_max")
    if total_count_min is not None or total_count_max is not None:
        builder.add_total_count_range(total_count_min, total_count_max)

    return builder


def parse_input_from_args(args: List[str]) -> CBStrategyQueryBuilder:
    """从命令行参数解析用户输入并构建查询"""

    parser = argparse.ArgumentParser(description="CB Strategy Troubleshooting Query Builder")

    # 必填参数 - 日期范围
    parser.add_argument("--start-date", dest="start_date", required=True, help="查询起始日期，格式 YYYY-MM-DD")
    parser.add_argument("--end-date", dest="end_date", required=True, help="查询结束日期，格式 YYYY-MM-DD")

    # 可选参数 - 基础筛选
    parser.add_argument("--advertiser-id", dest="advertiser_id", help="广告账户ID")
    parser.add_argument("--cp-id", dest="cp_id", help="CP/客户ID，支持模糊匹配")
    parser.add_argument("--source-event", dest="source_event", help="源事件类型，多个用逗号分隔")
    parser.add_argument("--target-event", dest="target_event", help="目标事件类型，多个用逗号分隔")
    parser.add_argument("--cb-strategy-id", dest="cb_strategy_id", help="回传策略ID")

    # 可选参数 - 数值范围筛选
    parser.add_argument("--result-ratio-min", dest="result_ratio_min", type=float, help="实际转化率最小值 [0, 1]")
    parser.add_argument("--result-ratio-max", dest="result_ratio_max", type=float, help="实际转化率最大值 [0, 1]")
    parser.add_argument("--setting-ratio-min", dest="setting_ratio_min", type=float, help="目标转化率最小值 [0, 100]")
    parser.add_argument("--setting-ratio-max", dest="setting_ratio_max", type=float, help="目标转化率最大值 [0, 100]")
    parser.add_argument("--total-count-min", dest="total_count_min", type=int, help="总尝试数最小值")
    parser.add_argument("--total-count-max", dest="total_count_max", type=int, help="总尝试数最大值")

    parsed_args = parser.parse_args(args)

    # 转换为字典，过滤掉 None 值
    input_data = {k: v for k, v in vars(parsed_args).items() if v is not None}

    return parse_input_from_dict(input_data)


def main():
    """主函数 - 支持两种参数传递方式"""

    try:
        # 尝试判断参数类型
        if len(sys.argv) < 2:
            print(json.dumps({
                "status": "error",
                "message": "缺少输入参数。支持两种方式：\n1. JSON: python query_builder.py '{\"start_date\": \"2026-04-10\", \"end_date\": \"2026-04-16\"}'\n2. 命令行: python query_builder.py --start-date 2026-04-10 --end-date 2026-04-16"
            }, ensure_ascii=False))
            sys.exit(1)

        # 方式1：检查是否为 JSON 字符串（以 { 开头）
        if sys.argv[1].startswith("{"):
            try:
                input_data = json.loads(sys.argv[1])
                builder = parse_input_from_dict(input_data)
            except json.JSONDecodeError as e:
                print(json.dumps({
                    "status": "error",
                    "message": f"JSON 解析错误: {str(e)}"
                }, ensure_ascii=False))
                sys.exit(1)

        # 方式2：命令行参数（以 -- 开头）
        elif sys.argv[1].startswith("--"):
            builder = parse_input_from_args(sys.argv[1:])

        # 方式3：单个参数作为 JSON（兼容旧版本）
        else:
            try:
                input_data = json.loads(sys.argv[1])
                builder = parse_input_from_dict(input_data)
            except json.JSONDecodeError:
                print(json.dumps({
                    "status": "error",
                    "message": f"无法解析参数: {sys.argv[1]}。请使用 JSON 格式或命令行参数"
                }, ensure_ascii=False))
                sys.exit(1)

        # 构建查询
        query_sql = builder.build_sql()
        filters = builder.get_filters()

        # 返回结果
        result = {
            "status": "success",
            "query_sql": query_sql,
            "filters_applied": filters,
            "message": "SQL 生成成功，可用于后续查询"
        }

        print(json.dumps(result, ensure_ascii=False, indent=2))

    except ValueError as e:
        print(json.dumps({
            "status": "error",
            "message": str(e)
        }, ensure_ascii=False))
        sys.exit(1)
    except Exception as e:
        print(json.dumps({
            "status": "error",
            "message": f"未知错误: {str(e)}"
        }, ensure_ascii=False))
        sys.exit(1)


if __name__ == "__main__":
    main()

