"""Print a new or validated attribution submission request ID."""

from __future__ import annotations

import re
import sys
from uuid import uuid4


REQUEST_ID_PATTERN = re.compile(r"^attr-[0-9a-f]{32}$")


def get_or_create_request_id(existing_request_id: str | None = None) -> str:
    if existing_request_id is None:
        return f"attr-{uuid4().hex}"
    if REQUEST_ID_PATTERN.fullmatch(existing_request_id) is None:
        raise ValueError("existing_request_id must match ^attr-[0-9a-f]{32}$")
    return existing_request_id


def main() -> None:
    if len(sys.argv) > 2:
        raise ValueError("expected at most one existing_request_id argument")
    existing_request_id = sys.argv[1] if len(sys.argv) == 2 else None
    print(get_or_create_request_id(existing_request_id))


if __name__ == "__main__":
    main()

