"""两期指标聚合、账户分类和素材方向分类。"""

from __future__ import annotations

import math
from collections import defaultdict
from datetime import date
from typing import Any, Iterable

from models import RunnerInput

SUM_FIELDS = {
    "cost": "cost_total",
    "cash_cost": "cash_cost_total",
    "obtain_device_cnt": "obtain_total",
    "remove_big_obtain_device_cnt": "remove_obtain_total",
    "remove_big_pull_device_cnt": "remove_pull_total",
    "remove_big_obtain_small_profit_amt_month1": "profit_total",
    "remove_big_obtain_small_consume_amt_month1": "consume_amt_total",
    "remove_big_obtain_small_consume_cnt_month1": "consume_cnt_total",
    "remove_big_obtain_small_user_cnt": "user_total",
}


def _num(value: Any) -> float:
    try:
        return float(str(value or "0").replace(",", ""))
    except ValueError:
        return 0.0


def _clean_id(value: Any) -> str:
    text = str(value or "").strip()
    return text[:-2] if text.endswith(".0") and text[:-2].isdigit() else text


def _period(row: dict[str, Any], scope: RunnerInput) -> str | None:
    raw = str(row.get("event_date") or row.get("month") or row.get("月份") or "")
    if raw.startswith(scope.period_previous.start_date.isoformat()[:7]):
        return "previous"
    if raw.startswith(scope.period_current.start_date.isoformat()[:7]):
        return "current"
    try:
        value = date.fromisoformat(raw[:10])
    except ValueError:
        return None
    if scope.period_previous.start_date <= value <= scope.period_previous.end_date:
        return "previous"
    if scope.period_current.start_date <= value <= scope.period_current.end_date:
        return "current"
    return None


def _ratio(numerator: float, denominator: float) -> float | None:
    return numerator / denominator if denominator else None


def _aggregate(
    rows: Iterable[dict[str, Any]], keys: tuple[str, ...], scope: RunnerInput
) -> list[dict[str, Any]]:
    grouped: dict[tuple[str, ...], dict[str, Any]] = {}
    for source in rows:
        period = _period(source, scope)
        if not period:
            continue
        key = tuple(
            (
                _clean_id(source.get(field))
                if field.endswith("_id")
                else str(source.get(field) or "")
            )
            for field in keys
        )
        if not all(key):
            continue
        row = grouped.setdefault(key, dict(zip(keys, key)))
        for source_field, output_field in SUM_FIELDS.items():
            name = f"{output_field}__{period}"
            row[name] = _num(row.get(name)) + _num(source.get(source_field))
    for row in grouped.values():
        for period in ("previous", "current"):
            for output_field in SUM_FIELDS.values():
                row.setdefault(f"{output_field}__{period}", 0.0)
            row[f"cac__{period}"] = _ratio(
                row[f"cost_total__{period}"], row[f"remove_obtain_total__{period}"]
            )
            row[f"roi__{period}"] = _ratio(
                row[f"profit_total__{period}"], row[f"cash_cost_total__{period}"]
            )
            row[f"consume_rate__{period}"] = _ratio(
                row[f"consume_cnt_total__{period}"], row[f"user_total__{period}"]
            )
            row[f"arppu__{period}"] = _ratio(
                row[f"consume_amt_total__{period}"], row[f"consume_cnt_total__{period}"]
            )
    return list(grouped.values())


def _scale(
    previous: float, current: float, scope: RunnerInput, stable: str = "正常波动"
) -> str:
    prev_days = (
        scope.period_previous.end_date - scope.period_previous.start_date
    ).days + 1
    curr_days = (
        scope.period_current.end_date - scope.period_current.start_date
    ).days + 1
    previous_daily, current_daily = previous / prev_days, current / curr_days
    if previous_daily <= 0:
        return "增量明显" if current_daily > 0 else stable
    change = current_daily / previous_daily - 1
    if change >= 0.2:
        return "增量明显"
    if change >= 0:
        return stable
    return "小幅下滑" if change > -0.2 else "掉量明显"


def _decline_within(previous: Any, current: Any, limit: float) -> bool:
    if previous is None or current is None:
        return False
    return current >= 0 if previous == 0 else (previous - current) / previous <= limit


def _daily_metrics(scope: RunnerInput, rows: list[dict[str, Any]]):
    account = defaultdict(lambda: defaultdict(float))
    direction = defaultdict(lambda: defaultdict(float))
    account_materials = defaultdict(set)
    direction_materials = defaultdict(set)
    for row in rows:
        period = _period(row, scope)
        if not period:
            continue
        account_id = _clean_id(row.get("advertiser_id"))
        if account_id:
            bucket = account[(account_id, period)]
            for key in ("obtain_device_cnt", "obtain_remain_day2", "pull_device_cnt"):
                bucket[key] += _num(row.get(key))
            bucket[str(row.get("am_type_name") or "")] += _num(
                row.get("obtain_device_cnt")
            )
            if _num(row.get("cost")) > 0 and _clean_id(row.get("material_id")):
                account_materials[(account_id, period)].add(
                    _clean_id(row.get("material_id"))
                )
        if scope.material_type not in str(row.get("am_type_name") or ""):
            continue
        key = (
            _clean_id(row.get("am_content_id")),
            str(row.get("material_pattern_name") or ""),
            period,
        )
        if key[0] and key[1]:
            direction[key]["denominator"] += _num(
                row.get("remove_big_obtain_device_cnt")
            )
            direction[key]["remain"] += _num(row.get("obtain_remain_day2"))
            direction[key]["pull"] += _num(row.get("pull_device_cnt"))
            if _num(row.get("cost")) > 0 and _clean_id(row.get("material_id")):
                direction_materials[key].add(_clean_id(row.get("material_id")))
    return account, direction, account_materials, direction_materials


def _goal_count(
    row: dict[str, Any], period: str, obtain_field: str, threshold: int
) -> int:
    return sum(
        [
            (row.get(f"roi__{period}") or 0) > 0.13,
            (row.get(f"consume_rate__{period}") or 0) > 0.023,
            (row.get(f"arppu__{period}") or 0) > 250,
            row.get(f"cac__{period}") is not None and row[f"cac__{period}"] < 30,
            (row.get(f"retention_rate__{period}") or 0) > 0.36,
            (row.get(f"pull_rate__{period}") or 0) > 0.30,
            (row.get(f"{obtain_field}__{period}") or 0) > threshold,
        ]
    )


def _add_changes(row: dict[str, Any]) -> None:
    """为每个同时存在两期数值的字段补齐环比，避免全量字段出现口径缺失。"""

    metric_names = []
    for key in list(row):
        for suffix in ("__previous", "__current"):
            if not key.endswith(suffix):
                continue
            metric = key[: -len(suffix)]
            if metric not in metric_names:
                metric_names.append(metric)
    for field in metric_names:
        row.setdefault(f"{field}__previous", None)
        row.setdefault(f"{field}__current", None)
        previous = row[f"{field}__previous"]
        current = row[f"{field}__current"]
    for field in metric_names:
        previous = row.get(f"{field}__previous")
        current = row.get(f"{field}__current")
        if previous is None or current is None:
            change = None
        else:
            previous_number, current_number = _num(previous), _num(current)
            if previous_number == 0:
                # 0 -> 0 是真实的零环比；0 -> 正数才是无有效分母。
                change = 0.0 if current_number == 0 else None
            else:
                change = (current_number - previous_number) / previous_number
        row[f"{field}__change_rate"] = change


def analyze(
    scope: RunnerInput, sources: dict[str, list[dict[str, Any]]]
) -> dict[str, list[dict[str, Any]]]:
    daily = sources.get("material_daily", [])
    account_daily, direction_daily, account_ids, direction_ids = _daily_metrics(
        scope, daily
    )
    accounts = _aggregate(
        sources.get("account_monthly", []), ("advertiser_id", "advertiser_name"), scope
    )
    material_source = [
        row
        for row in sources.get("material_monthly", [])
        if scope.material_type in str(row.get("am_type_name") or "")
    ]
    direction_keys = (
        "am_content_id",
        "am_content_name",
        "material_pattern_name",
        "am_type_name",
    )
    material_keys = (*direction_keys, "material_id", "material_name", "url")
    directions = _aggregate(material_source, direction_keys, scope)
    materials = _aggregate(material_source, material_keys, scope)

    for row in accounts:
        account_id = row["advertiser_id"]
        for period in ("previous", "current"):
            extra = account_daily[(account_id, period)]
            denominator = extra["obtain_device_cnt"]
            row[f"retention_rate__{period}"] = _ratio(
                extra["obtain_remain_day2"], denominator
            )
            row[f"pull_rate__{period}"] = _ratio(extra["pull_device_cnt"], denominator)
            row[f"material_count__{period}"] = len(account_ids[(account_id, period)])
            row[f"image_obtain__{period}"] = extra["图片"]
            row[f"video_obtain__{period}"] = extra["视频"]
        scale = _scale(
            row["obtain_total__previous"], row["obtain_total__current"], scope
        )
        goals = _goal_count(row, "current", "obtain_total", 9)
        good = (
            row["obtain_total__current"] >= 10
            and (row["cac__current"] or math.inf) < 30
            and goals >= 3
            and (row["roi__current"] or 0) > 0.08
        )
        image, video = row["image_obtain__current"], row["video_obtain__current"]
        if image == video == 0:
            strategy = "无素材获客"
        elif video == 0:
            strategy = "定投图片"
        elif image == 0:
            strategy = "定投视频"
        elif image == video:
            strategy = "通用素材获客"
        else:
            strategy = "主投图片" if image > video else "主投视频"
        previous_count = row["material_count__previous"]
        gap = (
            "无法判断"
            if previous_count == 0
            else (
                "存在素材缺口"
                if row["material_count__current"] / previous_count <= 0.7
                else "不存在素材缺口"
            )
        )
        row.update(
            {
                "账户类型": (
                    "停投账户"
                    if row["cost_total__current"] == 0
                    else "新增账户" if row["cost_total__previous"] == 0 else "正常账户"
                ),
                "账户量级": scale,
                "账户样本量": "充足" if row["obtain_total__current"] >= 10 else "不足",
                "账户素材策略": strategy,
                "账户素材缺口": gap,
                "账户七项目标达标数": goals,
                "账户效果": (
                    "效果较好" if good else "效果中等" if goals >= 2 else "效果较差"
                ),
            }
        )
        row["账户分类"] = (
            "建议补量"
            if good and scale in {"小幅下滑", "掉量明显"}
            else "建议继续放量" if good else "控制扩量"
        )
        row["建议动作"] = {
            "建议补量": "建议补量并关注素材供给",
            "建议继续放量": "建议继续放量并关注成本与付费质量",
            "控制扩量": "控制扩量并修复未达标指标",
        }[row["账户分类"]]
        _add_changes(row)

    for row in directions:
        for period in ("previous", "current"):
            extra = direction_daily[
                (row["am_content_id"], row["material_pattern_name"], period)
            ]
            row[f"retention_rate__{period}"] = _ratio(
                extra["remain"], extra["denominator"]
            )
            row[f"pull_rate__{period}"] = _ratio(extra["pull"], extra["denominator"])
            row[f"material_count__{period}"] = len(
                direction_ids[
                    (row["am_content_id"], row["material_pattern_name"], period)
                ]
            )
        scale = _scale(
            row["remove_obtain_total__previous"],
            row["remove_obtain_total__current"],
            scope,
            "小幅上升",
        )
        roi_ok = all((row[f"roi__{p}"] or 0) > 0.08 for p in ("previous", "current"))
        pay10 = _decline_within(
            row["consume_rate__previous"], row["consume_rate__current"], 0.1
        ) and _decline_within(row["arppu__previous"], row["arppu__current"], 0.1)
        pay20 = _decline_within(
            row["consume_rate__previous"], row["consume_rate__current"], 0.2
        ) and _decline_within(row["arppu__previous"], row["arppu__current"], 0.2)
        paid = (
            "优秀"
            if roi_ok and pay10
            else (
                "稳定"
                if any((row[f"roi__{p}"] or 0) > 0.06 for p in ("previous", "current"))
                and pay20
                else "下滑"
            )
        )
        goals = _goal_count(row, "current", "remove_obtain_total", 100)
        effect = "效果较好" if goals >= 4 else "效果中等" if goals >= 2 else "效果较差"
        if paid not in {"优秀", "稳定"}:
            classification, plan = "停止常规生产", 0
        elif effect in {"效果较好", "效果中等"} and scale in {"小幅下滑", "掉量明显"}:
            classification = "付费优秀素材补产-P0"
            plan = math.ceil(
                max(
                    row["remove_obtain_total__previous"]
                    - row["remove_obtain_total__current"],
                    0,
                )
                / 80
            )
        elif effect in {"效果较好", "效果中等"} and scale in {"增量明显", "小幅上升"}:
            classification = "付费优秀素材补产-P1"
            plan = math.ceil(
                (row["material_count__previous"] + row["material_count__current"]) / 2
            )
        else:
            classification, plan = "付费优秀素材补产-P2", None
        row.update(
            {
                "素材方向量级标签": scale,
                "素材方向付费标签": paid,
                "素材方向效果标签": effect,
                "素材方向分类": classification,
                "系统建议产量": plan,
                "采用的计划产量": plan,
            }
        )
        _add_changes(row)

    for row in materials:
        _add_changes(row)

    accounts.sort(
        key=lambda row: (
            -_num(row.get("cost_total__previous")),
            -_num(row.get("cost_total__current")),
        )
    )
    directions.sort(
        key=lambda row: (
            -_num(row.get("cost_total__previous")),
            -_num(row.get("cost_total__current")),
        )
    )
    materials.sort(
        key=lambda row: (
            -_num(row.get("cost_total__previous")),
            -_num(row.get("cost_total__current")),
        )
    )
    references = _reference_materials(materials, directions)
    return {
        "accounts": accounts,
        "directions": directions,
        "materials": materials,
        "reference_materials": references,
    }


def _combined(row: dict[str, Any], field: str) -> float:
    return _num(row.get(f"{field}__previous")) + _num(row.get(f"{field}__current"))


def _reference_row(row: dict[str, Any], category: str, rank: int) -> dict[str, Any]:
    cash = _combined(row, "cash_cost_total")
    return {
        **row,
        "参考素材分类": category,
        "排名": rank,
        "两期合计获客": _combined(row, "remove_obtain_total"),
        "两期合计利润": _combined(row, "profit_total"),
        "两期合计ROI": _ratio(_combined(row, "profit_total"), cash),
    }


def _reference_materials(
    materials: list[dict[str, Any]], directions: list[dict[str, Any]]
) -> list[dict[str, Any]]:
    """确定性生成方向优质、方向差素材和两期全量利润 TOP5。"""

    allowed = {
        (str(row["am_content_id"]), str(row["material_pattern_name"]))
        for row in directions
        if row.get("素材方向分类")
        in {"付费优秀素材补产-P0", "付费优秀素材补产-P1", "付费优秀素材补产-P2"}
    }
    by_direction: dict[tuple[str, str], list[dict[str, Any]]] = defaultdict(list)
    for row in materials:
        by_direction[
            (str(row["am_content_id"]), str(row["material_pattern_name"]))
        ].append(row)

    output: list[dict[str, Any]] = []
    for key in sorted(allowed):
        rows = by_direction.get(key, [])
        qualified = []
        for row in rows:
            cash = _combined(row, "cash_cost_total")
            roi = _ratio(_combined(row, "profit_total"), cash)
            if (
                _combined(row, "cost_total") > 0
                and _combined(row, "remove_obtain_total") >= 10
                and (roi or 0) > 0.10
            ):
                qualified.append(row)
        for rank, row in enumerate(
            sorted(
                qualified,
                key=lambda item: _combined(item, "profit_total"),
                reverse=True,
            )[:5],
            1,
        ):
            output.append(_reference_row(row, "方向内优质TOP5", rank))

        high_volume = sorted(
            rows, key=lambda item: _combined(item, "remove_obtain_total"), reverse=True
        )[:5]
        poor = [
            row
            for row in high_volume
            if (
                _ratio(
                    _combined(row, "profit_total"), _combined(row, "cash_cost_total")
                )
                or 0
            )
            < 0.05
        ]
        for rank, row in enumerate(poor, 1):
            output.append(_reference_row(row, "跑量大但付费差", rank))

    for period, label in (
        ("previous", "上一周期利润TOP5"),
        ("current", "本周期利润TOP5"),
    ):
        ranked = sorted(
            materials,
            key=lambda row: _num(row.get(f"profit_total__{period}")),
            reverse=True,
        )[:5]
        for rank, row in enumerate(ranked, 1):
            output.append(_reference_row(row, label, rank))
    return output

