"""生成 P0/P1 素材请求，并校验素材库 MCP 返回的结果。"""

from __future__ import annotations

import csv
import json
import re
import shutil
from calendar import monthrange
from datetime import date, timedelta
from pathlib import Path
from typing import Any

from models import RunnerInput


TARGET_CLASSES = {"付费优秀素材补产-P0", "付费优秀素材补产-P1"}


def _three_month_window(scope: RunnerInput) -> tuple[str, str]:
    """以本周期结束日次日为右边界，生成最多三个自然月的半开区间。"""

    end_exclusive = scope.period_current.end_date + timedelta(days=1)
    index = end_exclusive.year * 12 + end_exclusive.month - 1 - 3
    year, month_offset = divmod(index, 12)
    start = date(
        year,
        month_offset + 1,
        min(end_exclusive.day, monthrange(year, month_offset + 1)[1]),
    )
    return start.isoformat(), end_exclusive.isoformat()


def _orientation(pattern: str) -> str | None:
    normalized = pattern.replace("：", ":").replace("×", "*")
    if "横" in normalized or "16:9" in normalized or "16*9" in normalized:
        return "horizontal"
    if "竖" in normalized or "9:16" in normalized or "9*16" in normalized:
        return "vertical"
    return None


def _safe_filename(value: str) -> str:
    return re.sub(r"[^\w.-]+", "-", value, flags=re.UNICODE).strip("-.") or "file"


def _target_directions(directions: list[dict[str, Any]]) -> list[dict[str, Any]]:
    return [
        row
        for row in directions
        if row.get("素材方向分类") in TARGET_CLASSES
        and int(row.get("采用的计划产量") or 0) > 0
    ]


def build_material_requests(
    scope: RunnerInput,
    directions: list[dict[str, Any]],
) -> tuple[list[dict[str, Any]], list[str]]:
    """生成可由 Agent 原样调用的素材库 MCP 请求。"""

    start, end = _three_month_window(scope)
    requests: list[dict[str, Any]] = []
    limitations: list[str] = []
    material_type = "video" if scope.material_type == "视频" else "image"

    for index, direction in enumerate(_target_directions(directions), start=1):
        pattern = str(direction["material_pattern_name"])
        orientation = _orientation(pattern)
        if not orientation:
            limitations.append(
                f"方向“{direction['am_content_name']} + {pattern}”缺少横竖版映射"
            )
            continue

        plan = int(direction["采用的计划产量"])
        filters: dict[str, Any] = {
            "appName": scope.product,
            "contentIds": [str(direction["am_content_id"])],
            "startTime": start,
            "endTime": end,
            # 新素材库 MCP 原生支持“我未使用”和可见范围筛选。
            "useStatus": "2",
            "materialScope": "2",
        }
        if scope.designer_groups:
            filters["designerGroups"] = scope.designer_groups
        if scope.designer_names:
            filters["designerNames"] = scope.designer_names

        request_id = f"material-{index}-{direction['am_content_id']}-{orientation}"
        requests.append(
            {
                "request_id": request_id,
                "tool_name": "agent_tool_asset_library_selector",
                "arguments": {
                    "reqParam": {
                        "asset_type": material_type,
                        "filters": filters,
                    }
                },
                "direction": {
                    "am_content_id": str(direction["am_content_id"]),
                    "am_content_name": direction["am_content_name"],
                    "material_pattern_name": pattern,
                    "素材方向分类": direction["素材方向分类"],
                    "采用的计划产量": plan,
                    "orientation": orientation,
                },
            }
        )
    return requests, limitations


def _read_csv(path: str) -> list[dict[str, str]]:
    target = Path(path).expanduser().resolve()
    if not target.is_file():
        raise ValueError(f"素材库 MCP 返回的 CSV 不存在：{target}")
    with target.open("r", encoding="utf-8-sig", newline="") as handle:
        return [dict(row) for row in csv.DictReader(handle)]


def _normalize_result(raw: Any) -> dict[str, Any]:
    if isinstance(raw, str):
        value = json.loads(raw)
    else:
        value = raw
    if not isinstance(value, dict):
        raise ValueError("素材库 MCP 结果必须是对象")
    return value


def _row_matches_orientation(row: dict[str, Any], expected_direction: int) -> bool:
    """用 MCP 返回的尺寸做横竖版校验；缺少尺寸时保留记录并交给报告说明。"""

    width = _positive_number(row.get("width"))
    height = _positive_number(row.get("height"))
    if width is None or height is None:
        specification = str(row.get("specification") or "")
        match = re.search(r"(\d+)\s*[x×＊*]\s*(\d+)", specification)
        if match:
            width, height = int(match.group(1)), int(match.group(2))
    if width is None or height is None:
        return True
    return (width >= height) == (expected_direction == 1)


def _positive_number(value: Any) -> int | None:
    try:
        number = int(str(value).strip())
    except (TypeError, ValueError):
        return None
    return number if number > 0 else None


def _select_rows(
    scope: RunnerInput,
    request: dict[str, Any],
    payload: dict[str, Any],
) -> list[dict[str, Any]]:
    # 生产 MCP 返回可能没有 status 字段；只要 error 为空且有 csv_path 即视为成功。
    if payload.get("error"):
        error = payload["error"]
        raise ValueError(error.get("message") if isinstance(error, dict) else str(error))
    status = payload.get("status")
    if status is not None and status not in {"ready", "no_data"}:
        raise ValueError(str(status))
    if not payload.get("csv_path") and status != "no_data":
        raise ValueError("素材库 MCP 返回缺少 csv_path")
    rows = _read_csv(str(payload.get("csv_path"))) if payload.get("csv_path") else []
    direction = request["direction"]
    arguments = request["arguments"]
    expected_type = arguments["reqParam"]["asset_type"]
    expected_direction = 1 if direction["orientation"] == "horizontal" else 2
    seen: set[str] = set()
    selected: list[dict[str, Any]] = []

    for row in rows:
        material_id = str(row.get("material_id") or "").strip()
        if not material_id or material_id in seen:
            continue
        if expected_type == "video" and not _row_matches_orientation(row, expected_direction):
            continue
        seen.add(material_id)
        selected.append(row)
        if len(selected) >= int(request["direction"]["采用的计划产量"]):
            break
    return selected


def consume_material_results(
    scope: RunnerInput,
    directions: list[dict[str, Any]],
    requests: list[dict[str, Any]],
    material_results: list[dict[str, Any]],
    output_dir: str | None = None,
) -> tuple[
    list[dict[str, Any]],
    dict[tuple[str, str], list[str]],
    list[str],
    list[dict[str, Any]],
]:
    """按 request_id 消费结果，并再次校验内容、类型、方向、日期和数量。"""

    result_map: dict[str, Any] = {}
    result_dir = Path(output_dir).expanduser().resolve() if output_dir else None
    for item in material_results:
        request_id = str(item.get("request_id") or "").strip()
        if not request_id or request_id in result_map:
            raise ValueError("material_results 中 request_id 为空或重复")
        result_map[request_id] = item.get("result")

    expected_ids = {item["request_id"] for item in requests}
    unexpected = sorted(set(result_map) - expected_ids)
    if unexpected:
        raise ValueError(f"material_results 包含未知 request_id：{unexpected}")

    limitations: list[str] = []
    candidates: dict[tuple[str, str], list[str]] = {}
    datasets: list[dict[str, Any]] = []
    inventory_by_key: dict[tuple[str, str], dict[str, Any]] = {}
    start, end = _three_month_window(scope)

    # 先保留全部目标方向，缺映射或缺查询结果时也能明确展示库存缺口。
    for direction in _target_directions(directions):
        key = (
            str(direction["am_content_id"]),
            str(direction["material_pattern_name"]),
        )
        plan = int(direction["采用的计划产量"])
        candidates[key] = []
        inventory_by_key[key] = {
            "am_content_id": key[0],
            "am_content_name": direction["am_content_name"],
            "material_pattern_name": key[1],
            "素材方向分类": direction["素材方向分类"],
            "采用的计划产量": plan,
            "可用库存数量": 0,
            "库存分类": "库存不满足",
            "库存缺口": plan,
            "素材获取开始日期": start,
            "素材获取结束日期（不含）": end,
        }

    for request in requests:
        request_id = request["request_id"]
        direction = request["direction"]
        key = (
            str(direction["am_content_id"]),
            str(direction["material_pattern_name"]),
        )
        raw_result = result_map.get(request_id)
        if raw_result is None:
            limitations.append(
                f"方向“{direction['am_content_name']} + {key[1]}”缺少素材查询结果"
            )
            continue
        try:
            payload = _normalize_result(raw_result)
            rows = _select_rows(scope, request, payload)
        except (ValueError, json.JSONDecodeError) as exc:
            limitations.append(
                f"方向“{direction['am_content_name']} + {key[1]}”素材查询失败：{exc}"
            )
            continue

        plan = int(direction["采用的计划产量"])
        ids = [str(row["material_id"]) for row in rows]
        candidates[key] = ids
        # 复制为业务语义文件名，避免 Agent Loop 暴露 MCP 临时文件名。
        dataset_path = str(payload.get("csv_path") or "")
        title = (
            f"素材库存结果-{len(datasets) + 1:02d}-"
            f"{direction['am_content_name']}-{direction['material_pattern_name']}"
        )
        if result_dir is not None and dataset_path:
            result_dir.mkdir(parents=True, exist_ok=True)
            target_path = result_dir / f"{_safe_filename(title)}{Path(dataset_path).suffix.lower()}"
            shutil.copyfile(dataset_path, target_path)
            dataset_path = str(target_path)
        inventory_by_key[key].update(
            {
                "可用库存数量": len(ids),
                "库存分类": "库存满足" if len(ids) >= plan else "库存不满足",
                "库存缺口": max(plan - len(ids), 0),
            }
        )
        datasets.append(
            {
                "dataset_id": request_id,
                "path": dataset_path,
                "row_count": int(payload.get("row_count") or len(rows)),
                "title": title,
                "tool_name": "agent_tool_asset_library_selector",
                "query": request["arguments"],
                "adopted_row_count": len(rows),
            }
        )

    return list(inventory_by_key.values()), candidates, limitations, datasets

