"""账户素材缺口 Skill 的输入模型。"""

from __future__ import annotations

from calendar import monthrange
from datetime import date
from typing import Literal

from pydantic import BaseModel, ConfigDict, Field, model_validator


class Period(BaseModel):
    model_config = ConfigDict(extra="forbid")

    start_date: date
    end_date: date

    @model_validator(mode="after")
    def validate_order(self) -> "Period":
        if self.start_date > self.end_date:
            raise ValueError("start_date 不能晚于 end_date")
        if self.start_date.day != 1:
            raise ValueError("周期开始日期必须是月初")
        if self.end_date.day != monthrange(self.end_date.year, self.end_date.month)[1]:
            raise ValueError("周期结束日期必须是月末")
        return self


class RunnerInput(BaseModel):
    """LLM 只负责填写业务范围，所有判断均由 Runner 完成。"""

    model_config = ConfigDict(extra="forbid")

    product: str = Field(min_length=1)
    channel: str = Field(min_length=1)
    platform: str = Field(min_length=1)
    account_owner: str = Field(min_length=1)
    material_type: Literal["图片", "视频"]
    period_previous: Period
    period_current: Period
    app_id: int = Field(gt=0)
    ad_platform_id: str | int | None = None
    app_type: str | int
    designer_groups: list[str] = Field(default_factory=list)
    designer_names: list[str] = Field(default_factory=list)
    ad_place_ids: dict[Literal["horizontal", "vertical"], list[str]] = Field(
        default_factory=dict
    )

    @model_validator(mode="after")
    def validate_periods(self) -> "RunnerInput":
        if self.period_previous.end_date >= self.period_current.start_date:
            raise ValueError("上一周期必须早于本周期且不能重叠")
        return self

    @model_validator(mode="after")
    def validate_designer_scope(self) -> "RunnerInput":
        # 保持既有业务默认范围，避免未显式传入时查询全量设计人。
        if not self.designer_groups and not self.designer_names:
            self.designer_groups = ["设计三组"]
        return self


def period_dict(period: Period) -> dict[str, str]:
    return {
        "start_date": period.start_date.isoformat(),
        "end_date": period.end_date.isoformat(),
    }

