"""构造固定报表请求，并读取 Agent Loop 返回的完整 CSV。"""

from __future__ import annotations

import csv
from pathlib import Path
from typing import Any

from models import RunnerInput


MONTH_METRICS = [
    "cost",
    "cash_cost",
    "obtain_device_cnt",
    "remove_big_obtain_device_cnt",
    "remove_big_pull_device_cnt",
    "remove_big_obtain_small_roi_month1",
    "remove_big_obtain_small_consume_rate_month1",
    "remove_big_obtain_small_arppu_month1",
    "remove_big_obtain_small_profit_amt_month1",
    "remove_big_obtain_small_consume_amt_month1",
    "remove_big_obtain_small_consume_cnt_month1",
    "remove_big_obtain_small_user_cnt",
]

# 报表字段名变化时先在这里登记别名；无法识别的变化必须失败，不能静默算成 0。
SOURCE_FIELD_ALIASES = {
    "event_date": ("date", "日期", "统计日期"),
    "cost": ("cost_total", "consume", "consume_amt", "账面消耗"),
    "cash_cost": ("cash_cost_total", "cash_consume", "现金消耗"),
    "obtain_device_cnt": ("obtain_device_num", "obtain_cnt", "获客设备数"),
    "remove_big_obtain_device_cnt": (
        "remove_big_obtain_device_num",
        "剔除后获客设备数",
    ),
    "remove_big_pull_device_cnt": (
        "remove_big_pull_device_num",
        "剔除后拉新设备数",
    ),
    "remove_big_obtain_small_profit_amt_month1": ("profit_amt", "利润"),
    "remove_big_obtain_small_consume_amt_month1": ("gift_amt", "打赏金额"),
    "remove_big_obtain_small_consume_cnt_month1": ("gift_cnt", "打赏次数"),
    "remove_big_obtain_small_user_cnt": ("user_num", "参与用户数"),
    "obtain_remain_day2": ("remain_day2", "次留设备数"),
    "pull_device_cnt": ("pull_device_num", "pull_cnt", "拉新设备数"),
}


def _filters(scope: RunnerInput) -> list[dict[str, Any]]:
    values = [
        ("app_name", scope.product),
        ("ad_platform_name", scope.channel),
        ("charger_name", scope.account_owner),
    ]
    if scope.ad_platform_id is not None:
        values.append(("ad_platform_id", str(scope.ad_platform_id)))
    values.append(("app_type", str(scope.app_type)))
    return [
        {"field": field, "operator": "IN", "values": [value]} for field, value in values
    ]


def _combined_range(scope: RunnerInput) -> dict[str, str]:
    return {
        "start_date": scope.period_previous.start_date.isoformat(),
        "end_date": scope.period_current.end_date.isoformat(),
    }


def build_requests(scope: RunnerInput) -> dict[str, tuple[str, dict[str, Any]]]:
    """返回素材缺口分析 Skill 必须原样执行的报表请求。"""

    common = {"date_range": _combined_range(scope), "filtering": _filters(scope)}
    account_dims = ["event_date", "advertiser_id", "advertiser_name"]
    material_dims = [
        "event_date",
        "am_content_id",
        "am_content_name",
        "material_pattern_name",
        "am_type_name",
        "material_id",
        "material_name",
        "url",
    ]
    daily_dims = [
        "event_date",
        "advertiser_id",
        "advertiser_name",
        "am_content_id",
        "am_content_name",
        "material_pattern_name",
        "am_type_name",
        "material_id",
    ]
    return {
        "material_monthly": (
            "agent_tool_report_level_one_month_list",
            {
                "reqParam": {
                    **common,
                    "fields": [*material_dims, *MONTH_METRICS],
                    "group_by": material_dims,
                }
            },
        ),
        "material_daily": (
            "agent_tool_report_level_first_list",
            {
                "reqParam": {
                    **common,
                    "fields": [
                        *daily_dims,
                        "cost",
                        "obtain_device_cnt",
                        "remove_big_obtain_device_cnt",
                        "obtain_remain_day2",
                        "pull_device_cnt",
                    ],
                    "group_by": daily_dims,
                }
            },
        ),
    }


def write_csv(target: Path, rows: list[dict[str, Any]]) -> None:
    target.parent.mkdir(parents=True, exist_ok=True)
    columns = list(dict.fromkeys(key for row in rows for key in row))
    with target.open("w", encoding="utf-8-sig", newline="") as handle:
        writer = csv.DictWriter(handle, fieldnames=columns)
        if columns:
            writer.writeheader()
            writer.writerows(rows)


def _extract_csv_path(result: Any, dataset_id: str) -> Path:
    if isinstance(result, str):
        raw_path = result
    elif isinstance(result, dict):
        if result.get("error"):
            raise ValueError(f"{dataset_id} 报表查询失败：{result['error']}")
        raw_path = str(result.get("csv_path") or "")
    else:
        raise ValueError(f"{dataset_id} 报表结果必须是对象或 CSV 路径")
    path = Path(raw_path).expanduser().resolve()
    if not path.is_file():
        raise ValueError(f"{dataset_id} 报表 CSV 不存在：{path}")
    return path


def _copy_csv(source: Path, target: Path) -> list[dict[str, str]]:
    with source.open("r", encoding="utf-8-sig", newline="") as handle:
        rows = [dict(row) for row in csv.DictReader(handle)]
    write_csv(target, rows)
    return rows


def _normal_field(value: Any) -> str:
    """字段名比较用的规范化 key；保留中文，仅忽略大小写和常见分隔符。"""

    return "".join(
        char for char in str(value or "").strip().lower() if char.isalnum() or "\u4e00" <= char <= "\u9fff"
    )


def _normalize_and_validate_fields(
    dataset_id: str,
    rows: list[dict[str, str]],
    arguments: dict[str, Any],
) -> list[dict[str, str]]:
    """兼容已登记的字段别名，但对未知 schema 变化快速失败。"""

    if not rows:
        return rows
    expected_fields = [str(value) for value in arguments["reqParam"]["fields"]]
    for row in rows:
        available_by_normal = {_normal_field(key): key for key in row}
        for field in expected_fields:
            if field in row:
                continue
            variants = (field, *SOURCE_FIELD_ALIASES.get(field, ()))
            source_key = next(
                (
                    available_by_normal[_normal_field(variant)]
                    for variant in variants
                    if _normal_field(variant) in available_by_normal
                ),
                None,
            )
            if source_key and source_key in row:
                row[field] = row[source_key]

    missing = [field for field in expected_fields if field not in rows[0]]
    if missing:
        raise ValueError(
            f"{dataset_id} 报表字段 schema 变化，缺少字段：{missing}；"
            "请确认报表字段契约或在 SOURCE_FIELD_ALIASES 登记别名"
        )
    return rows


def load_report_results(
    scope: RunnerInput,
    report_results: dict[str, Any],
    output_dir: Path,
) -> tuple[dict[str, list[dict[str, str]]], list[dict[str, Any]]]:
    """读取 Agent 返回值；查询意图始终使用 Runner 内置模板记录。"""

    requests = build_requests(scope)
    missing = sorted(set(requests) - set(report_results))
    unexpected = sorted(set(report_results) - set(requests))
    if missing or unexpected:
        raise ValueError(
            f"report_results 不匹配，缺少={missing or '无'}，多余={unexpected or '无'}"
        )

    rows_by_name: dict[str, list[dict[str, str]]] = {}
    datasets: list[dict[str, Any]] = []
    for name, (tool_name, arguments) in requests.items():
        source_path = _extract_csv_path(report_results[name], name)
        target_path = output_dir / f"source_{name}.csv"
        rows = _normalize_and_validate_fields(
            name,
            _copy_csv(source_path, target_path),
            arguments,
        )
        rows_by_name[name] = rows
        datasets.append(
            {
                "dataset_id": name,
                "path": str(target_path.resolve()),
                "row_count": len(rows),
                "tool_name": tool_name,
                "query": arguments["reqParam"],
            }
        )
    return rows_by_name, datasets

