"""素材缺口分析 Skill 的两阶段确定性入口。"""

from __future__ import annotations

import json
import sys
import time
from pathlib import Path
from typing import Any, Callable

from pydantic import ValidationError

PROJECT_ROOT = Path(__file__).resolve().parents[3]
sys.path.insert(0, str(PROJECT_ROOT))

from analysis import analyze  # noqa: E402
from skills.common.report_renderer.schema import ReportView  # noqa: E402
from material_queries import (
    build_material_requests,
    consume_material_results,
)
from models import RunnerInput, period_dict  # noqa: E402
from report import render_report  # noqa: E402
from report_queries import load_report_results, write_csv  # noqa: E402


def _timed(timings: dict[str, float], name: str, function: Callable[[], Any]) -> Any:
    started = time.perf_counter()
    try:
        return function()
    finally:
        timings[name] = round(time.perf_counter() - started, 3)


def _write_json(path: Path, value: Any) -> None:
    path.write_text(json.dumps(value, ensure_ascii=False, indent=2), encoding="utf-8")


def _read_json(path: Path) -> dict[str, Any]:
    if not path.is_file():
        raise ValueError(f"分析状态文件不存在：{path}")
    value = json.loads(path.read_text(encoding="utf-8"))
    if not isinstance(value, dict):
        raise ValueError("分析状态文件顶层必须是对象")
    return value


def _write_analysis_datasets(
    target: Path, analyzed: dict[str, Any], datasets: list[dict[str, Any]]
) -> None:
    for dataset_id, key in (
        ("direction_classification", "directions"),
        ("material_metrics", "materials"),
    ):
        rows = analyzed.get(key, [])
        path = target / f"{dataset_id}.csv"
        write_csv(path, rows)
        datasets.append(
            {"dataset_id": dataset_id, "path": str(path), "row_count": len(rows)}
        )


def run_analyze(payload: dict[str, Any], output_dir: str) -> dict[str, Any]:
    started = time.perf_counter()
    scope = RunnerInput.model_validate(payload.get("scope"))
    report_results = payload.get("report_results")
    if not isinstance(report_results, dict):
        raise ValueError("action=analyze 必须提供 report_results 对象")

    target = Path(output_dir).expanduser().resolve()
    target.mkdir(parents=True, exist_ok=True)
    timings: dict[str, float] = {}
    sources, datasets = _timed(
        timings,
        "load_report_results",
        lambda: load_report_results(scope, report_results, target),
    )
    analyzed = _timed(timings, "analysis", lambda: analyze(scope, sources))
    material_requests, limitations = _timed(
        timings,
        "build_material_requests",
        lambda: build_material_requests(scope, analyzed["directions"]),
    )
    _write_analysis_datasets(target, analyzed, datasets)
    timings["analyze_total"] = round(time.perf_counter() - started, 3)

    state_path = target / "analysis_state.json"
    _write_json(
        state_path,
        {
            "scope": scope.model_dump(mode="json"),
            "analyzed": {
                "directions": analyzed["directions"],
                "materials": analyzed["materials"],
            },
            "datasets": datasets,
            "timings": timings,
            "limitations": limitations,
            "material_requests": material_requests,
        },
    )
    return {
        "status": "awaiting_material_queries",
        "period_current": period_dict(scope.period_current),
        "period_previous": period_dict(scope.period_previous),
        "analysis_path": str(state_path),
        "material_requests": material_requests,
        "timings": timings,
        "limitations": limitations,
    }


def run_finalize(payload: dict[str, Any], output_dir: str) -> dict[str, Any]:
    started = time.perf_counter()
    analysis_path = Path(str(payload.get("analysis_path") or "")).expanduser().resolve()
    state = _read_json(analysis_path)
    scope = RunnerInput.model_validate(state.get("scope"))
    analyzed = state.get("analyzed")
    requests = state.get("material_requests")
    if not isinstance(analyzed, dict):
        raise ValueError("分析状态文件不完整")
    if not isinstance(requests, list):
        raise ValueError("分析状态文件缺少 material_requests")
    material_results = payload.get("material_results")
    if not isinstance(material_results, list):
        raise ValueError("action=finalize 必须提供 material_results 数组")

    target = Path(output_dir).expanduser().resolve()
    target.mkdir(parents=True, exist_ok=True)
    timings = dict(state.get("timings") or {})
    limitations = list(state.get("limitations") or [])
    datasets = list(state.get("datasets") or [])
    inventory, _, inventory_limits, material_datasets = _timed(
        timings,
        "consume_material_results",
        lambda: consume_material_results(
            scope, analyzed["directions"], requests, material_results, str(target)
        ),
    )
    limitations.extend(inventory_limits)
    datasets.extend(material_datasets)
    inventory_path = target / "asset_inventory_gap.csv"
    write_csv(inventory_path, inventory)
    datasets.append(
        {
            "dataset_id": "asset_inventory_gap",
            "path": str(inventory_path),
            "row_count": len(inventory),
        }
    )
    report_path = target / "material_gap_analysis_report.html"
    report_view_path = target / f"{report_path.stem}.view.json"
    _timed(
        timings,
        "reporting",
        lambda: render_report(
            report_path,
            scope=scope,
            analyzed=analyzed,
            inventory=inventory,
            allocation={"details": []},
            datasets=datasets,
            limitations=limitations,
        ),
    )
    delivery_files = [
        {
            "file_id": "report_html",
            "file_name": report_path.name,
            "media_type": "text/html",
            "path": str(report_path),
        },
        {
            "file_id": "report_view_json",
            "file_name": report_view_path.name,
            "media_type": "application/json",
            "path": str(report_view_path),
        },
    ]
    for dataset in datasets:
        dataset_path = Path(str(dataset["path"]))
        delivery_files.append(
            {
                "file_id": str(dataset["dataset_id"]),
                "file_name": dataset_path.name,
                "media_type": (
                    "application/json"
                    if dataset_path.suffix.lower() == ".json"
                    else "text/csv"
                ),
                "path": str(dataset_path),
            }
        )
    timings["finalize_total"] = round(time.perf_counter() - started, 3)
    return {
        "status": "ready",
        "period_current": period_dict(scope.period_current),
        "period_previous": period_dict(scope.period_previous),
        "details": [],
        "report_path": str(report_path),
        "report_view_path": str(report_view_path),
        "delivery_files": delivery_files,
        "datasets": datasets,
        "timings": timings,
        "limitations": limitations,
    }


def _download_url_from_result(raw: Any) -> str | None:
    value = json.loads(raw) if isinstance(raw, str) else raw
    if not isinstance(value, dict):
        return None
    return str(value.get("url") or "").strip() or None


def run_finalize_delivery(payload: dict[str, Any], output_dir: str) -> dict[str, Any]:
    delivery_files = payload.get("delivery_files")
    delivery_results = payload.get("delivery_results")
    if not isinstance(delivery_files, list) or not isinstance(delivery_results, list):
        raise ValueError("action=finalize_delivery 必须提供 delivery_files 和 delivery_results")

    result_by_id = {
        str(item.get("file_id")): item.get("result")
        for item in delivery_results
        if item.get("file_id")
    }
    updated_delivery: list[dict[str, Any]] = []
    for item in delivery_files:
        row = dict(item)
        url = _download_url_from_result(result_by_id.get(str(row.get("file_id"))))
        if url:
            row["url"] = url
        updated_delivery.append(row)

    target = Path(output_dir).expanduser().resolve()
    report_path = Path(
        str(payload.get("report_path") or target / "material_gap_analysis_report.html")
    ).expanduser().resolve()
    report_view_path = Path(
        str(payload.get("report_view_path") or report_path.with_name(f"{report_path.stem}.view.json"))
    ).expanduser().resolve()
    if not report_view_path.is_file():
        raise ValueError(f"ReportView 不存在：{report_view_path}")

    view = ReportView.model_validate(json.loads(report_view_path.read_text(encoding="utf-8")))
    url_by_dataset = {
        str(item.get("file_id")): str(item.get("url") or "")
        for item in updated_delivery
        if item.get("url")
    }
    for artifact in view.artifacts:
        artifact.download_url = url_by_dataset.get(artifact.dataset_id)
    report_view_path.write_text(
        json.dumps(view.model_dump(mode="json"), ensure_ascii=False, indent=2),
        encoding="utf-8",
    )
    from skills.common.report_renderer.html_renderer import render_report_html

    report_path.write_text(render_report_html(view), encoding="utf-8")
    return {
        "status": "ready",
        "report_path": str(report_path),
        "report_view_path": str(report_view_path),
        "delivery_files": updated_delivery,
    }


def run(payload: dict[str, Any], output_dir: str) -> dict[str, Any]:
    action = str(payload.get("action") or "").strip()
    handlers = {
        "analyze": run_analyze,
        "finalize": run_finalize,
        "finalize_delivery": run_finalize_delivery,
    }
    if action not in handlers:
        raise ValueError("action 只允许 analyze、finalize 或 finalize_delivery")
    return handlers[action](payload, output_dir)


def main() -> None:
    if len(sys.argv) != 3:
        print(
            json.dumps({"status": "failed", "error": "用法：runner.py '<json>' <output_dir>"}),
            ensure_ascii=False,
        )
        raise SystemExit(1)
    try:
        payload = json.loads(sys.argv[1])
        if not isinstance(payload, dict):
            raise ValueError("输入 JSON 顶层必须是对象")
        result = run(payload, sys.argv[2])
    except (ValidationError, ValueError, RuntimeError, OSError, json.JSONDecodeError) as exc:
        result = {"status": "failed", "error": str(exc), "retry_allowed": False}
    print(json.dumps(result, ensure_ascii=False, indent=2))
    raise SystemExit(0 if result.get("status") != "failed" else 1)


if __name__ == "__main__":
    main()

"""
runner.py
---------
普通计划发布统一脚本入口。

action=prepare:
  1. 使用 MCP 工具校验账户、广告组、广告计划 ID，并从 CSV 结果水合名称/媒体字段
  2. 复用 validate_and_build_params.py 生成 step1 状态文件
  3. COPY_CAMPAIGN + 广点通时，调用广点通相似校验

action=merge:
  读取 step1 状态文件与纯数字 preStrategyId，复用 merge_normal_plan_params.py
  生成最终发布参数文件。
"""

from __future__ import annotations

import csv
import json
import sys
from pathlib import Path
from typing import Any

from orchestration.script_runtime.mcp import invoke_mcp_tool

import merge_normal_plan_params
import validate_and_build_params


ALLOWED_MCP_TOOLS = {
    "agent_tool_filter_advertiser",
    "agent_tool_filter_ad",
    "agent_tool_campaign_similarity_check",
}


def _result(
    *,
    action: str,
    ok: bool,
    errors: list[str] | None = None,
    **extra: Any,
) -> dict[str, Any]:
    payload = {
        "ok": ok,
        "action": action,
        "errors": errors or [],
    }
    payload.update(extra)
    return payload


def _is_missing(value: Any) -> bool:
    return value is None or (isinstance(value, str) and not value.strip())


def _normalize_required_id(field_name: str, value: Any, errors: list[str]) -> str | None:
    if isinstance(value, bool) or _is_missing(value):
        errors.append(f"{field_name} 必须是纯数字 ID")
        return None
    if isinstance(value, int):
        number = value
    elif isinstance(value, str):
        text = value.strip()
        if not text.isdigit():
            errors.append(f"{field_name} 必须是纯数字 ID，当前值：{text}")
            return None
        number = int(text)
    else:
        errors.append(f"{field_name} 必须是纯数字 ID，当前值：{value}")
        return None
    if number <= 0:
        errors.append(f"{field_name} 必须是正整数 ID，当前值：{value}")
        return None
    return str(number)


def _normalize_target_advertiser_ids(data: dict[str, Any], errors: list[str]) -> list[str]:
    raw_ids = data.get("targetAdvertiserIds")
    if not isinstance(raw_ids, list) or not raw_ids:
        errors.append("targetAdvertiserIds 必须是非空数组")
        return []

    normalized: list[str] = []
    for index, raw_id in enumerate(raw_ids):
        advertiser_id = _normalize_required_id(
            f"targetAdvertiserIds[{index}]",
            raw_id,
            errors,
        )
        if advertiser_id is not None:
            normalized.append(advertiser_id)
    return normalized


def _dedupe(values: list[str]) -> list[str]:
    deduped: list[str] = []
    seen: set[str] = set()
    for value in values:
        if value in seen:
            continue
        seen.add(value)
        deduped.append(value)
    return deduped


def _parse_json_payload(value: Any) -> Any:
    if isinstance(value, (dict, list)):
        return value
    if value is None:
        return None
    if not isinstance(value, str):
        return value
    text = value.strip()
    if not text:
        return ""
    if text.startswith("{") or text.startswith("["):
        return json.loads(text)
    return text


def _invoke_json_tool(tool_name: str, arguments: dict[str, Any]) -> Any:
    output = invoke_mcp_tool(
        tool_name,
        arguments,
        allowed_tools=ALLOWED_MCP_TOOLS,
    )
    return _parse_json_payload(output)


def _has_non_empty_value(value: Any) -> bool:
    if value is None:
        return False
    if isinstance(value, str):
        return bool(value.strip())
    if isinstance(value, list):
        return any(_has_non_empty_value(item) for item in value)
    if isinstance(value, dict):
        return any(_has_non_empty_value(item) for item in value.values())
    return True


def _normalize_ids_text(value: Any) -> str | None:
    if isinstance(value, str):
        return value.strip() or None
    if not isinstance(value, list):
        return None
    parts: list[str] = []
    seen: set[str] = set()
    for item in value:
        if not isinstance(item, (str, int, float)):
            continue
        text = str(item).strip()
        if not text or text in seen:
            continue
        seen.add(text)
        parts.append(text)
    return "、".join(parts) if parts else None


def _field(payload: Any, field_name: str) -> Any:
    if isinstance(payload, dict):
        if field_name in payload:
            return payload[field_name]
        for value in payload.values():
            found = _field(value, field_name)
            if found is not None:
                return found
    if isinstance(payload, list):
        for item in payload:
            found = _field(item, field_name)
            if found is not None:
                return found
    return None


def _payload_has_empty_result(payload: Any) -> bool:
    if payload is None:
        return True
    if isinstance(payload, list):
        return len(payload) == 0
    if isinstance(payload, dict):
        if not payload:
            return True
        for key in ("data", "list", "preview_rows"):
            if key in payload and isinstance(payload[key], list) and not payload[key]:
                return True
    return False


def _csv_path_from_payload(payload: Any, tool_name: str, errors: list[str]) -> Path | None:
    if not isinstance(payload, dict):
        errors.append(f"{tool_name} 返回值不是对象，无法读取 csv_path")
        return None
    raw_csv_path = payload.get("csv_path")
    if _is_missing(raw_csv_path):
        if _payload_has_empty_result(payload):
            errors.append(f"{tool_name} 返回为空，无法完成 ID 校验")
        else:
            errors.append(f"{tool_name} 未返回 csv_path，无法读取校验结果")
        return None
    csv_path = Path(str(raw_csv_path)).expanduser()
    if not csv_path.exists() or not csv_path.is_file():
        errors.append(f"{tool_name} 返回的 csv_path 不存在：{csv_path}")
        return None
    return csv_path


def _read_csv_rows(csv_path: Path) -> list[dict[str, str]]:
    with csv_path.open("r", encoding="utf-8-sig", newline="") as file:
        reader = csv.DictReader(file)
        return [
            {str(key or "").strip(): str(value or "").strip() for key, value in row.items()}
            for row in reader
        ]


def _row_value(row: dict[str, str], *field_names: str) -> str:
    normalized = {
        key.replace("_", "").lower(): value
        for key, value in row.items()
    }
    for field_name in field_names:
        value = normalized.get(field_name.replace("_", "").lower())
        if value:
            return value
    return ""


def _positive_int_field(field_name: str, value: Any, errors: list[str]) -> int | None:
    if isinstance(value, bool) or _is_missing(value):
        errors.append(f"{field_name} 必须是正整数")
        return None
    try:
        number = int(str(value).strip())
    except (TypeError, ValueError):
        errors.append(f"{field_name} 必须是正整数，当前值：{value}")
        return None
    if number <= 0:
        errors.append(f"{field_name} 必须是正整数，当前值：{value}")
        return None
    return number


def _load_advertisers(advertiser_ids: list[str], errors: list[str]) -> dict[str, dict[str, Any]]:
    payload = _invoke_json_tool(
        "agent_tool_filter_advertiser",
        {"reqParam": {"advertiserIds": advertiser_ids}},
    )
    advertiser_id_error = _field(payload, "advertiserIdError")
    if _has_non_empty_value(advertiser_id_error):
        ids_text = _normalize_ids_text(advertiser_id_error) or "、".join(advertiser_ids)
        errors.append(f"账户 ID [{ids_text}] 不存在或无权限，请重新确认后提供正确的 ID。")
        return {}

    csv_path = _csv_path_from_payload(payload, "agent_tool_filter_advertiser", errors)
    if csv_path is None:
        return {}

    rows = _read_csv_rows(csv_path)
    advertisers: dict[str, dict[str, Any]] = {}
    for row in rows:
        advertiser_id = _row_value(row, "advertiserId")
        if not advertiser_id:
            continue
        advertisers[advertiser_id] = {
            "advertiserId": advertiser_id,
            "advertiserName": _row_value(row, "advertiserName"),
            "appId": _row_value(row, "appId"),
            "adPlatformId": _row_value(row, "adPlatformId"),
            "adPlatformName": _row_value(row, "adPlatformName"),
        }

    missing = [advertiser_id for advertiser_id in advertiser_ids if advertiser_id not in advertisers]
    if missing:
        errors.append(f"账户 ID [{'、'.join(missing)}] 不存在或无权限，请重新确认后提供正确的 ID。")
        return {}

    for advertiser_id in advertiser_ids:
        advertiser = advertisers[advertiser_id]
        if not advertiser["advertiserName"]:
            errors.append(f"账户 ID [{advertiser_id}] 校验结果缺少 advertiserName")
        app_id = _positive_int_field(f"账户 {advertiser_id}.appId", advertiser["appId"], errors)
        ad_platform_id = _positive_int_field(
            f"账户 {advertiser_id}.adPlatformId",
            advertiser["adPlatformId"],
            errors,
        )
        if app_id is not None:
            advertiser["appId"] = app_id
        if ad_platform_id is not None:
            advertiser["adPlatformId"] = ad_platform_id
    return advertisers


def _ensure_single_app_and_media(advertisers: list[dict[str, Any]], errors: list[str]) -> None:
    app_ids = {advertiser.get("appId") for advertiser in advertisers}
    platform_ids = {advertiser.get("adPlatformId") for advertiser in advertisers}
    platform_names = {
        str(advertiser.get("adPlatformName") or "").strip()
        for advertiser in advertisers
        if str(advertiser.get("adPlatformName") or "").strip()
    }
    if len(app_ids) > 1:
        errors.append(f"目标账户与模板账户的 appId 必须一致，当前存在多个值：{app_ids}")
    if len(platform_ids) > 1:
        errors.append(f"目标账户与模板账户的 adPlatformId 必须一致，当前存在多个值：{platform_ids}")
    if len(platform_names) > 1:
        errors.append(f"一次只支持单媒体发布，当前检测到多个媒体平台：{platform_names}")


def _load_ad_entities(
    *,
    advertiser_id: str,
    campaign_ids: list[str],
    ad_ids: list[str],
    errors: list[str],
) -> tuple[dict[str, str], dict[str, str]]:
    req_param: dict[str, Any] = {"advertiserIds": [advertiser_id]}
    if campaign_ids:
        req_param["campaignIds"] = campaign_ids
    if ad_ids:
        req_param["adIds"] = ad_ids

    payload = _invoke_json_tool("agent_tool_filter_ad", {"reqParam": req_param})

    campaign_id_error = _field(payload, "campaignIdError")
    if _has_non_empty_value(campaign_id_error):
        ids_text = _normalize_ids_text(campaign_id_error) or "、".join(campaign_ids)
        errors.append(
            f"广告组 ID [{ids_text}] 在账户 [{advertiser_id}] 下不存在，请重新确认后提供正确的 ID。"
        )
        return {}, {}

    ad_id_error = _field(payload, "adIdError")
    if _has_non_empty_value(ad_id_error):
        ids_text = _normalize_ids_text(ad_id_error) or "、".join(ad_ids)
        errors.append(
            f"广告计划 ID [{ids_text}] 在账户 [{advertiser_id}] 下不存在，请重新确认后提供正确的 ID。"
        )
        return {}, {}

    csv_path = _csv_path_from_payload(payload, "agent_tool_filter_ad", errors)
    if csv_path is None:
        return {}, {}

    campaign_names: dict[str, str] = {}
    ad_names: dict[str, str] = {}
    for row in _read_csv_rows(csv_path):
        campaign_id = _row_value(row, "campaignId")
        if campaign_id:
            campaign_names[campaign_id] = _row_value(row, "campaignName")
        ad_id = _row_value(row, "adId")
        if ad_id:
            ad_names[ad_id] = _row_value(row, "adName")

    missing_campaigns = [campaign_id for campaign_id in campaign_ids if campaign_id not in campaign_names]
    if missing_campaigns:
        errors.append(
            f"广告组 ID [{'、'.join(missing_campaigns)}] 在账户 [{advertiser_id}] 下不存在，请重新确认后提供正确的 ID。"
        )
    missing_ads = [ad_id for ad_id in ad_ids if ad_id not in ad_names]
    if missing_ads:
        errors.append(
            f"广告计划 ID [{'、'.join(missing_ads)}] 在账户 [{advertiser_id}] 下不存在，请重新确认后提供正确的 ID。"
        )
    return campaign_names, ad_names


def _load_template_ad(
    *,
    ad_platform_name: str,
    template_ad_id: str,
    errors: list[str],
) -> dict[str, Any] | None:
    payload = _invoke_json_tool(
        "agent_tool_filter_ad",
        {
            "reqParam": {
                "adPlatformNames": [ad_platform_name],
                "adIds": [template_ad_id],
            }
        },
    )
    ad_id_error = _field(payload, "adIdError")
    if _has_non_empty_value(ad_id_error):
        ids_text = _normalize_ids_text(ad_id_error) or template_ad_id
        errors.append(
            f"模板广告计划 ID [{ids_text}] 在媒体平台 [{ad_platform_name}] 下不存在或无权限。"
        )
        return None
    if _payload_has_empty_result(payload):
        errors.append(
            f"模板广告计划 ID [{template_ad_id}] 在媒体平台 [{ad_platform_name}] 下不存在或无权限。"
        )
        return None

    csv_path = _csv_path_from_payload(payload, "agent_tool_filter_ad", errors)
    if csv_path is None:
        return None

    matched_rows = [
        row
        for row in _read_csv_rows(csv_path)
        if _row_value(row, "adId") == template_ad_id
    ]
    mappings = {
        (_row_value(row, "advertiserId"), _row_value(row, "campaignId"))
        for row in matched_rows
    }
    if not matched_rows:
        errors.append(
            f"模板广告计划 ID [{template_ad_id}] 在媒体平台 [{ad_platform_name}] 下不存在或无权限。"
        )
        return None
    if len(mappings) != 1:
        errors.append(
            f"模板广告计划 ID [{template_ad_id}] 反查到多个账户或广告组，无法唯一确定模板。"
        )
        return None

    row = matched_rows[0]
    template = {
        "advertiserId": _row_value(row, "advertiserId"),
        "advertiserName": _row_value(row, "advertiserName"),
        "appId": _row_value(row, "appId"),
        "adPlatformId": _row_value(row, "adPlatformId"),
        "adPlatformName": _row_value(row, "adPlatformName"),
        "campaignId": _row_value(row, "campaignId"),
        "campaignName": _row_value(row, "campaignName"),
        "adId": template_ad_id,
        "adName": _row_value(row, "adName"),
    }
    for field_name in ("advertiserId", "advertiserName", "campaignId", "campaignName", "adPlatformName"):
        if not template[field_name]:
            errors.append(f"模板广告计划 ID [{template_ad_id}] 反查结果缺少 {field_name}")
    app_id = _positive_int_field("模板广告计划反查结果 appId", template["appId"], errors)
    ad_platform_id = _positive_int_field(
        "模板广告计划反查结果 adPlatformId",
        template["adPlatformId"],
        errors,
    )
    if template["adPlatformName"] and template["adPlatformName"] != ad_platform_name:
        errors.append(
            f"模板广告计划所属媒体为 [{template['adPlatformName']}]，与目标账户媒体 [{ad_platform_name}] 不一致。"
        )
    if errors:
        return None
    assert app_id is not None
    assert ad_platform_id is not None
    template["appId"] = app_id
    template["adPlatformId"] = ad_platform_id
    return template


def _copy_optional_fields(source: dict[str, Any], target: dict[str, Any]) -> None:
    for field_name in ("preStrategyId", "adAttrStrategy", "materialId", "materialIds", "materialIdList"):
        if field_name in source:
            target[field_name] = source[field_name]


def _build_prepare_data(data: dict[str, Any]) -> dict[str, Any]:
    errors: list[str] = []
    mode = str(data.get("mode") or "").strip().upper()
    target_advertiser_ids = _normalize_target_advertiser_ids(data, errors)

    if mode not in {"COPY_CAMPAIGN", "APPEND_AD"}:
        errors.append(f"mode 字段无效：'{mode}'，必须是 COPY_CAMPAIGN 或 APPEND_AD")

    target_campaign_id = None
    template_ad_id = _normalize_required_id("templateAdId", data.get("templateAdId"), errors)

    if mode == "APPEND_AD":
        if len(target_advertiser_ids) > 1:
            errors.append("APPEND_AD 模式仅支持单个目标账户")
        target_campaign_id = _normalize_required_id(
            "targetCampaignId",
            data.get("targetCampaignId"),
            errors,
        )

    if errors:
        return _result(action="prepare", ok=False, errors=errors)

    advertisers = _load_advertisers(_dedupe(target_advertiser_ids), errors)
    if errors:
        return _result(action="prepare", ok=False, errors=errors)
    _ensure_single_app_and_media(
        [advertisers[advertiser_id] for advertiser_id in _dedupe(target_advertiser_ids)],
        errors,
    )
    if errors:
        return _result(action="prepare", ok=False, errors=errors)

    campaign_names: dict[str, str] = {}
    if mode == "APPEND_AD":
        assert target_campaign_id is not None
        target_advertiser_id = target_advertiser_ids[0]
        campaign_names, _ = _load_ad_entities(
            advertiser_id=target_advertiser_id,
            campaign_ids=[target_campaign_id],
            ad_ids=[],
            errors=errors,
        )
        if errors:
            return _result(action="prepare", ok=False, errors=errors)

    target_platform_name = str(advertisers[target_advertiser_ids[0]].get("adPlatformName") or "").strip()
    if not target_platform_name:
        return _result(
            action="prepare",
            ok=False,
            errors=["目标账户校验结果缺少 adPlatformName，无法反查模板广告计划"],
        )
    assert template_ad_id is not None
    template = _load_template_ad(
        ad_platform_name=target_platform_name,
        template_ad_id=template_ad_id,
        errors=errors,
    )
    if errors or template is None:
        return _result(action="prepare", ok=False, errors=errors)
    _ensure_single_app_and_media(
        [advertisers[advertiser_id] for advertiser_id in _dedupe(target_advertiser_ids)] + [template],
        errors,
    )
    if errors:
        return _result(action="prepare", ok=False, errors=errors)

    accounts: list[dict[str, Any]] = []
    if mode == "COPY_CAMPAIGN":
        for target_advertiser_id in target_advertiser_ids:
            target_advertiser = advertisers[target_advertiser_id]
            accounts.append(
                {
                    "advertiserId": target_advertiser["advertiserId"],
                    "advertiserName": target_advertiser["advertiserName"],
                    "appId": target_advertiser["appId"],
                    "adPlatformId": target_advertiser["adPlatformId"],
                    "adPlatformName": target_advertiser["adPlatformName"],
                    "templateAdvertiserId": template["advertiserId"],
                    "templateAdvertiserName": template["advertiserName"],
                    "tempAdPlatformName": template["adPlatformName"],
                    "templateCampaignId": template["campaignId"],
                    "templateCampaignName": template["campaignName"],
                    "templateAdId": template_ad_id,
                    "templateAdName": template["adName"],
                }
            )
    else:
        assert target_campaign_id is not None
        target_advertiser_id = target_advertiser_ids[0]
        target_advertiser = advertisers[target_advertiser_id]
        accounts.append(
            {
                "advertiserId": target_advertiser["advertiserId"],
                "advertiserName": target_advertiser["advertiserName"],
                "appId": target_advertiser["appId"],
                "adPlatformId": target_advertiser["adPlatformId"],
                "adPlatformName": target_advertiser["adPlatformName"],
                "templateAdvertiserId": template["advertiserId"],
                "templateAdvertiserName": template["advertiserName"],
                "tempAdPlatformName": template["adPlatformName"],
                "targetCampaignId": target_campaign_id,
                "targetCampaignName": campaign_names[target_campaign_id],
                "templateAdId": template_ad_id,
                "templateAdName": template["adName"],
            }
        )

    prepared = {
        "mode": mode,
        "accounts": accounts,
        "adCntPerCampaign": data.get("adCntPerCampaign"),
    }
    if mode == "COPY_CAMPAIGN":
        prepared["campaignCntPerAdvertiser"] = data.get("campaignCntPerAdvertiser")
    _copy_optional_fields(data, prepared)
    return prepared


def _write_step1_result(result: dict[str, Any], output_dir: str) -> dict[str, Any]:
    state_file, similarity_file = validate_and_build_params._build_output_paths(output_dir)
    result["output_file"] = state_file
    if result.get("ok"):
        similarity_payload = {
            "publishStrategies": result["publishStrategies"],
            "materialStrategies": [result["draftMaterialStrategy"]],
        }
        result["similarity_check_file"] = similarity_file
        validate_and_build_params._write_json(similarity_file, similarity_payload)
    validate_and_build_params._write_json(state_file, result)
    return result


def _needs_similarity_check(validated_result: dict[str, Any]) -> bool:
    if not validated_result.get("ok"):
        return False
    publish_strategies = validated_result.get("publishStrategies")
    if not isinstance(publish_strategies, list) or not publish_strategies:
        return False
    if publish_strategies[0].get("type") != "COPY_CAMPAIGN":
        return False
    draft = validated_result.get("draftMaterialStrategy")
    return isinstance(draft, dict) and int(draft.get("adPlatformId") or 0) == 3


def _similarity_failure_messages(payload: Any) -> list[str]:
    if not isinstance(payload, dict):
        return []
    failure = payload.get("failure")
    if not _has_non_empty_value(failure):
        return []
    if isinstance(failure, list):
        messages: list[str] = []
        for item in failure:
            if isinstance(item, dict):
                message = str(item.get("message") or "").strip()
                if message:
                    messages.append(message)
            elif str(item).strip():
                messages.append(str(item).strip())
        return messages or ["存在目标账号命中高相似广告组，请调整年龄定向后重试。"]
    if isinstance(failure, dict):
        message = str(failure.get("message") or "").strip()
        return [message] if message else ["存在目标账号命中高相似广告组，请调整年龄定向后重试。"]
    return [str(failure).strip() or "存在目标账号命中高相似广告组，请调整年龄定向后重试。"]


def prepare(data: dict[str, Any], output_dir: str) -> dict[str, Any]:
    prepared = _build_prepare_data(data)
    if not prepared.get("ok", True):
        return prepared

    validation_result = validate_and_build_params.validate(prepared)
    validation_result = _write_step1_result(validation_result, output_dir)
    if not validation_result.get("ok"):
        validation_result["action"] = "prepare"
        validation_result["next_action"] = None
        return validation_result

    if _needs_similarity_check(validation_result):
        similarity_payload = _invoke_json_tool(
            "agent_tool_campaign_similarity_check",
            {"reqParamPath": validation_result["similarity_check_file"]},
        )
        messages = _similarity_failure_messages(similarity_payload)
        if messages:
            return _result(
                action="prepare",
                ok=False,
                errors=[
                    "广点通目标账号相似广告组定向校验未全部通过，已停止后续流程。",
                    *messages,
                ],
                output_file=validation_result["output_file"],
                similarity_check_file=validation_result.get("similarity_check_file"),
            )

    validation_result["action"] = "prepare"
    validation_result["needs_pre_strategy_id"] = not bool(validation_result.get("preStrategyId"))
    validation_result["next_action"] = (
        "render_algorithmic_material_screening"
        if validation_result["needs_pre_strategy_id"]
        else "runner_merge"
    )
    return validation_result


def merge(data: dict[str, Any], output_dir: str) -> dict[str, Any]:
    step1_file = str(data.get("step1File") or "").strip()
    if not step1_file:
        return _result(action="merge", ok=False, errors=["step1File 是必填字段"])

    try:
        with open(step1_file, "r", encoding="utf-8") as file:
            state = json.load(file)
    except Exception as exc:  # noqa: BLE001
        return _result(action="merge", ok=False, errors=[f"读取 step1 文件失败：{exc}"])

    result = merge_normal_plan_params.merge(
        publish_strategies=state.get("publishStrategies", []),
        draft_material_strategy=state.get("draftMaterialStrategy"),
        pre_strategy_id=data.get("preStrategyId"),
    )
    merge_normal_plan_params._write_output(result, output_dir)
    result["action"] = "merge"
    result["next_action"] = "agent_tool_batch_build_validate" if result.get("ok") else None
    return result


def run(data: dict[str, Any], output_dir: str) -> dict[str, Any]:
    action = str(data.get("action") or "").strip().lower()
    if action == "prepare":
        return prepare(data, output_dir)
    if action == "merge":
        return merge(data, output_dir)
    return _result(
        action=action or "unknown",
        ok=False,
        errors=["action 必须是 prepare 或 merge"],
    )


def main() -> None:
    if len(sys.argv) < 3:
        print(json.dumps(
            _result(
                action="unknown",
                ok=False,
                errors=["用法：python runner.py '<json_string>' <output_dir>"],
            ),
            ensure_ascii=False,
        ))
        sys.exit(1)

    output_dir = sys.argv[2]
    try:
        data = json.loads(sys.argv[1])
    except json.JSONDecodeError as exc:
        print(json.dumps(
            _result(action="unknown", ok=False, errors=[f"JSON 解析失败：{exc}"]),
            ensure_ascii=False,
        ))
        sys.exit(1)

    if not isinstance(data, dict):
        result = _result(action="unknown", ok=False, errors=["输入 JSON 顶层必须是对象"])
    else:
        result = run(data, output_dir)

    print(json.dumps(result, ensure_ascii=False, indent=2))
    sys.exit(0 if result.get("ok") else 1)


if __name__ == "__main__":
    main()

