"""
validate_and_build_params.py
────────────────────────────
阶段一：普通计划发布的参数校验与组装。

职责：
  1. 按模式（COPY_CAMPAIGN / APPEND_AD）校验账户、模板、数量字段
  2. 校验模板调整字段、单媒体单模板约束
  3. 组装 publishStrategies
  4. 生成 AUTO_RELEASE 草稿 materialStrategies
  5. 生成广点通一致性校验专用 reqParam 文件
  6. 将结果写入 <output_dir>/normal_plan_publish_state_1_{timestamp}_{uuid}.json
"""

from __future__ import annotations

import json
import os
import sys
import uuid
from datetime import datetime
from typing import Any


REQUIRED_COPY = [
    "advertiserId",
    "advertiserName",
    "appId",
    "adPlatformId",
    "templateAdvertiserId",
    "templateAdvertiserName",
    "templateCampaignId",
    "templateCampaignName",
    "templateAdId",
]

REQUIRED_APPEND = [
    "advertiserId",
    "advertiserName",
    "appId",
    "adPlatformId",
    "targetCampaignId",
    "targetCampaignName",
    "templateAdvertiserId",
    "templateAdvertiserName",
    "templateAdId",
]

FORBIDDEN_COPY = {"targetCampaignId", "targetCampaignName"}
FORBIDDEN_APPEND = {"templateCampaignId", "templateCampaignName", "campaignCntPerAdvertiser"}

SHARED_COPY_FIELDS = [
    "templateAdvertiserId",
    "templateAdvertiserName",
    "templateCampaignId",
    "templateCampaignName",
    "templateAdId",
]

SHARED_APPEND_FIELDS = [
    "templateAdvertiserId",
    "templateAdvertiserName",
    "templateAdId",
]

ADJUSTMENT_TYPES = {"FIXED_AMOUNT", "INCREASE_PERCENT", "DECREASE_PERCENT"}
ENTITY_ID_FIELDS = {
    "advertiserId",
    "templateAdvertiserId",
    "targetCampaignId",
    "templateCampaignId",
    "templateAdId",
}


def _normalize_id(value: Any) -> str:
    return str(value)


def _is_missing(value: Any) -> bool:
    return value is None or (isinstance(value, str) and not value.strip())


def _positive_int(value: Any, field_name: str, errors: list[str]) -> int | None:
    if isinstance(value, bool):
        errors.append(f"{field_name} 必须是正整数，当前值：{value}")
        return None
    try:
        number = int(value)
    except (TypeError, ValueError):
        errors.append(f"{field_name} 必须是正整数，当前值：{value}")
        return None
    if number <= 0:
        errors.append(f"{field_name} 必须是正整数，当前值：{number}")
        return None
    return number


def _validate_entity_id(value: Any, field_name: str, errors: list[str]) -> None:
    if _is_missing(value):
        return
    if isinstance(value, bool):
        errors.append(f"{field_name} 必须是纯数字 ID，当前值：{value}")
        return
    if isinstance(value, int):
        if value <= 0:
            errors.append(f"{field_name} 必须是正整数 ID，当前值：{value}")
        return
    if isinstance(value, str):
        text = value.strip()
        if not text.isdigit():
            errors.append(f"{field_name} 必须是纯数字 ID，当前值：{text}")
            return
        if int(text) <= 0:
            errors.append(f"{field_name} 必须是正整数 ID，当前值：{text}")
        return
    errors.append(f"{field_name} 必须是纯数字 ID，当前值：{value}")


def _normalize_number(value: Any) -> int | float | None:
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return int(value) if isinstance(value, float) and value.is_integer() else value
    if isinstance(value, str):
        text = value.strip()
        if not text:
            return None
        try:
            number = float(text)
        except ValueError:
            return None
        return int(number) if number.is_integer() else number
    return None


def _normalize_optional_pre_strategy_id(value: Any, errors: list[str]) -> str | None:
    if _is_missing(value):
        return None
    if isinstance(value, bool):
        errors.append(f"preStrategyId 必须是纯数字 ID，当前值：{value}")
        return None
    if isinstance(value, int):
        number = value
    elif isinstance(value, str):
        normalized_value = value.strip()
        if not normalized_value.isdigit():
            errors.append(f"preStrategyId 必须是纯数字 ID，当前值：{normalized_value}")
            return None
        number = int(normalized_value)
    else:
        errors.append(f"preStrategyId 必须是纯数字 ID，当前值：{value}")
        return None
    if number <= 0:
        errors.append(f"preStrategyId 必须是纯数字 ID，当前值：{value}")
        return None
    return str(number)


def _validate_adjustment_block(
    block_name: str,
    raw_block: Any,
    errors: list[str],
) -> dict[str, Any] | None:
    if raw_block is None:
        return None
    if not isinstance(raw_block, dict):
        errors.append(f"adAttrStrategy.{block_name} 必须是对象")
        return None
    adj_type = raw_block.get("type")
    if adj_type not in ADJUSTMENT_TYPES:
        errors.append(
            f"adAttrStrategy.{block_name}.type 非法：{adj_type}，可选值为 {sorted(ADJUSTMENT_TYPES)}"
        )
        return None
    value = _normalize_number(raw_block.get("value"))
    if value is None:
        errors.append(f"adAttrStrategy.{block_name}.value 必须是数值")
        return None
    if value <= 0:
        errors.append(f"adAttrStrategy.{block_name}.value 必须大于 0，当前值：{value}")
        return None
    return {"type": adj_type, "value": value}


def _validate_age_ranges(raw_ranges: Any, errors: list[str]) -> list[dict[str, int]] | None:
    if raw_ranges is None:
        return None
    if not isinstance(raw_ranges, list) or not raw_ranges:
        errors.append("adAttrStrategy.age 至少需要 1 个年龄区间")
        return None
    if len(raw_ranges) > 5:
        errors.append("adAttrStrategy.age 最多支持 5 个年龄区间")
        return None

    normalized: list[dict[str, int]] = []
    for index, item in enumerate(raw_ranges):
        label = f"adAttrStrategy.age[{index}]"
        if not isinstance(item, dict):
            errors.append(f"{label} 必须是对象")
            continue
        if item.get("unlimited") is True or str(item.get("label") or "").strip() == "不限":
            errors.append("年龄“不限”与其它年龄区间不能同时选择，需要重新修改")
            continue
        min_age = _positive_int(item.get("min"), f"{label}.min", errors)
        max_age = _positive_int(item.get("max"), f"{label}.max", errors)
        if min_age is None or max_age is None:
            continue
        if min_age < 14:
            errors.append(f"{label}.min 不能小于 14")
        if max_age > 66:
            errors.append(f"{label}.max 不能大于 66")
        if max_age - min_age < 4:
            errors.append(f"{label} 年龄区间至少需要覆盖 5 岁，当前为 {min_age}~{max_age}")
        normalized.append({"min": min_age, "max": max_age})

    sorted_ranges = sorted(normalized, key=lambda item: (item["min"], item["max"]))
    for prev, current in zip(sorted_ranges, sorted_ranges[1:]):
        if current["min"] <= prev["max"]:
            errors.append("修改多个年龄范围时不支持重叠区间，请重新修改年龄范围")
            break
    return sorted_ranges


def _validate_ad_attr_strategy(raw_strategy: Any, errors: list[str]) -> dict[str, Any] | None:
    if raw_strategy is None:
        return None
    if not isinstance(raw_strategy, dict):
        errors.append("adAttrStrategy 必须是对象")
        return None

    if not _is_missing(raw_strategy.get("deliveryTime")):
        errors.append("不支持修改投放时间")
    budget_mode = str(raw_strategy.get("budgetMode") or "").strip().upper()
    if budget_mode in {"UNLIMITED", "NO_LIMIT"} or str(raw_strategy.get("budgetMode") or "").strip() == "不限":
        errors.append("预算金额不支持设置为不限")

    normalized: dict[str, Any] = {}
    for key in ("budget", "bid", "deepBid"):
        block = _validate_adjustment_block(key, raw_strategy.get(key), errors)
        if block is not None:
            normalized[key] = block

    age_ranges = _validate_age_ranges(raw_strategy.get("age"), errors)
    if age_ranges is not None:
        normalized["age"] = age_ranges

    return normalized or None


def _build_draft_material_strategy(
    *,
    mode: str,
    app_id: int,
    ad_platform_id: int,
    campaign_cnt_per_advertiser: int | None,
    ad_cnt_per_campaign: int,
) -> dict[str, Any]:
    layout_rules: dict[str, Any] = {"adCntPerCampaign": ad_cnt_per_campaign}
    if mode == "COPY_CAMPAIGN":
        layout_rules["campaignCntPerAdvertiser"] = campaign_cnt_per_advertiser
    return {
        "type": "AUTO_RELEASE",
        "appId": app_id,
        "adPlatformId": ad_platform_id,
        "layoutRules": layout_rules,
    }


def validate(data: dict[str, Any]) -> dict[str, Any]:
    errors: list[str] = []
    mode = str(data.get("mode") or "").upper()
    accounts = data.get("accounts", [])
    pre_strategy_id = _normalize_optional_pre_strategy_id(
        data.get("preStrategyId"),
        errors,
    )

    if mode not in {"COPY_CAMPAIGN", "APPEND_AD"}:
        errors.append(f"mode 字段无效：'{mode}'，必须是 COPY_CAMPAIGN 或 APPEND_AD")
        return {"step": 1, "ok": False, "errors": errors, "publishStrategies": []}

    if not isinstance(accounts, list) or not accounts:
        errors.append("accounts 列表为空，至少需要一个目标账户")
        return {"step": 1, "ok": False, "errors": errors, "publishStrategies": []}

    if mode == "APPEND_AD" and len(accounts) > 1:
        errors.append("APPEND_AD 模式仅支持单个目标账户")

    if not _is_missing(data.get("materialId")) or not _is_missing(data.get("materialIds")) or not _is_missing(data.get("materialIdList")):
        errors.append("普通计划发布不支持手动指定素材 ID，请改为提供算法素材筛选预设")

    ad_cnt_per_campaign = _positive_int(data.get("adCntPerCampaign"), "adCntPerCampaign", errors)

    campaign_cnt_per_advertiser = None
    if mode == "COPY_CAMPAIGN":
        campaign_cnt_per_advertiser = _positive_int(
            data.get("campaignCntPerAdvertiser"),
            "campaignCntPerAdvertiser",
            errors,
        )
    elif data.get("campaignCntPerAdvertiser") is not None:
        errors.append("APPEND_AD 模式禁止填写 campaignCntPerAdvertiser")

    ad_attr_strategy = _validate_ad_attr_strategy(data.get("adAttrStrategy"), errors)

    required = REQUIRED_COPY if mode == "COPY_CAMPAIGN" else REQUIRED_APPEND
    forbidden = FORBIDDEN_COPY if mode == "COPY_CAMPAIGN" else FORBIDDEN_APPEND

    advertiser_ids: list[str] = []
    app_ids: set[int] = set()
    platform_ids: set[int] = set()
    platform_names: set[str] = set()
    template_platform_names: set[str] = set()

    for index, account in enumerate(accounts):
        account_id_for_label = account.get("advertiserId", "?") if isinstance(account, dict) else "?"
        label = f"账户[{index}]({account_id_for_label})"
        if not isinstance(account, dict):
            errors.append(f"{label} 必须是对象")
            continue
        for field in required:
            if _is_missing(account.get(field)):
                errors.append(f"{label} 缺少必填字段：{field}")
        for field in ENTITY_ID_FIELDS:
            if field in account:
                _validate_entity_id(account.get(field), f"{label}.{field}", errors)
        for field in forbidden:
            if field in account and account.get(field) is not None:
                errors.append(f"{label} 包含禁止字段（{mode} 模式不允许）：{field}")

        if (
            account.get("materialIdList")
            or account.get("materialIds")
            or account.get("materialId")
        ):
            errors.append("普通计划发布不支持手动指定素材 ID，请改为提供算法素材筛选预设")

        advertiser_id = account.get("advertiserId")
        if advertiser_id is not None:
            advertiser_ids.append(str(advertiser_id))

        app_id = account.get("appId")
        if app_id is not None:
            normalized_app_id = _positive_int(app_id, f"{label}.appId", errors)
            if normalized_app_id is not None:
                app_ids.add(normalized_app_id)
        platform_id = account.get("adPlatformId")
        if platform_id is not None:
            normalized_platform_id = _positive_int(platform_id, f"{label}.adPlatformId", errors)
            if normalized_platform_id is not None:
                platform_ids.add(normalized_platform_id)

        platform_name = str(account.get("adPlatformName") or "").strip()
        if platform_name:
            platform_names.add(platform_name)
        temp_platform_name = str(account.get("tempAdPlatformName") or "").strip()
        if temp_platform_name:
            template_platform_names.add(temp_platform_name)

    if len(set(advertiser_ids)) != len(advertiser_ids):
        errors.append("目标账户 advertiserId 不允许重复")
    if len(app_ids) > 1:
        errors.append(f"所有账户的 appId 必须一致，当前存在多个值：{app_ids}")
    if len(platform_ids) > 1:
        errors.append(f"所有账户的 adPlatformId 必须一致，当前存在多个值：{platform_ids}")

    merged_platform_names = platform_names | template_platform_names
    if len(merged_platform_names) > 1:
        errors.append(f"一次只支持单媒体发布，当前检测到多个媒体平台：{merged_platform_names}")

    if mode == "COPY_CAMPAIGN":
        for field in SHARED_COPY_FIELDS:
            values = {
                account.get(field)
                for account in accounts
                if isinstance(account, dict) and account.get(field) is not None
            }
            if len(values) > 1:
                errors.append(f"一次只能选择单个模版复制，不支持多个模板。字段 {field} 当前存在多个值：{values}")
    else:
        for field in SHARED_APPEND_FIELDS:
            values = {
                account.get(field)
                for account in accounts
                if isinstance(account, dict) and account.get(field) is not None
            }
            if len(values) > 1:
                errors.append(f"APPEND_AD 一次只能使用一个模板。字段 {field} 当前存在多个值：{values}")

    if errors:
        return {"step": 1, "ok": False, "errors": errors, "publishStrategies": []}

    publish_strategies: list[dict[str, Any]] = []
    for account in accounts:
        entry = {
            "type": mode,
            "appId": int(account["appId"]),
            "adPlatformId": int(account["adPlatformId"]),
            "advertiserId": _normalize_id(account["advertiserId"]),
            "advertiserName": account["advertiserName"],
            "templateAdId": _normalize_id(account["templateAdId"]),
        }
        template_ad_name = account.get("templateAdName")
        if not _is_missing(template_ad_name):
            entry["templateAdName"] = template_ad_name

        if mode == "COPY_CAMPAIGN":
            entry["templateAdvertiserId"] = _normalize_id(account["templateAdvertiserId"])
            entry["templateAdvertiserName"] = account["templateAdvertiserName"]
            entry["templateCampaignId"] = _normalize_id(account["templateCampaignId"])
            entry["templateCampaignName"] = account["templateCampaignName"]
        else:
            entry["templateAdvertiserId"] = _normalize_id(account["templateAdvertiserId"])
            entry["templateAdvertiserName"] = account["templateAdvertiserName"]
            entry["targetCampaignId"] = _normalize_id(account["targetCampaignId"])
            entry["targetCampaignName"] = account["targetCampaignName"]

        if ad_attr_strategy:
            entry["adAttrStrategy"] = ad_attr_strategy
        publish_strategies.append(entry)

    first_account = accounts[0]
    draft_material_strategy = _build_draft_material_strategy(
        mode=mode,
        app_id=int(first_account["appId"]),
        ad_platform_id=int(first_account["adPlatformId"]),
        campaign_cnt_per_advertiser=campaign_cnt_per_advertiser,
        ad_cnt_per_campaign=ad_cnt_per_campaign,
    )

    return {
        "step": 1,
        "ok": True,
        "errors": [],
        "publishStrategies": publish_strategies,
        "draftMaterialStrategy": draft_material_strategy,
        "preStrategyId": pre_strategy_id,
    }


def _build_output_paths(output_dir: str) -> tuple[str, str]:
    os.makedirs(output_dir, exist_ok=True)
    timestamp = datetime.now().strftime("%Y%m%d%H%M%S")
    uid_suffix = uuid.uuid4().hex[-4:]
    state_file = os.path.join(
        output_dir,
        f"normal_plan_publish_state_1_{timestamp}_{uid_suffix}.json",
    )
    similarity_file = os.path.join(
        output_dir,
        f"normal_plan_publish_similarity_{timestamp}_{uid_suffix}.json",
    )
    return state_file, similarity_file


def _write_json(filepath: str, payload: dict[str, Any]) -> None:
    with open(filepath, "w", encoding="utf-8") as file:
        json.dump(payload, file, ensure_ascii=False, indent=2)


def main() -> None:
    if len(sys.argv) < 3:
        print(json.dumps({
            "step": 1,
            "ok": False,
            "errors": ["用法：python validate_and_build_params.py '<json_string>' <output_dir>"],
            "publishStrategies": [],
        }, ensure_ascii=False))
        sys.exit(1)

    raw = sys.argv[1]
    output_dir = sys.argv[2]

    try:
        data = json.loads(raw)
    except json.JSONDecodeError as exc:
        result = {
            "step": 1,
            "ok": False,
            "errors": [f"JSON 解析失败：{exc}"],
            "publishStrategies": [],
        }
        state_file, _ = _build_output_paths(output_dir)
        result["output_file"] = state_file
        _write_json(state_file, result)
        print(json.dumps(result, ensure_ascii=False, indent=2))
        sys.exit(1)

    result = validate(data)
    state_file, similarity_file = _build_output_paths(output_dir)
    result["output_file"] = state_file

    if result["ok"]:
        similarity_payload = {
            "publishStrategies": result["publishStrategies"],
            "materialStrategies": [result["draftMaterialStrategy"]],
        }
        result["similarity_check_file"] = similarity_file
        _write_json(similarity_file, similarity_payload)

    _write_json(state_file, result)
    print(json.dumps(result, ensure_ascii=False, indent=2))
    sys.exit(0 if result["ok"] else 1)


if __name__ == "__main__":
    main()

