"""
普通计划素材 ID 批量发布脚本入口。

action=build:
  1. 使用 MCP 工具校验账户、广告组、广告计划 ID，并从 CSV 结果水合名称/媒体字段
  2. 组装 agent_tool_batch_build_validate 可直接读取的 reqParam JSON
  3. COPY_CAMPAIGN + 广点通时，调用广点通相似校验
  4. 输出包含 AUTO_RELEASE 指定素材池模式和 autoSubmit=true 的最终参数文件
"""

from __future__ import annotations

import csv
import json
import os
import sys
import uuid
from datetime import datetime
from pathlib import Path
from typing import Any

from orchestration.script_runtime.mcp import invoke_mcp_tool


ALLOWED_MCP_TOOLS = {
    "agent_tool_filter_advertiser",
    "agent_tool_filter_ad",
    "agent_tool_campaign_similarity_check",
}

ADJUSTMENT_TYPES = {"FIXED_AMOUNT", "INCREASE_PERCENT", "DECREASE_PERCENT"}
ENTITY_ID_FIELDS = {
    "templateAdvertiserId",
    "templateCampaignId",
    "targetCampaignId",
    "templateAdId",
}


def _result(
    *,
    action: str,
    ok: bool,
    errors: list[str] | None = None,
    **extra: Any,
) -> dict[str, Any]:
    payload = {
        "ok": ok,
        "action": action,
        "errors": errors or [],
    }
    payload.update(extra)
    return payload


def _is_missing(value: Any) -> bool:
    return value is None or (isinstance(value, str) and not value.strip())


def _normalize_required_id(field_name: str, value: Any, errors: list[str]) -> str | None:
    if isinstance(value, bool) or _is_missing(value):
        errors.append(f"{field_name} 必须是纯数字 ID")
        return None
    if isinstance(value, int):
        number = value
    elif isinstance(value, str):
        text = value.strip()
        if not text.isdigit():
            errors.append(f"{field_name} 必须是纯数字 ID，当前值：{text}")
            return None
        number = int(text)
    else:
        errors.append(f"{field_name} 必须是纯数字 ID，当前值：{value}")
        return None
    if number <= 0:
        errors.append(f"{field_name} 必须是正整数 ID，当前值：{value}")
        return None
    return str(number)


def _normalize_target_advertiser_ids(data: dict[str, Any], errors: list[str]) -> list[str]:
    raw_ids = data.get("targetAdvertiserIds")
    if not isinstance(raw_ids, list) or not raw_ids:
        errors.append("targetAdvertiserIds 必须是非空数组")
        return []

    normalized: list[str] = []
    for index, raw_id in enumerate(raw_ids):
        advertiser_id = _normalize_required_id(
            f"targetAdvertiserIds[{index}]",
            raw_id,
            errors,
        )
        if advertiser_id is not None:
            normalized.append(advertiser_id)
    if len(set(normalized)) != len(normalized):
        errors.append("targetAdvertiserIds 不允许重复")
    return normalized


def _positive_int_field(field_name: str, value: Any, errors: list[str]) -> int | None:
    if isinstance(value, bool) or _is_missing(value):
        errors.append(f"{field_name} 必须是正整数")
        return None
    try:
        number = int(str(value).strip())
    except (TypeError, ValueError):
        errors.append(f"{field_name} 必须是正整数，当前值：{value}")
        return None
    if number <= 0:
        errors.append(f"{field_name} 必须是正整数，当前值：{value}")
        return None
    return number


def _normalize_material_id_list(value: Any, errors: list[str]) -> list[str]:
    if not isinstance(value, list) or not value:
        errors.append("materialIdList 必须是非空数组")
        return []

    normalized: list[str] = []
    seen: set[str] = set()
    for index, item in enumerate(value):
        material_id = _normalize_required_id(f"materialIdList[{index}]", item, errors)
        if material_id is None:
            continue
        if material_id in seen:
            errors.append(f"materialIdList 不允许重复，重复值：{material_id}")
            continue
        seen.add(material_id)
        normalized.append(material_id)
    return normalized


def _normalize_number(value: Any) -> int | float | None:
    if isinstance(value, bool):
        return None
    if isinstance(value, (int, float)):
        return int(value) if isinstance(value, float) and value.is_integer() else value
    if isinstance(value, str):
        text = value.strip()
        if not text:
            return None
        try:
            number = float(text)
        except ValueError:
            return None
        return int(number) if number.is_integer() else number
    return None


def _validate_adjustment_block(
    block_name: str,
    raw_block: Any,
    errors: list[str],
) -> dict[str, Any] | None:
    if raw_block is None:
        return None
    if not isinstance(raw_block, dict):
        errors.append(f"adAttrStrategy.{block_name} 必须是对象")
        return None
    adj_type = raw_block.get("type")
    if adj_type not in ADJUSTMENT_TYPES:
        errors.append(
            f"adAttrStrategy.{block_name}.type 非法：{adj_type}，可选值为 {sorted(ADJUSTMENT_TYPES)}"
        )
        return None
    value = _normalize_number(raw_block.get("value"))
    if value is None:
        errors.append(f"adAttrStrategy.{block_name}.value 必须是数值")
        return None
    if value <= 0:
        errors.append(f"adAttrStrategy.{block_name}.value 必须大于 0，当前值：{value}")
        return None
    return {"type": adj_type, "value": value}


def _validate_age_ranges(raw_ranges: Any, errors: list[str]) -> list[dict[str, int]] | None:
    if raw_ranges is None:
        return None
    if not isinstance(raw_ranges, list) or not raw_ranges:
        errors.append("adAttrStrategy.age 至少需要 1 个年龄区间")
        return None
    if len(raw_ranges) > 5:
        errors.append("adAttrStrategy.age 最多支持 5 个年龄区间")
        return None

    normalized: list[dict[str, int]] = []
    for index, item in enumerate(raw_ranges):
        label = f"adAttrStrategy.age[{index}]"
        if not isinstance(item, dict):
            errors.append(f"{label} 必须是对象")
            continue
        if item.get("unlimited") is True or str(item.get("label") or "").strip() == "不限":
            errors.append("年龄“不限”与其它年龄区间不能同时选择，需要重新修改")
            continue
        min_age = _positive_int_field(f"{label}.min", item.get("min"), errors)
        max_age = _positive_int_field(f"{label}.max", item.get("max"), errors)
        if min_age is None or max_age is None:
            continue
        if min_age < 14:
            errors.append(f"{label}.min 不能小于 14")
        if max_age > 66:
            errors.append(f"{label}.max 不能大于 66")
        if max_age - min_age < 4:
            errors.append(f"{label} 年龄区间至少需要覆盖 5 岁，当前为 {min_age}~{max_age}")
        normalized.append({"min": min_age, "max": max_age})

    sorted_ranges = sorted(normalized, key=lambda item: (item["min"], item["max"]))
    for prev, current in zip(sorted_ranges, sorted_ranges[1:]):
        if current["min"] <= prev["max"]:
            errors.append("修改多个年龄范围时不支持重叠区间，请重新修改年龄范围")
            break
    return sorted_ranges


def _validate_ad_attr_strategy(raw_strategy: Any, errors: list[str]) -> dict[str, Any] | None:
    if raw_strategy is None:
        return None
    if not isinstance(raw_strategy, dict):
        errors.append("adAttrStrategy 必须是对象")
        return None

    if not _is_missing(raw_strategy.get("deliveryTime")):
        errors.append("不支持修改投放时间")
    budget_mode = str(raw_strategy.get("budgetMode") or "").strip().upper()
    if budget_mode in {"UNLIMITED", "NO_LIMIT"} or str(raw_strategy.get("budgetMode") or "").strip() == "不限":
        errors.append("预算金额不支持设置为不限")

    normalized: dict[str, Any] = {}
    for key in ("budget", "bid", "deepBid"):
        block = _validate_adjustment_block(key, raw_strategy.get(key), errors)
        if block is not None:
            normalized[key] = block

    age_ranges = _validate_age_ranges(raw_strategy.get("age"), errors)
    if age_ranges is not None:
        normalized["age"] = age_ranges

    return normalized or None


def _normalize_publish_time_strategy(data: dict[str, Any], errors: list[str]) -> dict[str, Any] | None:
    has_publish_time = "publishTimeStrategy" in data and not _is_missing(data.get("publishTimeStrategy"))
    has_time_strategy = "timeStrategy" in data and not _is_missing(data.get("timeStrategy"))
    if has_publish_time and has_time_strategy:
        errors.append("publishTimeStrategy 和 timeStrategy 只能传一个")
        return None
    raw_value = data.get("publishTimeStrategy") if has_publish_time else data.get("timeStrategy")
    if _is_missing(raw_value):
        return None
    if not isinstance(raw_value, dict):
        errors.append("publishTimeStrategy 必须是对象")
        return None
    return dict(raw_value)


def _parse_json_payload(value: Any) -> Any:
    if isinstance(value, (dict, list)):
        return value
    if value is None:
        return None
    if not isinstance(value, str):
        return value
    text = value.strip()
    if not text:
        return ""
    if text.startswith("{") or text.startswith("["):
        return json.loads(text)
    return text


def _invoke_json_tool(tool_name: str, arguments: dict[str, Any]) -> Any:
    output = invoke_mcp_tool(
        tool_name,
        arguments,
        allowed_tools=ALLOWED_MCP_TOOLS,
    )
    return _parse_json_payload(output)


def _has_non_empty_value(value: Any) -> bool:
    if value is None:
        return False
    if isinstance(value, str):
        return bool(value.strip())
    if isinstance(value, list):
        return any(_has_non_empty_value(item) for item in value)
    if isinstance(value, dict):
        return any(_has_non_empty_value(item) for item in value.values())
    return True


def _normalize_ids_text(value: Any) -> str | None:
    if isinstance(value, str):
        return value.strip() or None
    if not isinstance(value, list):
        return None
    parts: list[str] = []
    seen: set[str] = set()
    for item in value:
        if not isinstance(item, (str, int, float)):
            continue
        text = str(item).strip()
        if not text or text in seen:
            continue
        seen.add(text)
        parts.append(text)
    return "、".join(parts) if parts else None


def _field(payload: Any, field_name: str) -> Any:
    if isinstance(payload, dict):
        if field_name in payload:
            return payload[field_name]
        for value in payload.values():
            found = _field(value, field_name)
            if found is not None:
                return found
    if isinstance(payload, list):
        for item in payload:
            found = _field(item, field_name)
            if found is not None:
                return found
    return None


def _payload_has_empty_result(payload: Any) -> bool:
    if payload is None:
        return True
    if isinstance(payload, list):
        return len(payload) == 0
    if isinstance(payload, dict):
        if not payload:
            return True
        for key in ("data", "list", "preview_rows"):
            if key in payload and isinstance(payload[key], list) and not payload[key]:
                return True
    return False


def _csv_path_from_payload(payload: Any, tool_name: str, errors: list[str]) -> Path | None:
    if not isinstance(payload, dict):
        errors.append(f"{tool_name} 返回值不是对象，无法读取 csv_path")
        return None
    raw_csv_path = payload.get("csv_path")
    if _is_missing(raw_csv_path):
        if _payload_has_empty_result(payload):
            errors.append(f"{tool_name} 返回为空，无法完成 ID 校验")
        else:
            errors.append(f"{tool_name} 未返回 csv_path，无法读取校验结果")
        return None
    csv_path = Path(str(raw_csv_path)).expanduser()
    if not csv_path.exists() or not csv_path.is_file():
        errors.append(f"{tool_name} 返回的 csv_path 不存在：{csv_path}")
        return None
    return csv_path


def _read_csv_rows(csv_path: Path) -> list[dict[str, str]]:
    with csv_path.open("r", encoding="utf-8-sig", newline="") as file:
        reader = csv.DictReader(file)
        return [
            {str(key or "").strip(): str(value or "").strip() for key, value in row.items()}
            for row in reader
        ]


def _row_value(row: dict[str, str], *field_names: str) -> str:
    normalized = {
        key.replace("_", "").lower(): value
        for key, value in row.items()
    }
    for field_name in field_names:
        value = normalized.get(field_name.replace("_", "").lower())
        if value:
            return value
    return ""


def _dedupe(values: list[str]) -> list[str]:
    deduped: list[str] = []
    seen: set[str] = set()
    for value in values:
        if value in seen:
            continue
        seen.add(value)
        deduped.append(value)
    return deduped


def _load_advertisers(advertiser_ids: list[str], errors: list[str]) -> dict[str, dict[str, Any]]:
    payload = _invoke_json_tool(
        "agent_tool_filter_advertiser",
        {"reqParam": {"advertiserIds": advertiser_ids}},
    )
    advertiser_id_error = _field(payload, "advertiserIdError")
    if _has_non_empty_value(advertiser_id_error):
        ids_text = _normalize_ids_text(advertiser_id_error) or "、".join(advertiser_ids)
        errors.append(f"账户 ID [{ids_text}] 不存在或无权限，请重新确认后提供正确的 ID。")
        return {}

    csv_path = _csv_path_from_payload(payload, "agent_tool_filter_advertiser", errors)
    if csv_path is None:
        return {}

    rows = _read_csv_rows(csv_path)
    advertisers: dict[str, dict[str, Any]] = {}
    for row in rows:
        advertiser_id = _row_value(row, "advertiserId")
        if not advertiser_id:
            continue
        advertisers[advertiser_id] = {
            "advertiserId": advertiser_id,
            "advertiserName": _row_value(row, "advertiserName"),
            "appId": _row_value(row, "appId"),
            "adPlatformId": _row_value(row, "adPlatformId"),
            "adPlatformName": _row_value(row, "adPlatformName"),
        }

    missing = [advertiser_id for advertiser_id in advertiser_ids if advertiser_id not in advertisers]
    if missing:
        errors.append(f"账户 ID [{'、'.join(missing)}] 不存在或无权限，请重新确认后提供正确的 ID。")
        return {}

    for advertiser_id in advertiser_ids:
        advertiser = advertisers[advertiser_id]
        if not advertiser["advertiserName"]:
            errors.append(f"账户 ID [{advertiser_id}] 校验结果缺少 advertiserName")
        app_id = _positive_int_field(f"账户 {advertiser_id}.appId", advertiser["appId"], errors)
        ad_platform_id = _positive_int_field(
            f"账户 {advertiser_id}.adPlatformId",
            advertiser["adPlatformId"],
            errors,
        )
        if app_id is not None:
            advertiser["appId"] = app_id
        if ad_platform_id is not None:
            advertiser["adPlatformId"] = ad_platform_id
    return advertisers


def _load_ad_entities(
    *,
    advertiser_id: str,
    campaign_ids: list[str],
    ad_ids: list[str],
    errors: list[str],
) -> tuple[dict[str, str], dict[str, str]]:
    req_param: dict[str, Any] = {"advertiserIds": [advertiser_id]}
    if campaign_ids:
        req_param["campaignIds"] = campaign_ids
    if ad_ids:
        req_param["adIds"] = ad_ids

    payload = _invoke_json_tool("agent_tool_filter_ad", {"reqParam": req_param})

    campaign_id_error = _field(payload, "campaignIdError")
    if _has_non_empty_value(campaign_id_error):
        ids_text = _normalize_ids_text(campaign_id_error) or "、".join(campaign_ids)
        errors.append(
            f"广告组 ID [{ids_text}] 在账户 [{advertiser_id}] 下不存在，请重新确认后提供正确的 ID。"
        )
        return {}, {}

    ad_id_error = _field(payload, "adIdError")
    if _has_non_empty_value(ad_id_error):
        ids_text = _normalize_ids_text(ad_id_error) or "、".join(ad_ids)
        errors.append(
            f"广告计划 ID [{ids_text}] 在账户 [{advertiser_id}] 下不存在，请重新确认后提供正确的 ID。"
        )
        return {}, {}

    csv_path = _csv_path_from_payload(payload, "agent_tool_filter_ad", errors)
    if csv_path is None:
        return {}, {}

    campaign_names: dict[str, str] = {}
    ad_names: dict[str, str] = {}
    for row in _read_csv_rows(csv_path):
        campaign_id = _row_value(row, "campaignId")
        if campaign_id:
            campaign_names[campaign_id] = _row_value(row, "campaignName")
        ad_id = _row_value(row, "adId")
        if ad_id:
            ad_names[ad_id] = _row_value(row, "adName")

    missing_campaigns = [campaign_id for campaign_id in campaign_ids if campaign_id not in campaign_names]
    if missing_campaigns:
        errors.append(
            f"广告组 ID [{'、'.join(missing_campaigns)}] 在账户 [{advertiser_id}] 下不存在，请重新确认后提供正确的 ID。"
        )
    missing_ads = [ad_id for ad_id in ad_ids if ad_id not in ad_names]
    if missing_ads:
        errors.append(
            f"广告计划 ID [{'、'.join(missing_ads)}] 在账户 [{advertiser_id}] 下不存在，请重新确认后提供正确的 ID。"
        )
    return campaign_names, ad_names


def _load_template_ad(
    *,
    ad_platform_name: str,
    template_ad_id: str,
    errors: list[str],
) -> dict[str, Any] | None:
    payload = _invoke_json_tool(
        "agent_tool_filter_ad",
        {
            "reqParam": {
                "adPlatformNames": [ad_platform_name],
                "adIds": [template_ad_id],
            }
        },
    )
    ad_id_error = _field(payload, "adIdError")
    if _has_non_empty_value(ad_id_error):
        ids_text = _normalize_ids_text(ad_id_error) or template_ad_id
        errors.append(
            f"模板广告计划 ID [{ids_text}] 在媒体平台 [{ad_platform_name}] 下不存在或无权限。"
        )
        return None
    if _payload_has_empty_result(payload):
        errors.append(
            f"模板广告计划 ID [{template_ad_id}] 在媒体平台 [{ad_platform_name}] 下不存在或无权限。"
        )
        return None

    csv_path = _csv_path_from_payload(payload, "agent_tool_filter_ad", errors)
    if csv_path is None:
        return None

    matched_rows = [
        row
        for row in _read_csv_rows(csv_path)
        if _row_value(row, "adId") == template_ad_id
    ]
    mappings = {
        (_row_value(row, "advertiserId"), _row_value(row, "campaignId"))
        for row in matched_rows
    }
    if not matched_rows:
        errors.append(
            f"模板广告计划 ID [{template_ad_id}] 在媒体平台 [{ad_platform_name}] 下不存在或无权限。"
        )
        return None
    if len(mappings) != 1:
        errors.append(
            f"模板广告计划 ID [{template_ad_id}] 反查到多个账户或广告组，无法唯一确定模板。"
        )
        return None

    row = matched_rows[0]
    template = {
        "advertiserId": _row_value(row, "advertiserId"),
        "advertiserName": _row_value(row, "advertiserName"),
        "appId": _row_value(row, "appId"),
        "adPlatformId": _row_value(row, "adPlatformId"),
        "adPlatformName": _row_value(row, "adPlatformName"),
        "campaignId": _row_value(row, "campaignId"),
        "campaignName": _row_value(row, "campaignName"),
        "adId": template_ad_id,
        "adName": _row_value(row, "adName"),
    }
    for field_name in ("advertiserId", "advertiserName", "campaignId", "campaignName", "adPlatformName"):
        if not template[field_name]:
            errors.append(f"模板广告计划 ID [{template_ad_id}] 反查结果缺少 {field_name}")
    app_id = _positive_int_field("模板广告计划反查结果 appId", template["appId"], errors)
    ad_platform_id = _positive_int_field(
        "模板广告计划反查结果 adPlatformId",
        template["adPlatformId"],
        errors,
    )
    if template["adPlatformName"] and template["adPlatformName"] != ad_platform_name:
        errors.append(
            f"模板广告计划所属媒体为 [{template['adPlatformName']}]，与目标账户媒体 [{ad_platform_name}] 不一致。"
        )
    if errors:
        return None
    assert app_id is not None
    assert ad_platform_id is not None
    template["appId"] = app_id
    template["adPlatformId"] = ad_platform_id
    return template


def _ensure_single_app_and_media(advertisers: list[dict[str, Any]], errors: list[str]) -> None:
    app_ids = {advertiser.get("appId") for advertiser in advertisers}
    platform_ids = {advertiser.get("adPlatformId") for advertiser in advertisers}
    platform_names = {
        str(advertiser.get("adPlatformName") or "").strip()
        for advertiser in advertisers
        if str(advertiser.get("adPlatformName") or "").strip()
    }
    if len(app_ids) > 1:
        errors.append(f"所有账户的 appId 必须一致，当前存在多个值：{app_ids}")
    if len(platform_ids) > 1:
        errors.append(f"所有账户的 adPlatformId 必须一致，当前存在多个值：{platform_ids}")
    if len(platform_names) > 1:
        errors.append(f"一次只支持单媒体发布，当前检测到多个媒体平台：{platform_names}")


def _ad_capacity_per_account(
    *,
    mode: str,
    campaign_cnt_per_advertiser: int | None,
    ad_cnt_per_campaign: int,
) -> int:
    if mode == "COPY_CAMPAIGN":
        assert campaign_cnt_per_advertiser is not None
        return campaign_cnt_per_advertiser * ad_cnt_per_campaign
    return ad_cnt_per_campaign


def _total_ad_capacity(
    *,
    mode: str,
    account_count: int,
    campaign_cnt_per_advertiser: int | None,
    ad_cnt_per_campaign: int,
) -> int:
    return account_count * _ad_capacity_per_account(
        mode=mode,
        campaign_cnt_per_advertiser=campaign_cnt_per_advertiser,
        ad_cnt_per_campaign=ad_cnt_per_campaign,
    )


def _minimum_material_count(
    *,
    total_ad_capacity: int,
    material_cnt_per_ad: int,
) -> int:
    return (total_ad_capacity - 1) * material_cnt_per_ad + 1


def _build_confirmation_summary(req_param: dict[str, Any]) -> str:
    publish_strategies = req_param["publishStrategies"]
    material_strategy = req_param["materialStrategies"][0]
    layout_rules = material_strategy["layoutRules"]
    mode = publish_strategies[0]["type"]
    account_count = len(publish_strategies)
    ad_cnt_per_campaign = layout_rules["adCntPerCampaign"]
    material_cnt_per_ad = layout_rules["materialCntPerAd"]
    campaign_cnt_per_advertiser = layout_rules.get("campaignCntPerAdvertiser")
    if mode == "COPY_CAMPAIGN":
        total_campaigns = account_count * campaign_cnt_per_advertiser
    else:
        total_campaigns = account_count
    total_ads = total_campaigns * ad_cnt_per_campaign
    full_material_count = total_ads * material_cnt_per_ad
    minimum_material_count = _minimum_material_count(
        total_ad_capacity=total_ads,
        material_cnt_per_ad=material_cnt_per_ad,
    )

    account_lines = [
        f"- {item['advertiserId']}（{item['advertiserName']}）"
        for item in publish_strategies
    ]
    first = publish_strategies[0]
    if mode == "COPY_CAMPAIGN":
        template_line = (
            f"- 模板账户：{first['templateAdvertiserId']}（{first['templateAdvertiserName']}）\n"
            f"- 模板广告组：{first['templateCampaignId']}（{first['templateCampaignName']}）\n"
            f"- 模板计划：{first['templateAdId']}（{first.get('templateAdName', '')}）"
        )
        quantity_line = (
            f"- 每账户新建广告组数：{campaign_cnt_per_advertiser}\n"
            f"- 每广告组计划数：{ad_cnt_per_campaign}\n"
            f"- 每计划素材数：{material_cnt_per_ad}"
        )
    else:
        template_line = (
            f"- 模板账户：{first['templateAdvertiserId']}（{first['templateAdvertiserName']}）\n"
            f"- 目标广告组：{first['targetCampaignId']}（{first['targetCampaignName']}）\n"
            f"- 模板计划：{first['templateAdId']}（{first.get('templateAdName', '')}）"
        )
        quantity_line = (
            "- 追加广告组数：1\n"
            f"- 每广告组计划数：{ad_cnt_per_campaign}\n"
            f"- 每计划素材数：{material_cnt_per_ad}"
        )

    publish_time = req_param.get("publishTimeStrategy") or {"type": "未指定"}
    return "\n".join(
        [
            "本次普通计划素材 ID 发布小结：",
            "",
            "目标账户：",
            *account_lines,
            "",
            "模板/目标信息：",
            template_line,
            "",
            "批量数量：",
            quantity_line,
            f"- 总广告组数：{total_campaigns}",
            f"- 总计划数：{total_ads}",
            f"- 满额素材数：{full_material_count}",
            f"- 最低所需素材数：{minimum_material_count}",
            "",
            "素材规则：",
            "- 使用 AUTO_RELEASE 指定素材池模式",
            f"- materialIdList 数量：{len(material_strategy['materialIdList'])}",
            "- 除最后一个计划外每个计划满素材，最后一个计划至少 1 个素材",
            "- 每个计划使用不同素材，不复用素材 ID",
            "",
            f"发布时间策略：{json.dumps(publish_time, ensure_ascii=False)}",
            "",
            "请确认以上信息无误后，再继续自动提交。",
        ]
    )


def _build_material_strategy(
    *,
    app_id: int,
    ad_platform_id: int,
    mode: str,
    campaign_cnt_per_advertiser: int | None,
    ad_cnt_per_campaign: int,
    material_cnt_per_ad: int,
    material_id_list: list[str],
) -> dict[str, Any]:
    layout_rules = {
        "adCntPerCampaign": ad_cnt_per_campaign,
        "materialCntPerAd": material_cnt_per_ad,
    }
    if mode == "COPY_CAMPAIGN":
        layout_rules["campaignCntPerAdvertiser"] = campaign_cnt_per_advertiser
    return {
        "type": "AUTO_RELEASE",
        "appId": app_id,
        "adPlatformId": ad_platform_id,
        "materialIdList": material_id_list,
        "layoutRules": layout_rules,
    }


def _write_json(output_dir: str, prefix: str, payload: dict[str, Any]) -> str:
    os.makedirs(output_dir, exist_ok=True)
    timestamp = datetime.now().strftime("%Y%m%d%H%M%S")
    uid_suffix = uuid.uuid4().hex[-4:]
    filepath = os.path.join(output_dir, f"{prefix}_{timestamp}_{uid_suffix}.json")
    with open(filepath, "w", encoding="utf-8") as file:
        json.dump(payload, file, ensure_ascii=False, indent=2)
    return filepath


def _needs_similarity_check(req_param: dict[str, Any]) -> bool:
    publish_strategies = req_param.get("publishStrategies")
    if not isinstance(publish_strategies, list) or not publish_strategies:
        return False
    if publish_strategies[0].get("type") != "COPY_CAMPAIGN":
        return False
    material_strategies = req_param.get("materialStrategies")
    if not isinstance(material_strategies, list) or not material_strategies:
        return False
    return int(material_strategies[0].get("adPlatformId") or 0) == 3


def _similarity_failure_messages(payload: Any) -> list[str]:
    if not isinstance(payload, dict):
        return []
    failure = payload.get("failure")
    if not _has_non_empty_value(failure):
        return []
    if isinstance(failure, list):
        messages: list[str] = []
        for item in failure:
            if isinstance(item, dict):
                message = str(item.get("message") or "").strip()
                if message:
                    messages.append(message)
            elif str(item).strip():
                messages.append(str(item).strip())
        return messages or ["存在目标账号命中高相似广告组，请调整年龄定向后重试。"]
    if isinstance(failure, dict):
        message = str(failure.get("message") or "").strip()
        return [message] if message else ["存在目标账号命中高相似广告组，请调整年龄定向后重试。"]
    return [str(failure).strip() or "存在目标账号命中高相似广告组，请调整年龄定向后重试。"]


def _run_similarity_check(req_param: dict[str, Any], output_dir: str) -> tuple[str | None, list[str]]:
    if not _needs_similarity_check(req_param):
        return None, []
    similarity_file = _write_json(
        output_dir,
        "normal_plan_material_id_similarity",
        {
            "publishStrategies": req_param["publishStrategies"],
            "materialStrategies": req_param["materialStrategies"],
        },
    )
    payload = _invoke_json_tool(
        "agent_tool_campaign_similarity_check",
        {"reqParamPath": similarity_file},
    )
    messages = _similarity_failure_messages(payload)
    return similarity_file, messages


def _validate_input(data: dict[str, Any]) -> tuple[dict[str, Any], list[str]]:
    errors: list[str] = []
    mode = str(data.get("mode") or "").strip().upper()
    target_advertiser_ids = _normalize_target_advertiser_ids(data, errors)

    if mode not in {"COPY_CAMPAIGN", "APPEND_AD"}:
        errors.append(f"mode 字段无效：'{mode}'，必须是 COPY_CAMPAIGN 或 APPEND_AD")

    if not _is_missing(data.get("preStrategyId")):
        errors.append("该简化流程只支持直接传素材 ID，不支持算法素材筛选预设或 preStrategyId")

    target_campaign_id = None
    template_ad_id = _normalize_required_id("templateAdId", data.get("templateAdId"), errors)

    if mode == "APPEND_AD":
        if len(target_advertiser_ids) > 1:
            errors.append("APPEND_AD 模式仅支持单个目标账户")
        target_campaign_id = _normalize_required_id(
            "targetCampaignId",
            data.get("targetCampaignId"),
            errors,
        )

    ad_cnt_per_campaign = _positive_int_field(
        "adCntPerCampaign",
        data.get("adCntPerCampaign"),
        errors,
    )
    material_cnt_per_ad = _positive_int_field(
        "materialCntPerAd",
        data.get("materialCntPerAd"),
        errors,
    )
    campaign_cnt_per_advertiser = None
    if mode == "COPY_CAMPAIGN":
        campaign_cnt_per_advertiser = _positive_int_field(
            "campaignCntPerAdvertiser",
            data.get("campaignCntPerAdvertiser"),
            errors,
        )
    elif not _is_missing(data.get("campaignCntPerAdvertiser")):
        errors.append("APPEND_AD 模式禁止填写 campaignCntPerAdvertiser")

    material_id_list = _normalize_material_id_list(data.get("materialIdList"), errors)
    publish_time_strategy = _normalize_publish_time_strategy(data, errors)
    ad_attr_strategy = _validate_ad_attr_strategy(data.get("adAttrStrategy"), errors)

    if (
        not errors
        and mode
        and ad_cnt_per_campaign is not None
        and material_cnt_per_ad is not None
        and material_id_list
    ):
        total_ad_capacity = _total_ad_capacity(
            mode=mode,
            account_count=len(target_advertiser_ids),
            campaign_cnt_per_advertiser=campaign_cnt_per_advertiser,
            ad_cnt_per_campaign=ad_cnt_per_campaign,
        )
        minimum_count = _minimum_material_count(
            total_ad_capacity=total_ad_capacity,
            material_cnt_per_ad=material_cnt_per_ad,
        )
        if len(material_id_list) < minimum_count:
            errors.append(
                "materialIdList 数量不足，必须至少满足 "
                "(账号数 × 每账号计划容量 - 1) × materialCntPerAd + 1，"
                "即除最后一个计划外每个计划都需满素材、最后一个计划至少 1 个素材；"
                f"当前最低需要 {minimum_count} 个，"
                f"实际传入 {len(material_id_list)} 个"
            )

    return (
        {
            "mode": mode,
            "targetAdvertiserIds": target_advertiser_ids,
            "targetCampaignId": target_campaign_id,
            "templateAdId": template_ad_id,
            "campaignCntPerAdvertiser": campaign_cnt_per_advertiser,
            "adCntPerCampaign": ad_cnt_per_campaign,
            "materialCntPerAd": material_cnt_per_ad,
            "materialIdList": material_id_list,
            "publishTimeStrategy": publish_time_strategy,
            "adAttrStrategy": ad_attr_strategy,
        },
        errors,
    )


def build(data: dict[str, Any], output_dir: str) -> dict[str, Any]:
    normalized, errors = _validate_input(data)
    if errors:
        return _result(action="build", ok=False, errors=errors)

    mode = normalized["mode"]
    target_advertiser_ids = normalized["targetAdvertiserIds"]
    template_ad_id = normalized["templateAdId"]

    advertisers = _load_advertisers(_dedupe(target_advertiser_ids), errors)
    if errors:
        return _result(action="build", ok=False, errors=errors)

    _ensure_single_app_and_media(
        [advertisers[advertiser_id] for advertiser_id in _dedupe(target_advertiser_ids)],
        errors,
    )
    if errors:
        return _result(action="build", ok=False, errors=errors)

    campaign_names: dict[str, str] = {}
    if mode == "APPEND_AD":
        target_advertiser_id = target_advertiser_ids[0]
        target_campaign_id = normalized["targetCampaignId"]
        campaign_names, _ = _load_ad_entities(
            advertiser_id=target_advertiser_id,
            campaign_ids=[target_campaign_id],
            ad_ids=[],
            errors=errors,
        )
        if errors:
            return _result(action="build", ok=False, errors=errors)

    target_platform_name = str(advertisers[target_advertiser_ids[0]].get("adPlatformName") or "").strip()
    if not target_platform_name:
        return _result(
            action="build",
            ok=False,
            errors=["目标账户校验结果缺少 adPlatformName，无法反查模板广告计划"],
        )
    template = _load_template_ad(
        ad_platform_name=target_platform_name,
        template_ad_id=template_ad_id,
        errors=errors,
    )
    if errors or template is None:
        return _result(action="build", ok=False, errors=errors)
    _ensure_single_app_and_media(
        [advertisers[advertiser_id] for advertiser_id in _dedupe(target_advertiser_ids)] + [template],
        errors,
    )
    if errors:
        return _result(action="build", ok=False, errors=errors)

    publish_strategies: list[dict[str, Any]] = []
    if mode == "COPY_CAMPAIGN":
        for target_advertiser_id in target_advertiser_ids:
            target_advertiser = advertisers[target_advertiser_id]
            entry = {
                "type": "COPY_CAMPAIGN",
                "appId": target_advertiser["appId"],
                "adPlatformId": target_advertiser["adPlatformId"],
                "advertiserId": target_advertiser["advertiserId"],
                "advertiserName": target_advertiser["advertiserName"],
                "templateAdvertiserId": template["advertiserId"],
                "templateAdvertiserName": template["advertiserName"],
                "templateCampaignId": template["campaignId"],
                "templateCampaignName": template["campaignName"],
                "templateAdId": template_ad_id,
                "templateAdName": template["adName"],
            }
            if normalized["adAttrStrategy"]:
                entry["adAttrStrategy"] = normalized["adAttrStrategy"]
            publish_strategies.append(entry)
    else:
        target_advertiser_id = target_advertiser_ids[0]
        target_campaign_id = normalized["targetCampaignId"]
        target_advertiser = advertisers[target_advertiser_id]
        entry = {
            "type": "APPEND_AD",
            "appId": target_advertiser["appId"],
            "adPlatformId": target_advertiser["adPlatformId"],
            "advertiserId": target_advertiser["advertiserId"],
            "advertiserName": target_advertiser["advertiserName"],
            "templateAdvertiserId": template["advertiserId"],
            "templateAdvertiserName": template["advertiserName"],
            "targetCampaignId": target_campaign_id,
            "targetCampaignName": campaign_names[target_campaign_id],
            "templateAdId": template_ad_id,
            "templateAdName": template["adName"],
        }
        if normalized["adAttrStrategy"]:
            entry["adAttrStrategy"] = normalized["adAttrStrategy"]
        publish_strategies.append(entry)

    first_strategy = publish_strategies[0]
    material_strategy = _build_material_strategy(
        app_id=first_strategy["appId"],
        ad_platform_id=first_strategy["adPlatformId"],
        mode=mode,
        campaign_cnt_per_advertiser=normalized["campaignCntPerAdvertiser"],
        ad_cnt_per_campaign=normalized["adCntPerCampaign"],
        material_cnt_per_ad=normalized["materialCntPerAd"],
        material_id_list=normalized["materialIdList"],
    )
    req_param: dict[str, Any] = {
        "publishStrategies": publish_strategies,
        "materialStrategies": [material_strategy],
        "autoSubmit": True,
    }
    if normalized["publishTimeStrategy"] is not None:
        req_param["publishTimeStrategy"] = normalized["publishTimeStrategy"]

    similarity_file, similarity_messages = _run_similarity_check(req_param, output_dir)
    if similarity_messages:
        return _result(
            action="build",
            ok=False,
            errors=[
                "广点通目标账号相似广告组定向校验未全部通过，已停止后续流程。",
                *similarity_messages,
            ],
            similarity_check_file=similarity_file,
        )

    output_file = _write_json(
        output_dir,
        "normal_plan_material_id_publish_req",
        req_param,
    )
    confirmation_summary = _build_confirmation_summary(req_param)
    return _result(
        action="build",
        ok=True,
        errors=[],
        publishStrategies=publish_strategies,
        materialStrategies=[material_strategy],
        confirmation_summary=confirmation_summary,
        output_file=output_file,
        similarity_check_file=similarity_file,
        next_action="user_confirm_then_agent_tool_batch_build_validate",
    )


def run(data: dict[str, Any], output_dir: str) -> dict[str, Any]:
    action = str(data.get("action") or "").strip().lower()
    if action == "build":
        return build(data, output_dir)
    return _result(
        action=action or "unknown",
        ok=False,
        errors=["action 必须是 build"],
    )


def main() -> None:
    if len(sys.argv) < 3:
        print(json.dumps(
            _result(
                action="unknown",
                ok=False,
                errors=["用法：python runner.py '<json_string>' <output_dir>"],
            ),
            ensure_ascii=False,
        ))
        sys.exit(1)

    output_dir = sys.argv[2]
    try:
        data = json.loads(sys.argv[1])
    except json.JSONDecodeError as exc:
        print(json.dumps(
            _result(action="unknown", ok=False, errors=[f"JSON 解析失败：{exc}"]),
            ensure_ascii=False,
        ))
        sys.exit(1)

    if not isinstance(data, dict):
        result = _result(action="unknown", ok=False, errors=["输入 JSON 顶层必须是对象"])
    else:
        result = run(data, output_dir)

    print(json.dumps(result, ensure_ascii=False, indent=2))
    sys.exit(0 if result.get("ok") else 1)


if __name__ == "__main__":
    main()

