"""
用户流量包标签 Skill - Runner

文件存储路径：{PACKAGE_TAG_DIR}/{user_id}.yaml
支持操作：read（读取）、write（全量覆盖写入）、delete（删除特定的流量包）
"""
import os
import re
import sys
from pathlib import Path

# 将项目根目录加入 sys.path，以便导入 config
_PROJECT_ROOT = Path(__file__).resolve().parent.parent.parent
if str(_PROJECT_ROOT) not in sys.path:
    sys.path.insert(0, str(_PROJECT_ROOT))

from config import PACKAGE_TAG_DIR  # noqa: E402

_PERSONAL_DIR = Path(PACKAGE_TAG_DIR)

# 安全的 user_id：只保留字母、数字、连字符、下划线
_SAFE_UID_RE = re.compile(r"[^\w\-]")


def _safe_uid(user_id: str) -> str:
    return _SAFE_UID_RE.sub("_", (user_id or "default").strip()) or "default"


def _kb_path(user_id: str) -> Path:
    return _PERSONAL_DIR / f"{_safe_uid(user_id)}.yaml"


def _validate_yaml(content: str) -> str | None:
    """返回错误信息；None 表示合法。"""
    try:
        import yaml
        parsed = yaml.safe_load(content)
        if parsed and not isinstance(parsed, dict):
             return "YAML 格式错误：顶层必须是字典结构"
        return None
    except Exception as e:
        return f"YAML 格式错误：{e}"


def run(fields: dict) -> dict:
    """
    fields:
        operation (str): "read" | "write"
        content   (str): write 时必填，完整 YAML 文本
        user_id   (str): 由 skill_tool 自动注入
    """
    user_id = (fields.get("user_id") or "default").strip()
    operation = (fields.get("operation") or "read").strip().lower()
    path = _kb_path(user_id)

    # ── READ ──────────────────────────────────────────────────────────────────
    if operation == "read":
        if not path.exists():
            return {
                "status": "ok",
                "content": "",
                "message": (
                    "知识库当前为空。\n"
                    "你可以通过对话告诉我需要记录的内容，例如：\n"
                    "「帮我把'TT高次留流量包'加到高次留流量包分类里」"
                ),
            }
        content = path.read_text(encoding="utf-8")
        return {"status": "ok", "content": content}

    # ── WRITE ─────────────────────────────────────────────────────────────────
    if operation == "write":
        content = (fields.get("content") or "").strip()
        if not content:
            return {"status": "error", "message": "content 不能为空，请提供完整的 YAML 内容"}

        err = _validate_yaml(content)
        if err:
            return {"status": "error", "message": err}

        # 在代码层面进行保底防御：合并原有文件的其他根节点
        import yaml
        try:
            new_data = yaml.safe_load(content) or {}
            if path.exists():
                old_content = path.read_text(encoding="utf-8")
                old_data = yaml.safe_load(old_content) or {}
                # 遍历旧数据，如果新数据中丢失了非 union_packages 的根节点，则自动补回
                for k, v in old_data.items():
                    if k not in ["union_packages", "version", "updated_at"] and k not in new_data:
                        new_data[k] = v

            # 将合并后的数据重新转回 YAML
            final_content = yaml.dump(new_data, allow_unicode=True, sort_keys=False, default_flow_style=False)
        except Exception as e:
            return {"status": "error", "message": f"处理 YAML 数据时发生错误：{e}"}

        _PERSONAL_DIR.mkdir(parents=True, exist_ok=True)
        path.write_text(final_content, encoding="utf-8")
        return {"status": "ok", "message": f"流量包标签已更新（{path.name}）"}

    # ── DELETE ────────────────────────────────────────────────────────────────
    if operation == "delete":
        if not path.exists():
            return {"status": "ok", "message": "知识库为空，无需删除。"}

        packages_to_delete = fields.get("package_names") or []
        if not packages_to_delete or not isinstance(packages_to_delete, list):
            return {"status": "error", "message": "请在 package_names 数组中提供要删除的流量包名称"}

        import yaml
        try:
            content = path.read_text(encoding="utf-8")
            data = yaml.safe_load(content) or {}

            if "union_packages" in data and isinstance(data["union_packages"], dict):
                deleted_count = 0
                packages_set = set(packages_to_delete)

                # 遍历所有分类，移除目标流量包
                for category, pkgs in data["union_packages"].items():
                    if isinstance(pkgs, list):
                        original_len = len(pkgs)
                        data["union_packages"][category] = [p for p in pkgs if p not in packages_set]
                        deleted_count += (original_len - len(data["union_packages"][category]))

                if deleted_count > 0:
                    final_content = yaml.dump(data, allow_unicode=True, sort_keys=False, default_flow_style=False)
                    path.write_text(final_content, encoding="utf-8")
                    return {"status": "ok", "message": f"成功删除了 {deleted_count} 个流量包标签映射。"}
                else:
                    return {"status": "ok", "message": "未找到指定的流量包，无需删除。"}
            else:
                return {"status": "ok", "message": "当前没有流量包映射数据。"}

        except Exception as e:
            return {"status": "error", "message": f"处理删除操作时发生错误：{e}"}

    # ── UNKNOWN ───────────────────────────────────────────────────────────────
    return {
        "status": "error",
        "message": f"未知操作：{operation!r}，支持的操作为 read / write / delete",
    }

