"""
merge_xingguang_params.py
─────────────────────────
阶段二：圈选参数已持久化后的最终参数合并（头条星广联投版）

职责：
  从阶段一产出的状态文件中读取 publishStrategies、distributionType 和 chooseParams，
  组装 AUTO_LAYOUT_FROM_CHOOSE_ID 格式的 materialStrategies（含 distributionType），
  输出可直接传给 agent_tool_batch_build_validate 和 render_batch_publish_confirm 的完整参数，
  并将结果写入 <output_dir>/xingguang_publish_state_2_{timestamp}_{uuid后四位}.json

重要约束：
  本脚本只从文件读取所有参数，不接受命令行传入 chooseId / materialCntPerAd / distributionType 等字段。
  必须先调用 validate_and_build_params.py（写入 distributionType）和
  save_choose_params.py（写入 chooseParams），本脚本才能正常运行。
  如果状态文件中缺少 chooseParams 或 distributionType 字段，直接报错，不提供任何备用路径。

用法：
  python merge_xingguang_params.py <step1_file_path> <output_dir>

参数说明：
  step1_file_path   阶段一脚本输出的 JSON 文件绝对路径（即脚本一 output_file 字段的值）。
                    该文件必须已包含：
                    - distributionType（由 validate_and_build_params.py 写入）
                    - chooseParams（由 save_choose_params.py 写入）

  output_dir        必填，指定输出目录，由调用方传入 DATA_DIR/tasks_run

AUTO_LAYOUT_FROM_CHOOSE_ID 约束（来自 agent_tool_batch_build_validate schema）：
  - 整单只允许 1 条 materialStrategies
  - chooseId 必须是长度为 1 的非空字符串数组（值本身需为正整数 ID）
  - distributionType 必填；COPY_CAMPAIGN 可选值 EVEN / ALL，APPEND_AD 仅允许 EVEN
  - materialCntPerAd 必填，且必须 > 0
  - campaignCntPerAdvertiser 仅 COPY_CAMPAIGN 时必填；APPEND_AD 时禁止填写
  - adCntPerCampaign 两种模式都必填
  - advertiserId、advertiserName、materialIdList 禁止填写
  - appId / adPlatformId 必须与 publishStrategies[0] 保持一致

输出文件命名：
  xingguang_publish_state_2_{timestamp}_{uuid后四位}.json

输出（stdout + 写文件）：
{
  "step": 2,
  "ok": true | false,
  "errors": ["错误描述", ...],
  "publishStrategies": [...],    // 完整版，直接用于 agent_tool_batch_build_validate 和 render_batch_publish_confirm
  "materialStrategies": [...],   // AUTO_LAYOUT_FROM_CHOOSE_ID 格式，含 distributionType
  "output_file": "/path/to/xingguang_publish_state_2_20260601135601_cd34.json"
}
"""

import json
import os
import sys
import uuid
from datetime import datetime

VALID_DISTRIBUTION_TYPES = {"EVEN", "ALL"}


def merge(
    publish_strategies: list,
    choose_params: dict,
    distribution_type: str,
    xingguang_context: dict | None = None,
) -> dict:
    errors = []
    if not publish_strategies:
        errors.append("publishStrategies 为空")
        return {"step": 2, "ok": False, "errors": errors,
                "publishStrategies": [], "materialStrategies": []}

    # ── 从 publishStrategies[0] 获取 appId / adPlatformId / mode ───────────────
    first = publish_strategies[0]
    app_id = first.get("appId")
    ad_platform_id = first.get("adPlatformId")
    mode = first.get("type", "").upper()

    if not app_id:
        errors.append("publishStrategies[0] 缺少 appId")
    if not ad_platform_id:
        errors.append("publishStrategies[0] 缺少 adPlatformId")
    if mode not in ("COPY_CAMPAIGN", "APPEND_AD"):
        errors.append(f"publishStrategies[0].type 无效：'{mode}'，必须是 COPY_CAMPAIGN 或 APPEND_AD")

    if errors:
        return {"step": 2, "ok": False, "errors": errors,
                "publishStrategies": [], "materialStrategies": []}

    # ── 校验 distributionType ───────────────────────────────────────────────────
    if not distribution_type:
        errors.append(
            "状态文件中缺少 distributionType，请确认脚本一（validate_and_build_params.py）已正确执行"
        )
    elif mode == "APPEND_AD" and distribution_type != "EVEN":
        errors.append(
            f"APPEND_AD 模式仅支持 EVEN（平均分配），当前值：'{distribution_type}'"
        )
    elif distribution_type not in VALID_DISTRIBUTION_TYPES:
        errors.append(
            f"distributionType 值非法：'{distribution_type}'，可选值为 EVEN 或 ALL"
        )

    # ── 校验 chooseId ───────────────────────────────────────────────────────────
    choose_id_raw = choose_params.get("chooseId")
    choose_id = None
    if choose_id_raw is None:
        errors.append(
            "状态文件中缺少 chooseId，请先调用 save_choose_params.py 将圈选参数写入文件后再执行本脚本"
        )
    else:
        try:
            choose_id = int(choose_id_raw)
            if choose_id <= 0:
                errors.append(f"chooseId 必须是正整数，当前值：{choose_id}")
        except (ValueError, TypeError):
            errors.append(f"chooseId 必须是整数，当前值：{choose_id_raw}")

    # ── 校验 materialCntPerAd ───────────────────────────────────────────────────
    material_cnt_raw = choose_params.get("materialCntPerAd")
    material_cnt = None
    if material_cnt_raw is None:
        errors.append(
            "状态文件中缺少 materialCntPerAd，请先调用 save_choose_params.py 将圈选参数写入文件后再执行本脚本"
        )
    else:
        try:
            material_cnt = int(material_cnt_raw)
            if material_cnt <= 0:
                errors.append(f"materialCntPerAd 必须大于 0，当前值：{material_cnt}")
        except (ValueError, TypeError):
            errors.append(f"materialCntPerAd 必须是整数，当前值：{material_cnt_raw}")

    # ── 处理 campaignCntPerAdvertiser ──────────────────────────────────────────
    campaign_cnt_raw = choose_params.get("campaignCntPerAdvertiser")
    campaign_cnt = None

    if mode == "COPY_CAMPAIGN":
        if campaign_cnt_raw is None:
            errors.append(
                "状态文件中缺少 campaignCntPerAdvertiser，COPY_CAMPAIGN 模式下此字段必填，"
                "请先调用 save_choose_params.py 将圈选参数写入文件后再执行本脚本"
            )
        else:
            try:
                campaign_cnt = int(campaign_cnt_raw)
                if campaign_cnt <= 0:
                    errors.append(f"campaignCntPerAdvertiser 必须大于 0，当前值：{campaign_cnt}")
            except (ValueError, TypeError):
                errors.append(f"campaignCntPerAdvertiser 必须是整数，当前值：{campaign_cnt_raw}")
    else:
        if campaign_cnt_raw is not None:
            errors.append(
                f"APPEND_AD 模式下禁止填写 campaignCntPerAdvertiser，当前值：{campaign_cnt_raw}"
            )

    # ── 处理 adCntPerCampaign（两种模式都必填）──────────────────────────────────
    ad_cnt_raw = choose_params.get("adCntPerCampaign")
    ad_cnt = None

    if ad_cnt_raw is None:
        errors.append(
            f"状态文件中缺少 adCntPerCampaign，{mode} 模式下此字段必填，"
            "请先调用 save_choose_params.py 将圈选参数写入文件后再执行本脚本"
        )
    else:
        try:
            ad_cnt = int(ad_cnt_raw)
            if ad_cnt <= 0:
                errors.append(f"adCntPerCampaign 必须大于 0，当前值：{ad_cnt}")
        except (ValueError, TypeError):
            errors.append(f"adCntPerCampaign 必须是整数，当前值：{ad_cnt_raw}")

    if errors:
        return {"step": 2, "ok": False, "errors": errors,
                "publishStrategies": [], "materialStrategies": []}

    # ── 组装 materialStrategies（AUTO_LAYOUT_FROM_CHOOSE_ID）────────────────────
    layout_rules = {
        "adCntPerCampaign": ad_cnt,
        "materialCntPerAd": material_cnt,
    }
    if mode == "COPY_CAMPAIGN":
        layout_rules["campaignCntPerAdvertiser"] = campaign_cnt

    material_strategy = {
        "type": "AUTO_LAYOUT_FROM_CHOOSE_ID",
        "appId": app_id,
        "adPlatformId": ad_platform_id,
        "chooseId": [str(choose_id)],
        "distributionType": distribution_type,
        "layoutRules": layout_rules,
    }
    if isinstance(xingguang_context, dict):
        for field_name in ("xingGuangTaskId", "xingGuangTaskName", "filteringDesc"):
            value = xingguang_context.get(field_name)
            if value is not None and str(value).strip():
                material_strategy[field_name] = str(value).strip()

    result = {
        "step": 2,
        "ok": True,
        "errors": [],
        "publishStrategies": publish_strategies,
        "materialStrategies": [material_strategy],
    }

    return result


def load_step1_file(filepath: str) -> tuple:
    """
    从阶段一输出文件中读取 publishStrategies、distributionType、chooseParams 和 xingGuangContext。
    若文件中缺少对应字段，返回空值（由 merge() 负责报错）。
    """
    with open(filepath, "r", encoding="utf-8") as f:
        data = json.load(f)
    if not isinstance(data, dict):
        raise ValueError(
            f"step1 文件格式不符合预期，应为 JSON 对象，实际：{type(data)}"
        )
    return (
        data.get("publishStrategies", []),
        data.get("distributionType"),
        data.get("chooseParams", {}),
        data.get("xingGuangContext", {}),
    )


def write_output(result: dict, output_dir: str) -> str:
    """将结果写入文件，返回文件路径。"""
    os.makedirs(output_dir, exist_ok=True)
    timestamp = datetime.now().strftime("%Y%m%d%H%M%S")
    uid_suffix = uuid.uuid4().hex[-4:]
    filename = f"xingguang_publish_state_2_{timestamp}_{uid_suffix}.json"
    filepath = os.path.join(output_dir, filename)
    with open(filepath, "w", encoding="utf-8") as f:
        json.dump(result, f, ensure_ascii=False, indent=2)
    return filepath


def main():
    if len(sys.argv) < 3:
        print(json.dumps({
            "step": 2,
            "ok": False,
            "errors": ["用法：python merge_xingguang_params.py <step1_file_path> <output_dir>"],
            "publishStrategies": [], "materialStrategies": []
        }, ensure_ascii=False))
        sys.exit(1)

    step1_file = sys.argv[1]
    output_dir = sys.argv[2]

    # ── 读取阶段一文件 ──────────────────────────────────────────────────────────
    try:
        publish_strategies, distribution_type, choose_params, xingguang_context = load_step1_file(step1_file)
    except Exception as e:
        print(json.dumps({
            "step": 2, "ok": False,
            "errors": [f"读取 step1 文件失败：{e}"],
            "publishStrategies": [], "materialStrategies": []
        }, ensure_ascii=False))
        sys.exit(1)

    # ── 前置检查：distributionType 必须存在 ────────────────────────────────────
    if not distribution_type:
        print(json.dumps({
            "step": 2, "ok": False,
            "errors": [
                "状态文件中不存在 distributionType 字段。"
                "请确认脚本一（validate_and_build_params.py）已正确执行并传入了 distributionType 参数。"
            ],
            "publishStrategies": [], "materialStrategies": []
        }, ensure_ascii=False))
        sys.exit(1)

    # ── 前置检查：chooseParams 必须存在 ────────────────────────────────────────
    if not choose_params:
        print(json.dumps({
            "step": 2, "ok": False,
            "errors": [
                "状态文件中不存在 chooseParams 字段。"
                "请先调用 save_choose_params.py 将 chooseId、adCntPerCampaign、materialCntPerAd"
                "（以及 COPY_CAMPAIGN 需要的 campaignCntPerAdvertiser）写入文件，再执行本脚本。"
            ],
            "publishStrategies": [], "materialStrategies": []
        }, ensure_ascii=False))
        sys.exit(1)

    result = merge(publish_strategies, choose_params, distribution_type, xingguang_context)

    filepath = write_output(result, output_dir)
    result["output_file"] = filepath

    print(json.dumps(result, ensure_ascii=False, indent=2))
    sys.exit(0 if result["ok"] else 1)


if __name__ == "__main__":
    main()

