"""
runner.py
---------
星广联投批量发布统一脚本入口。

action=prepare:
  1. 使用 MCP 工具校验账户、广告组、广告计划 ID，并从 CSV 结果水合名称/媒体字段
  2. 解析或查询星图任务，调用素材圈选工具获取 chooseId
  3. 复用 validate_and_build_params.py 生成 step1 状态文件，并写入 chooseParams/xingGuangContext

action=merge:
  读取 step1 状态文件，复用 merge_xingguang_params.py 生成最终发布参数文件。
"""

from __future__ import annotations

import csv
import json
import re
import sys
from datetime import datetime
from pathlib import Path
from typing import Any

from orchestration.script_runtime.mcp import invoke_mcp_tool

import merge_xingguang_params
import validate_and_build_params


ALLOWED_MCP_TOOLS = {
    "agent_tool_filter_advertiser",
    "agent_tool_filter_ad",
    "agent_tool_batch_build_attribute",
    "agent_tool_channel_push_material_choose",
}

SUPPORTED_PLATFORM = "头条"
VALID_DISTRIBUTION_TYPES = {"EVEN", "ALL"}
DATE_RE = re.compile(r"^\d{4}-\d{2}-\d{2}$")


def _result(
    *,
    action: str,
    ok: bool,
    errors: list[str] | None = None,
    **extra: Any,
) -> dict[str, Any]:
    payload = {
        "ok": ok,
        "action": action,
        "errors": errors or [],
    }
    payload.update(extra)
    return payload


def _is_missing(value: Any) -> bool:
    return value is None or (isinstance(value, str) and not value.strip())


def _normalize_required_id(field_name: str, value: Any, errors: list[str]) -> str | None:
    if isinstance(value, bool) or _is_missing(value):
        errors.append(f"{field_name} 必须是纯数字 ID")
        return None
    if isinstance(value, int):
        number = value
    elif isinstance(value, str):
        text = value.strip()
        if not text.isdigit():
            errors.append(f"{field_name} 必须是纯数字 ID，当前值：{text}")
            return None
        number = int(text)
    else:
        errors.append(f"{field_name} 必须是纯数字 ID，当前值：{value}")
        return None
    if number <= 0:
        errors.append(f"{field_name} 必须是正整数 ID，当前值：{value}")
        return None
    return str(number)


def _normalize_optional_id(field_name: str, value: Any, errors: list[str]) -> str | None:
    if _is_missing(value):
        return None
    return _normalize_required_id(field_name, value, errors)


def _normalize_target_advertiser_ids(data: dict[str, Any], errors: list[str]) -> list[str]:
    raw_ids = data.get("targetAdvertiserIds")
    if not isinstance(raw_ids, list) or not raw_ids:
        errors.append("targetAdvertiserIds 必须是非空数组")
        return []

    normalized: list[str] = []
    for index, raw_id in enumerate(raw_ids):
        advertiser_id = _normalize_required_id(
            f"targetAdvertiserIds[{index}]",
            raw_id,
            errors,
        )
        if advertiser_id is not None:
            normalized.append(advertiser_id)
    return normalized


def _dedupe(values: list[str]) -> list[str]:
    deduped: list[str] = []
    seen: set[str] = set()
    for value in values:
        if value in seen:
            continue
        seen.add(value)
        deduped.append(value)
    return deduped


def _parse_json_payload(value: Any) -> Any:
    if isinstance(value, (dict, list)):
        return value
    if value is None:
        return None
    if not isinstance(value, str):
        return value
    text = value.strip()
    if not text:
        return ""
    if text.startswith("{") or text.startswith("["):
        return json.loads(text)
    return text


def _invoke_json_tool(tool_name: str, arguments: dict[str, Any]) -> Any:
    output = invoke_mcp_tool(
        tool_name,
        arguments,
        allowed_tools=ALLOWED_MCP_TOOLS,
    )
    return _parse_json_payload(output)


def _has_non_empty_value(value: Any) -> bool:
    if value is None:
        return False
    if isinstance(value, str):
        return bool(value.strip())
    if isinstance(value, list):
        return any(_has_non_empty_value(item) for item in value)
    if isinstance(value, dict):
        return any(_has_non_empty_value(item) for item in value.values())
    return True


def _normalize_ids_text(value: Any) -> str | None:
    if isinstance(value, str):
        return value.strip() or None
    if not isinstance(value, list):
        return None
    parts: list[str] = []
    seen: set[str] = set()
    for item in value:
        if not isinstance(item, (str, int, float)):
            continue
        text = str(item).strip()
        if not text or text in seen:
            continue
        seen.add(text)
        parts.append(text)
    return "、".join(parts) if parts else None


def _field(payload: Any, field_name: str) -> Any:
    if isinstance(payload, dict):
        if field_name in payload:
            return payload[field_name]
        for value in payload.values():
            found = _field(value, field_name)
            if found is not None:
                return found
    if isinstance(payload, list):
        for item in payload:
            found = _field(item, field_name)
            if found is not None:
                return found
    return None


def _payload_has_empty_result(payload: Any) -> bool:
    if payload is None:
        return True
    if isinstance(payload, list):
        return len(payload) == 0
    if isinstance(payload, dict):
        if not payload:
            return True
        for key in ("data", "list", "preview_rows"):
            if key in payload and isinstance(payload[key], list) and not payload[key]:
                return True
    return False


def _csv_path_from_payload(payload: Any, tool_name: str, errors: list[str]) -> Path | None:
    if not isinstance(payload, dict):
        errors.append(f"{tool_name} 返回值不是对象，无法读取 csv_path")
        return None
    raw_csv_path = payload.get("csv_path")
    if _is_missing(raw_csv_path):
        if _payload_has_empty_result(payload):
            errors.append(f"{tool_name} 返回为空，无法完成 ID 校验")
        else:
            errors.append(f"{tool_name} 未返回 csv_path，无法读取校验结果")
        return None
    csv_path = Path(str(raw_csv_path)).expanduser()
    if not csv_path.exists() or not csv_path.is_file():
        errors.append(f"{tool_name} 返回的 csv_path 不存在：{csv_path}")
        return None
    return csv_path


def _read_csv_rows(csv_path: Path) -> list[dict[str, str]]:
    with csv_path.open("r", encoding="utf-8-sig", newline="") as file:
        reader = csv.DictReader(file)
        return [
            {str(key or "").strip(): str(value or "").strip() for key, value in row.items()}
            for row in reader
        ]


def _row_value(row: dict[str, str], *field_names: str) -> str:
    normalized = {
        key.replace("_", "").lower(): value
        for key, value in row.items()
    }
    for field_name in field_names:
        value = normalized.get(field_name.replace("_", "").lower())
        if value:
            return value
    return ""


def _dict_rows_from_payload(payload: Any) -> list[dict[str, Any]]:
    if isinstance(payload, dict):
        rows: list[dict[str, Any]] = []
        for key in ("preview_rows", "data", "list", "rows"):
            value = payload.get(key)
            if isinstance(value, list):
                rows.extend(item for item in value if isinstance(item, dict))
            elif isinstance(value, dict):
                rows.append(value)
        return rows
    if isinstance(payload, list):
        return [item for item in payload if isinstance(item, dict)]
    return []


def _positive_int_field(field_name: str, value: Any, errors: list[str]) -> int | None:
    if isinstance(value, bool) or _is_missing(value):
        errors.append(f"{field_name} 必须是正整数")
        return None
    try:
        number = int(str(value).strip())
    except (TypeError, ValueError):
        errors.append(f"{field_name} 必须是正整数，当前值：{value}")
        return None
    if number <= 0:
        errors.append(f"{field_name} 必须是正整数，当前值：{value}")
        return None
    return number


def _load_advertisers(advertiser_ids: list[str], errors: list[str]) -> dict[str, dict[str, Any]]:
    payload = _invoke_json_tool(
        "agent_tool_filter_advertiser",
        {"reqParam": {"advertiserIds": advertiser_ids}},
    )
    advertiser_id_error = _field(payload, "advertiserIdError")
    if _has_non_empty_value(advertiser_id_error):
        ids_text = _normalize_ids_text(advertiser_id_error) or "、".join(advertiser_ids)
        errors.append(f"账户 ID [{ids_text}] 不存在或无权限，请重新确认后提供正确的 ID。")
        return {}

    csv_path = _csv_path_from_payload(payload, "agent_tool_filter_advertiser", errors)
    if csv_path is None:
        return {}

    rows = _read_csv_rows(csv_path)
    advertisers: dict[str, dict[str, Any]] = {}
    for row in rows:
        advertiser_id = _row_value(row, "advertiserId")
        if not advertiser_id:
            continue
        advertisers[advertiser_id] = {
            "advertiserId": advertiser_id,
            "advertiserName": _row_value(row, "advertiserName"),
            "appId": _row_value(row, "appId"),
            "adPlatformId": _row_value(row, "adPlatformId"),
            "adPlatformName": _row_value(row, "adPlatformName"),
        }

    missing = [advertiser_id for advertiser_id in advertiser_ids if advertiser_id not in advertisers]
    if missing:
        errors.append(f"账户 ID [{'、'.join(missing)}] 不存在或无权限，请重新确认后提供正确的 ID。")
        return {}

    for advertiser_id in advertiser_ids:
        advertiser = advertisers[advertiser_id]
        if not advertiser["advertiserName"]:
            errors.append(f"账户 ID [{advertiser_id}] 校验结果缺少 advertiserName")
        app_id = _positive_int_field(f"账户 {advertiser_id}.appId", advertiser["appId"], errors)
        ad_platform_id = _positive_int_field(
            f"账户 {advertiser_id}.adPlatformId",
            advertiser["adPlatformId"],
            errors,
        )
        if app_id is not None:
            advertiser["appId"] = app_id
        if ad_platform_id is not None:
            advertiser["adPlatformId"] = ad_platform_id
        if advertiser["adPlatformName"] != SUPPORTED_PLATFORM:
            errors.append(
                f"账户 [{advertiser_id}] 所属平台为「{advertiser['adPlatformName'] or '<empty>'}」，"
                f"当前星广联投批量发布功能仅支持{SUPPORTED_PLATFORM}平台，暂不支持其他媒体平台。"
            )
    return advertisers


def _ensure_single_app_and_media(advertisers: list[dict[str, Any]], errors: list[str]) -> None:
    app_ids = {advertiser.get("appId") for advertiser in advertisers}
    platform_ids = {advertiser.get("adPlatformId") for advertiser in advertisers}
    if len(app_ids) > 1:
        errors.append(f"目标账户与模板账户的 appId 必须一致，当前存在多个值：{app_ids}")
    if len(platform_ids) > 1:
        errors.append(f"目标账户与模板账户的 adPlatformId 必须一致，当前存在多个值：{platform_ids}")


def _load_campaign_attributes(
    campaign_ids: list[str],
    errors: list[str],
    campaign_attribute_cache: dict[str, dict[str, str]],
) -> dict[str, dict[str, str]]:
    missing_ids = [campaign_id for campaign_id in _dedupe(campaign_ids) if campaign_id not in campaign_attribute_cache]
    if missing_ids:
        payload = _invoke_json_tool(
            "agent_tool_batch_build_attribute",
            {
                "reqParam": {
                    "adPlatformId": 1,
                    "queryType": "campaign",
                    "ids": missing_ids,
                }
            },
        )

        rows = _dict_rows_from_payload(payload)
        if isinstance(payload, dict) and not rows and not _is_missing(payload.get("csv_path")):
            csv_path = Path(str(payload["csv_path"])).expanduser()
            if csv_path.exists() and csv_path.is_file():
                rows = _read_csv_rows(csv_path)
            else:
                errors.append(f"agent_tool_batch_build_attribute 返回的 csv_path 不存在：{csv_path}")

        for row in rows:
            normalized_row = {str(key): "" if value is None else str(value) for key, value in row.items()}
            campaign_id = _row_value(normalized_row, "id", "campaignId")
            if not campaign_id and len(missing_ids) == 1:
                campaign_id = missing_ids[0]
            if not campaign_id:
                continue
            campaign_attribute_cache[campaign_id] = {
                "name": _row_value(normalized_row, "name", "campaignName"),
                "starTaskId": _row_value(normalized_row, "starTaskId", "xingGuangTaskId"),
            }

    return {
        campaign_id: campaign_attribute_cache[campaign_id]
        for campaign_id in campaign_ids
        if campaign_id in campaign_attribute_cache
    }


def _load_ad_entities(
    *,
    advertiser_id: str,
    campaign_ids: list[str],
    ad_ids: list[str],
    errors: list[str],
    campaign_attribute_cache: dict[str, dict[str, str]],
) -> tuple[dict[str, str], dict[str, str]]:
    req_param: dict[str, Any] = {"advertiserIds": [advertiser_id]}
    if campaign_ids:
        req_param["campaignIds"] = campaign_ids
    if ad_ids:
        req_param["adIds"] = ad_ids

    payload = _invoke_json_tool("agent_tool_filter_ad", {"reqParam": req_param})

    campaign_id_error = _field(payload, "campaignIdError")
    if _has_non_empty_value(campaign_id_error):
        ids_text = _normalize_ids_text(campaign_id_error) or "、".join(campaign_ids)
        errors.append(
            f"广告组 ID [{ids_text}] 在账户 [{advertiser_id}] 下不存在，请重新确认后提供正确的 ID。"
        )
        return {}, {}

    ad_id_error = _field(payload, "adIdError")
    if _has_non_empty_value(ad_id_error):
        ids_text = _normalize_ids_text(ad_id_error) or "、".join(ad_ids)
        errors.append(
            f"广告计划 ID [{ids_text}] 在账户 [{advertiser_id}] 下不存在，请重新确认后提供正确的 ID。"
        )
        return {}, {}

    csv_path = _csv_path_from_payload(payload, "agent_tool_filter_ad", errors)
    if csv_path is None:
        return {}, {}

    campaign_names: dict[str, str] = {}
    ad_names: dict[str, str] = {}
    for row in _read_csv_rows(csv_path):
        campaign_id = _row_value(row, "campaignId")
        if campaign_id:
            campaign_names[campaign_id] = _row_value(row, "campaignName")
        ad_id = _row_value(row, "adId")
        if ad_id:
            ad_names[ad_id] = _row_value(row, "adName")

    campaigns_needing_names = [
        campaign_id for campaign_id in campaign_ids if campaign_id in campaign_names and not campaign_names[campaign_id]
    ]
    if campaigns_needing_names:
        attributes = _load_campaign_attributes(campaigns_needing_names, errors, campaign_attribute_cache)
        for campaign_id in campaigns_needing_names:
            name = attributes.get(campaign_id, {}).get("name", "")
            if name:
                campaign_names[campaign_id] = name

    missing_campaigns = [campaign_id for campaign_id in campaign_ids if campaign_id not in campaign_names]
    if missing_campaigns:
        errors.append(
            f"广告组 ID [{'、'.join(missing_campaigns)}] 在账户 [{advertiser_id}] 下不存在，请重新确认后提供正确的 ID。"
        )
    missing_campaign_names = [
        campaign_id for campaign_id in campaign_ids if campaign_id in campaign_names and not campaign_names[campaign_id]
    ]
    if missing_campaign_names:
        errors.append(
            f"广告组 ID [{'、'.join(missing_campaign_names)}] 校验结果缺少 campaignName，"
            "无法自动水合广告组名称，请检查工具返回数据。"
        )
    missing_ads = [ad_id for ad_id in ad_ids if ad_id not in ad_names]
    if missing_ads:
        errors.append(
            f"广告计划 ID [{'、'.join(missing_ads)}] 在账户 [{advertiser_id}] 下不存在，请重新确认后提供正确的 ID。"
        )
    return campaign_names, ad_names


def _load_template_ad(
    *,
    ad_platform_name: str,
    template_ad_id: str,
    errors: list[str],
) -> dict[str, Any] | None:
    payload = _invoke_json_tool(
        "agent_tool_filter_ad",
        {
            "reqParam": {
                "adPlatformNames": [ad_platform_name],
                "adIds": [template_ad_id],
            }
        },
    )
    ad_id_error = _field(payload, "adIdError")
    if _has_non_empty_value(ad_id_error):
        ids_text = _normalize_ids_text(ad_id_error) or template_ad_id
        errors.append(
            f"模板广告计划 ID [{ids_text}] 在媒体平台 [{ad_platform_name}] 下不存在或无权限。"
        )
        return None
    if _payload_has_empty_result(payload):
        errors.append(
            f"模板广告计划 ID [{template_ad_id}] 在媒体平台 [{ad_platform_name}] 下不存在或无权限。"
        )
        return None

    csv_path = _csv_path_from_payload(payload, "agent_tool_filter_ad", errors)
    if csv_path is None:
        return None

    matched_rows = [
        row
        for row in _read_csv_rows(csv_path)
        if _row_value(row, "adId") == template_ad_id
    ]
    mappings = {
        (_row_value(row, "advertiserId"), _row_value(row, "campaignId"))
        for row in matched_rows
    }
    if not matched_rows:
        errors.append(
            f"模板广告计划 ID [{template_ad_id}] 在媒体平台 [{ad_platform_name}] 下不存在或无权限。"
        )
        return None
    if len(mappings) != 1:
        errors.append(
            f"模板广告计划 ID [{template_ad_id}] 反查到多个账户或广告组，无法唯一确定模板。"
        )
        return None

    row = matched_rows[0]
    template = {
        "advertiserId": _row_value(row, "advertiserId"),
        "advertiserName": _row_value(row, "advertiserName"),
        "appId": _row_value(row, "appId"),
        "adPlatformId": _row_value(row, "adPlatformId"),
        "adPlatformName": _row_value(row, "adPlatformName"),
        "campaignId": _row_value(row, "campaignId"),
        "campaignName": _row_value(row, "campaignName"),
        "adId": template_ad_id,
        "adName": _row_value(row, "adName"),
    }
    for field_name in ("advertiserId", "advertiserName", "campaignId", "adPlatformName"):
        if not template[field_name]:
            errors.append(f"模板广告计划 ID [{template_ad_id}] 反查结果缺少 {field_name}")
    app_id = _positive_int_field("模板广告计划反查结果 appId", template["appId"], errors)
    ad_platform_id = _positive_int_field(
        "模板广告计划反查结果 adPlatformId",
        template["adPlatformId"],
        errors,
    )
    if template["adPlatformName"] and template["adPlatformName"] != ad_platform_name:
        errors.append(
            f"模板广告计划所属媒体为 [{template['adPlatformName']}]，与目标账户媒体 [{ad_platform_name}] 不一致。"
        )
    if errors:
        return None
    assert app_id is not None
    assert ad_platform_id is not None
    template["appId"] = app_id
    template["adPlatformId"] = ad_platform_id
    return template


def _normalize_create_time_range(data: dict[str, Any], errors: list[str]) -> list[str] | None:
    raw_range = data.get("createTimeRange")
    if not isinstance(raw_range, list) or len(raw_range) != 2:
        errors.append("createTimeRange 必须是长度为 2 的数组，格式为 ['YYYY-MM-DD', 'YYYY-MM-DD']")
        return None

    normalized: list[str] = []
    parsed_dates = []
    for index, raw_value in enumerate(raw_range):
        value = str(raw_value or "").strip()
        if not DATE_RE.match(value):
            errors.append(f"createTimeRange[{index}] 必须是 YYYY-MM-DD，当前值：{raw_value}")
            return None
        try:
            parsed_dates.append(datetime.strptime(value, "%Y-%m-%d"))
        except ValueError:
            errors.append(f"createTimeRange[{index}] 不是有效日期，当前值：{raw_value}")
            return None
        normalized.append(value)

    if parsed_dates[0] > parsed_dates[1]:
        errors.append("createTimeRange 开始日期不能晚于结束日期")
        return None
    return normalized


def _task_id_from_attribute(payload: Any) -> str | None:
    for field_name in ("starTaskId", "xingGuangTaskId"):
        value = _field(payload, field_name)
        if _has_non_empty_value(value):
            if isinstance(value, list):
                for item in value:
                    text = str(item or "").strip()
                    if text:
                        return text
            return str(value).strip()
    return None


def _resolve_xingguang_task(
    data: dict[str, Any],
    *,
    campaign_id_for_default_task: str,
    errors: list[str],
    campaign_attribute_cache: dict[str, dict[str, str]],
) -> dict[str, str] | None:
    task_id = _normalize_optional_id("xingGuangTaskId", data.get("xingGuangTaskId"), errors)
    task_name = str(data.get("xingGuangTaskName") or "").strip()

    if task_id and task_name:
        errors.append("xingGuangTaskId 和 xingGuangTaskName 只能二选一传入")
        return None
    if errors:
        return None
    if task_id:
        return {"field": "xingGuangTaskId", "value": task_id, "source": "provided_id"}
    if task_name:
        return {"field": "xingGuangTaskName", "value": task_name, "source": "provided_name"}

    attributes = _load_campaign_attributes([campaign_id_for_default_task], errors, campaign_attribute_cache)
    if errors:
        return None
    default_task_id = attributes.get(campaign_id_for_default_task, {}).get("starTaskId")
    if not default_task_id:
        errors.append("未查询到模板广告组绑定的星图任务，请手动提供任务 ID 或任务名称")
        return None
    if not default_task_id.isdigit():
        errors.append(f"模板广告组绑定的星图任务 ID 非法：{default_task_id}")
        return None
    return {"field": "xingGuangTaskId", "value": default_task_id, "source": "template_campaign"}


def _filtering_desc(task: dict[str, str], create_time_range: list[str]) -> str:
    label = "星广任务ID" if task["field"] == "xingGuangTaskId" else "星广任务名称"
    return f"数据类型[xingGuang] {label}[{task['value']}] 创建时间[{create_time_range[0]}, {create_time_range[1]}]"


def _choose_id_from_payload(payload: Any, errors: list[str]) -> int | None:
    payload_text = payload if isinstance(payload, str) else json.dumps(payload, ensure_ascii=False)
    if "HTTP 404" in payload_text:
        errors.append("当前素材圈选接口暂时不可用，请等待重试。")
        return None
    if isinstance(payload, dict):
        message = str(payload.get("msg") or payload.get("message") or "").strip()
        code = payload.get("code")
        if code not in (None, 0) and message:
            if "没有筛选到素材" in message:
                errors.append(f"{message}。请重新提供素材筛选逻辑。")
            else:
                errors.append(message)
            return None

    choose_id = _field(payload, "chooseId")
    if not _has_non_empty_value(choose_id):
        if "没有筛选到素材" in payload_text:
            errors.append("当前筛选条件下未找到素材圈选记录，请调整条件后重试")
        else:
            errors.append("agent_tool_channel_push_material_choose 未返回有效 chooseId")
        return None

    if isinstance(choose_id, list):
        choose_id = next((item for item in choose_id if _has_non_empty_value(item)), None)
    try:
        normalized = int(str(choose_id).strip())
    except (TypeError, ValueError):
        errors.append(f"chooseId 必须是正整数，当前值：{choose_id}")
        return None
    if normalized <= 0:
        errors.append(f"chooseId 必须是正整数，当前值：{choose_id}")
        return None
    return normalized


def _choose_materials(
    *,
    app_id: int,
    task: dict[str, str],
    create_time_range: list[str],
    errors: list[str],
) -> tuple[int | None, dict[str, Any] | None]:
    filtering = [
        {"field": "dataType", "operator": "EQUALS", "values": ["xingGuang"]},
        {"field": "appId", "operator": "EQUALS", "values": [app_id]},
        {"field": task["field"], "operator": "EQUALS", "values": [task["value"]]},
        {"field": "createTime", "operator": "BETWEEN", "values": create_time_range},
    ]
    payload = _invoke_json_tool(
        "agent_tool_channel_push_material_choose",
        {"reqParam": {"filtering": filtering}},
    )
    choose_id = _choose_id_from_payload(payload, errors)
    if choose_id is None:
        return None, None
    context: dict[str, Any] = {
        "filtering": filtering,
        "filteringDesc": _filtering_desc(task, create_time_range),
    }
    if task["field"] == "xingGuangTaskId":
        context["xingGuangTaskId"] = task["value"]
    else:
        context["xingGuangTaskName"] = task["value"]
    return choose_id, context


def _copy_optional_fields(source: dict[str, Any], target: dict[str, Any]) -> None:
    if "adAttrStrategy" in source:
        target["adAttrStrategy"] = source["adAttrStrategy"]


def _build_prepare_data(data: dict[str, Any]) -> dict[str, Any]:
    errors: list[str] = []
    mode = str(data.get("mode") or "").strip().upper()
    target_advertiser_ids = _normalize_target_advertiser_ids(data, errors)
    create_time_range = _normalize_create_time_range(data, errors)

    if mode not in {"COPY_CAMPAIGN", "APPEND_AD"}:
        errors.append(f"mode 字段无效：'{mode}'，必须是 COPY_CAMPAIGN 或 APPEND_AD")

    target_campaign_id = None
    template_ad_id = _normalize_required_id("templateAdId", data.get("templateAdId"), errors)

    campaign_cnt = None
    if mode == "COPY_CAMPAIGN":
        distribution_type = str(data.get("distributionType") or "").strip().upper()
        if distribution_type not in VALID_DISTRIBUTION_TYPES:
            errors.append("COPY_CAMPAIGN 模式必须传入 distributionType，且只能是 EVEN 或 ALL")
        campaign_cnt = _positive_int_field(
            "campaignCntPerAdvertiser",
            data.get("campaignCntPerAdvertiser"),
            errors,
        )
    else:
        distribution_type = "EVEN"
        if len(target_advertiser_ids) > 1:
            errors.append("APPEND_AD 模式仅支持单个目标账户")
        target_campaign_id = _normalize_required_id(
            "targetCampaignId",
            data.get("targetCampaignId"),
            errors,
        )

    ad_cnt = _positive_int_field("adCntPerCampaign", data.get("adCntPerCampaign"), errors)
    material_cnt = _positive_int_field("materialCntPerAd", data.get("materialCntPerAd"), errors)

    if errors:
        return _result(action="prepare", ok=False, errors=errors)
    assert create_time_range is not None

    advertisers = _load_advertisers(_dedupe(target_advertiser_ids), errors)
    if errors:
        return _result(action="prepare", ok=False, errors=errors)
    _ensure_single_app_and_media(
        [advertisers[advertiser_id] for advertiser_id in _dedupe(target_advertiser_ids)],
        errors,
    )
    if errors:
        return _result(action="prepare", ok=False, errors=errors)

    campaign_attribute_cache: dict[str, dict[str, str]] = {}
    campaign_names: dict[str, str] = {}
    if mode == "APPEND_AD":
        assert target_campaign_id is not None
        target_advertiser_id = target_advertiser_ids[0]
        campaign_names, _ = _load_ad_entities(
            advertiser_id=target_advertiser_id,
            campaign_ids=[target_campaign_id],
            ad_ids=[],
            errors=errors,
            campaign_attribute_cache=campaign_attribute_cache,
        )
        if errors:
            return _result(action="prepare", ok=False, errors=errors)

    target_platform_name = str(advertisers[target_advertiser_ids[0]].get("adPlatformName") or "").strip()
    if not target_platform_name:
        return _result(
            action="prepare",
            ok=False,
            errors=["目标账户校验结果缺少 adPlatformName，无法反查模板广告计划"],
        )
    assert template_ad_id is not None
    template = _load_template_ad(
        ad_platform_name=target_platform_name,
        template_ad_id=template_ad_id,
        errors=errors,
    )
    if errors or template is None:
        return _result(action="prepare", ok=False, errors=errors)
    if not template["campaignName"]:
        attributes = _load_campaign_attributes(
            [template["campaignId"]],
            errors,
            campaign_attribute_cache,
        )
        template["campaignName"] = attributes.get(template["campaignId"], {}).get("name", "")
        if not template["campaignName"]:
            errors.append(f"模板广告计划 ID [{template_ad_id}] 反查结果缺少 campaignName")
    _ensure_single_app_and_media(
        [advertisers[advertiser_id] for advertiser_id in _dedupe(target_advertiser_ids)] + [template],
        errors,
    )
    if errors:
        return _result(action="prepare", ok=False, errors=errors)

    accounts: list[dict[str, Any]] = []
    if mode == "COPY_CAMPAIGN":
        task_campaign_id = template["campaignId"]
        for target_advertiser_id in target_advertiser_ids:
            target_advertiser = advertisers[target_advertiser_id]
            accounts.append(
                {
                    "advertiserId": target_advertiser["advertiserId"],
                    "advertiserName": target_advertiser["advertiserName"],
                    "appId": target_advertiser["appId"],
                    "adPlatformId": target_advertiser["adPlatformId"],
                    "adPlatformName": target_advertiser["adPlatformName"],
                    "templateAdvertiserId": template["advertiserId"],
                    "templateAdvertiserName": template["advertiserName"],
                    "tempAdPlatformName": template["adPlatformName"],
                    "templateCampaignId": template["campaignId"],
                    "templateCampaignName": template["campaignName"],
                    "templateAdId": template_ad_id,
                    "templateAdName": template["adName"],
                }
            )
    else:
        assert target_campaign_id is not None
        target_advertiser_id = target_advertiser_ids[0]
        task_campaign_id = target_campaign_id
        target_advertiser = advertisers[target_advertiser_id]
        accounts.append(
            {
                "advertiserId": target_advertiser["advertiserId"],
                "advertiserName": target_advertiser["advertiserName"],
                "appId": target_advertiser["appId"],
                "adPlatformId": target_advertiser["adPlatformId"],
                "adPlatformName": target_advertiser["adPlatformName"],
                "templateAdvertiserId": template["advertiserId"],
                "templateAdvertiserName": template["advertiserName"],
                "tempAdPlatformName": template["adPlatformName"],
                "targetCampaignId": target_campaign_id,
                "targetCampaignName": campaign_names[target_campaign_id],
                "templateAdId": template_ad_id,
                "templateAdName": template["adName"],
            }
        )

    task = _resolve_xingguang_task(
        data,
        campaign_id_for_default_task=task_campaign_id,
        errors=errors,
        campaign_attribute_cache=campaign_attribute_cache,
    )
    if errors or task is None:
        return _result(action="prepare", ok=False, errors=errors)

    choose_id, xingguang_context = _choose_materials(
        app_id=accounts[0]["appId"],
        task=task,
        create_time_range=create_time_range,
        errors=errors,
    )
    if errors or choose_id is None or xingguang_context is None:
        return _result(action="prepare", ok=False, errors=errors)

    prepared = {
        "mode": mode,
        "distributionType": distribution_type,
        "accounts": accounts,
        "chooseParams": {
            "chooseId": choose_id,
            "adCntPerCampaign": ad_cnt,
            "materialCntPerAd": material_cnt,
        },
        "xingGuangContext": xingguang_context,
    }
    if mode == "COPY_CAMPAIGN":
        prepared["chooseParams"]["campaignCntPerAdvertiser"] = campaign_cnt
    _copy_optional_fields(data, prepared)
    return prepared


def _write_step1_result(result: dict[str, Any], output_dir: str) -> dict[str, Any]:
    filepath = validate_and_build_params.write_output(result, output_dir)
    result["output_file"] = filepath
    with open(filepath, "w", encoding="utf-8") as file:
        json.dump(result, file, ensure_ascii=False, indent=2)
    return result


def prepare(data: dict[str, Any], output_dir: str) -> dict[str, Any]:
    prepared = _build_prepare_data(data)
    if not prepared.get("ok", True):
        return prepared

    choose_params = prepared.pop("chooseParams")
    xingguang_context = prepared.pop("xingGuangContext")
    validation_result = validate_and_build_params.validate(prepared)
    if validation_result.get("ok"):
        validation_result["chooseParams"] = choose_params
        validation_result["xingGuangContext"] = xingguang_context

    validation_result = _write_step1_result(validation_result, output_dir)
    validation_result["action"] = "prepare"
    validation_result["next_action"] = "runner_merge" if validation_result.get("ok") else None
    return validation_result


def merge(data: dict[str, Any], output_dir: str) -> dict[str, Any]:
    step1_file = str(data.get("step1File") or "").strip()
    if not step1_file:
        return _result(action="merge", ok=False, errors=["step1File 是必填字段"])

    try:
        (
            publish_strategies,
            distribution_type,
            choose_params,
            xingguang_context,
        ) = merge_xingguang_params.load_step1_file(step1_file)
    except Exception as exc:  # noqa: BLE001
        return _result(action="merge", ok=False, errors=[f"读取 step1 文件失败：{exc}"])

    result = merge_xingguang_params.merge(
        publish_strategies=publish_strategies,
        choose_params=choose_params,
        distribution_type=distribution_type,
        xingguang_context=xingguang_context,
    )
    output_file = merge_xingguang_params.write_output(result, output_dir)
    result["output_file"] = output_file
    result["action"] = "merge"
    result["next_action"] = "agent_tool_batch_build_validate" if result.get("ok") else None
    return result


def run(data: dict[str, Any], output_dir: str) -> dict[str, Any]:
    action = str(data.get("action") or "").strip().lower()
    if action == "prepare":
        return prepare(data, output_dir)
    if action == "merge":
        return merge(data, output_dir)
    return _result(
        action=action or "unknown",
        ok=False,
        errors=["action 必须是 prepare 或 merge"],
    )


def main() -> None:
    if len(sys.argv) < 3:
        print(json.dumps(
            _result(
                action="unknown",
                ok=False,
                errors=["用法：python runner.py '<json_string>' <output_dir>"],
            ),
            ensure_ascii=False,
        ))
        sys.exit(1)

    output_dir = sys.argv[2]
    try:
        data = json.loads(sys.argv[1])
    except json.JSONDecodeError as exc:
        print(json.dumps(
            _result(action="unknown", ok=False, errors=[f"JSON 解析失败：{exc}"]),
            ensure_ascii=False,
        ))
        sys.exit(1)

    if not isinstance(data, dict):
        result = _result(action="unknown", ok=False, errors=["输入 JSON 顶层必须是对象"])
    else:
        result = run(data, output_dir)

    print(json.dumps(result, ensure_ascii=False, indent=2))
    sys.exit(0 if result.get("ok") else 1)


if __name__ == "__main__":
    main()

