"""
save_choose_params.py
─────────────────────
阶段一点五：素材圈选完成后，将 chooseId + 数量配置持久化写入状态文件。

背景：
  脚本一（validate_and_build_params.py）在素材圈选之前执行，此时 chooseId 尚未确定，
  无法一并写入。本脚本在 Agent 拿到 chooseId 后立即调用，把圈选参数追加写入
  脚本一产出的状态文件，确保后续脚本三（merge_xingguang_params.py）只需读文件，
  不再依赖 Agent 口头传参，避免多轮对话后参数被遗忘或错用。

用法：
  python save_choose_params.py <step1_file_path> '<choose_params_json>'

参数说明：
  step1_file_path      脚本一输出的 JSON 文件绝对路径（output_file 字段的值）。
                       脚本会在原文件上追加写入 chooseParams 字段，不新建文件。

  choose_params_json   圈选参数 JSON 字符串，结构如下：

    COPY_CAMPAIGN 模式：
    {
      "chooseId": 5114731350,         // 必填，正整数，来自 agent_tool_channel_push_material_choose
      "campaignCntPerAdvertiser": 2,  // COPY_CAMPAIGN 时必填，每个目标账户复制几个广告组，必须 > 0
      "adCntPerCampaign": 5,          // COPY_CAMPAIGN 时必填，每个广告组下建几条计划，必须 > 0
      "materialCntPerAd": 3           // 必填，每条计划下几个素材，必须 > 0
    }

    APPEND_AD 模式：
    {
      "chooseId": 5114731350,         // 必填
      "adCntPerCampaign": 5,          // APPEND_AD 时也必填，每个广告组下建几条计划，必须 > 0
      "materialCntPerAd": 3           // 必填
      // campaignCntPerAdvertiser 不传
    }

输出（stdout）：
{
  "ok": true,
  "output_file": "/path/to/xingguang_publish_state_1_xxx.json",
  "chooseParams": {
    "chooseId": 5114731350,
    "campaignCntPerAdvertiser": 2,
    "adCntPerCampaign": 5,
    "materialCntPerAd": 3
  }
}

写入后，状态文件新增字段示例（COPY_CAMPAIGN）：
{
  "step": 1,
  "ok": true,
  "publishStrategies": [...],
  "chooseParams": {
    "chooseId": 5114731350,
    "campaignCntPerAdvertiser": 2,
    "adCntPerCampaign": 5,
    "materialCntPerAd": 3
  },
  "output_file": "..."
}
"""

import json
import sys


def main():
    if len(sys.argv) < 3:
        print(json.dumps({
            "ok": False,
            "error": "用法：python save_choose_params.py <step1_file_path> '<choose_params_json>'"
        }, ensure_ascii=False))
        sys.exit(1)

    step1_file = sys.argv[1]
    choose_params_raw = sys.argv[2]

    # ── 解析圈选参数 ────────────────────────────────────────────────────────────
    try:
        choose_params = json.loads(choose_params_raw)
    except json.JSONDecodeError as e:
        print(json.dumps({"ok": False, "error": f"圈选参数 JSON 解析失败：{e}"}, ensure_ascii=False))
        sys.exit(1)

    # ── 读取脚本一状态文件 ──────────────────────────────────────────────────────
    try:
        with open(step1_file, "r", encoding="utf-8") as f:
            state = json.load(f)
    except Exception as e:
        print(json.dumps({"ok": False, "error": f"读取 step1 文件失败：{e}"}, ensure_ascii=False))
        sys.exit(1)

    publish_strategies = state.get("publishStrategies", [])
    if not publish_strategies:
        print(json.dumps({
            "ok": False,
            "errors": ["step1 文件缺少 publishStrategies，无法判断发布模式"]
        }, ensure_ascii=False))
        sys.exit(1)

    mode = str(publish_strategies[0].get("type", "")).upper()
    if mode not in ("COPY_CAMPAIGN", "APPEND_AD"):
        print(json.dumps({
            "ok": False,
            "errors": [f"step1 文件中的发布模式无效：{mode or '<empty>'}"]
        }, ensure_ascii=False))
        sys.exit(1)

    # ── 基础校验 ────────────────────────────────────────────────────────────────
    errors = []

    # chooseId：必填
    choose_id = choose_params.get("chooseId")
    if choose_id is None:
        errors.append("chooseId 为必填项")
    else:
        try:
            choose_id = int(choose_id)
            if choose_id <= 0:
                errors.append(f"chooseId 必须是正整数，当前值：{choose_id}")
        except (ValueError, TypeError):
            errors.append(f"chooseId 必须是整数，当前值：{choose_params.get('chooseId')}")

    # materialCntPerAd：必填
    material_cnt = choose_params.get("materialCntPerAd")
    if material_cnt is None:
        errors.append("materialCntPerAd 为必填项")
    else:
        try:
            material_cnt = int(material_cnt)
            if material_cnt <= 0:
                errors.append(f"materialCntPerAd 必须大于 0，当前值：{material_cnt}")
        except (ValueError, TypeError):
            errors.append(f"materialCntPerAd 必须是整数，当前值：{choose_params.get('materialCntPerAd')}")

    # campaignCntPerAdvertiser：仅 COPY_CAMPAIGN 时必填
    campaign_cnt_raw = choose_params.get("campaignCntPerAdvertiser")
    campaign_cnt = None
    if mode == "COPY_CAMPAIGN":
        if campaign_cnt_raw is None:
            errors.append("COPY_CAMPAIGN 模式下 campaignCntPerAdvertiser 为必填项")
        else:
            try:
                campaign_cnt = int(campaign_cnt_raw)
                if campaign_cnt <= 0:
                    errors.append(f"campaignCntPerAdvertiser 必须大于 0，当前值：{campaign_cnt}")
            except (ValueError, TypeError):
                errors.append(f"campaignCntPerAdvertiser 必须是整数，当前值：{campaign_cnt_raw}")
    elif campaign_cnt_raw is not None:
        errors.append("APPEND_AD 模式下禁止填写 campaignCntPerAdvertiser")

    # adCntPerCampaign：两种模式都必填
    ad_cnt_raw = choose_params.get("adCntPerCampaign")
    ad_cnt = None
    if ad_cnt_raw is None:
        errors.append(f"{mode} 模式下 adCntPerCampaign 为必填项")
    else:
        try:
            ad_cnt = int(ad_cnt_raw)
            if ad_cnt <= 0:
                errors.append(f"adCntPerCampaign 必须大于 0，当前值：{ad_cnt}")
        except (ValueError, TypeError):
            errors.append(f"adCntPerCampaign 必须是整数，当前值：{ad_cnt_raw}")

    if errors:
        print(json.dumps({"ok": False, "errors": errors}, ensure_ascii=False))
        sys.exit(1)

    # ── 组装并写入 chooseParams ─────────────────────────────────────────────────
    saved_params = {
        "chooseId": choose_id,
        "adCntPerCampaign": ad_cnt,
        "materialCntPerAd": material_cnt,
    }
    if campaign_cnt is not None:
        saved_params["campaignCntPerAdvertiser"] = campaign_cnt

    state["chooseParams"] = saved_params

    try:
        with open(step1_file, "w", encoding="utf-8") as f:
            json.dump(state, f, ensure_ascii=False, indent=2)
    except Exception as e:
        print(json.dumps({"ok": False, "error": f"写入状态文件失败：{e}"}, ensure_ascii=False))
        sys.exit(1)

    print(json.dumps({
        "ok": True,
        "output_file": step1_file,
        "chooseParams": saved_params
    }, ensure_ascii=False, indent=2))
    sys.exit(0)


if __name__ == "__main__":
    main()

